export const questions: Question[] = [
  { id: "y2v2-001", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 01", difficulty: "Foundation", questionText: "Calculate the magnitude of the resultant of \\(\\mathbf{a} = 2\\mathbf{i} + \\mathbf{j} - \\mathbf{k}\\) and \\(\\mathbf{b} = -\\mathbf{i} + 3\\mathbf{j} + \\mathbf{k}\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["resultant", "magnitude"], workedSolution: { steps: [ { stepNumber: 1, description: "State the resultant as a sum", workingLatex: "\\mathbf{r} = \\mathbf{a} + \\mathbf{b}", explanation: "The resultant of two vectors is their vector sum, so we first add \\(\\mathbf{a}\\) and \\(\\mathbf{b}\\) before taking any magnitude. Do not attempt to add the separate magnitudes \\(|\\mathbf{a}|\\) and \\(|\\mathbf{b}|\\) — that is wrong." }, { stepNumber: 2, description: "Write out both vectors' components", workingLatex: "\\mathbf{a} = 2\\mathbf{i} + \\mathbf{j} - \\mathbf{k}, \\quad \\mathbf{b} = -\\mathbf{i} + 3\\mathbf{j} + \\mathbf{k}", explanation: "Listing the components lined up by \\(\\mathbf{i}, \\mathbf{j}, \\mathbf{k}\\) makes the like-for-like addition reliable and avoids mixing up signs." }, { stepNumber: 3, description: "Add the i-components", workingLatex: "2 + (-1) = 1", explanation: "Combine only the \\(\\mathbf{i}\\) terms; watch the sign of \\(\\mathbf{b}\\)'s component which is \\(-1\\), giving \\(1\\)." }, { stepNumber: 4, description: "Add the j-components", workingLatex: "1 + 3 = 4", explanation: "Combine only the \\(\\mathbf{j}\\) terms to get \\(4\\); keep these separate from the other directions." }, { stepNumber: 5, description: "Add the k-components", workingLatex: "-1 + 1 = 0", explanation: "The \\(\\mathbf{k}\\) terms cancel to \\(0\\), so the resultant lies in the \\(\\mathbf{i}\\,\\mathbf{j}\\)-plane. Do not drop the zero carelessly — confirm it really is zero." }, { stepNumber: 6, description: "Assemble the resultant vector", workingLatex: "\\mathbf{a} + \\mathbf{b} = \\mathbf{i} + 4\\mathbf{j} + 0\\mathbf{k}", explanation: "Collecting the three component sums gives the resultant \\(\\mathbf{i} + 4\\mathbf{j}\\)." }, { stepNumber: 7, description: "Apply the magnitude formula", workingLatex: "|\\mathbf{a} + \\mathbf{b}| = \\sqrt{1^2 + 4^2 + 0^2}", explanation: "The magnitude in 3D is the square root of the sum of the squared components, \\(\\sqrt{x^2+y^2+z^2}\\). Each component must be squared, never just summed." }, { stepNumber: 8, description: "Square each component", workingLatex: "= \\sqrt{1 + 16 + 0}", explanation: "Evaluating \\(1^2=1\\), \\(4^2=16\\), \\(0^2=0\\) keeps the arithmetic explicit and error-free." }, { stepNumber: 9, description: "Sum and take the root", workingLatex: "= \\sqrt{17}", explanation: "The sum \\(17\\) is not a perfect square, so the surd \\(\\sqrt{17}\\) is the exact final magnitude." } ], finalAnswer: "\\(\\sqrt{17}\\)." } },
  { id: "y2v2-002", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 02", difficulty: "Foundation", questionText: "Find \\(|\\mathbf{a}|\\) for \\(\\mathbf{a} = \\begin{pmatrix} 1 \\\\ 4 \\\\ 8 \\end{pmatrix}\\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["magnitude"], workedSolution: { steps: [ { stepNumber: 1, description: "Identify the components", workingLatex: "\\mathbf{a} = \\begin{pmatrix} 1 \\\\ 4 \\\\ 8 \\end{pmatrix}", explanation: "Read off the three components \\(1, 4, 8\\); the magnitude depends only on these numbers and not their order." }, { stepNumber: 2, description: "Write the magnitude formula", workingLatex: "|\\mathbf{a}| = \\sqrt{x^2 + y^2 + z^2}", explanation: "The length of a 3D vector is the root of the sum of squared components, an extension of Pythagoras. Each component must be squared first." }, { stepNumber: 3, description: "Substitute the components", workingLatex: "|\\mathbf{a}| = \\sqrt{1^2 + 4^2 + 8^2}", explanation: "Insert \\(1, 4, 8\\) into the formula, keeping each squared separately to avoid arithmetic slips." }, { stepNumber: 4, description: "Square each component", workingLatex: "= \\sqrt{1 + 16 + 64}", explanation: "Compute \\(1^2=1\\), \\(4^2=16\\), \\(8^2=64\\); a common slip is writing \\(8^2=16\\) instead of \\(64\\)." }, { stepNumber: 5, description: "Add the squared terms", workingLatex: "= \\sqrt{81}", explanation: "Summing \\(1+16+64\\) gives \\(81\\), which is a perfect square." }, { stepNumber: 6, description: "Take the square root", workingLatex: "= 9", explanation: "Since \\(81 = 9^2\\), the magnitude simplifies to the exact integer \\(9\\)." } ], finalAnswer: "9." } },
  { id: "y2v2-003", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 03", difficulty: "Foundation", questionText: "Find the distance between \\(A(1, 2, 3)\\) and \\(B(4, -2, 1)\\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["distance"], workedSolution: { steps: [ { stepNumber: 1, description: "State the displacement vector", workingLatex: "\\overrightarrow{AB} = \\mathbf{b} - \\mathbf{a}", explanation: "Distance between two points is the magnitude of the displacement vector from \\(A\\) to \\(B\\), found by subtracting position coordinates (end minus start)." }, { stepNumber: 2, description: "Write both position coordinates", workingLatex: "A(1, 2, 3), \\quad B(4, -2, 1)", explanation: "Lay out the coordinates so each axis can be subtracted independently; mind the negative \\(y\\)-coordinate of \\(B\\)." }, { stepNumber: 3, description: "Subtract the x-coordinates", workingLatex: "4 - 1 = 3", explanation: "The \\(x\\)-component of \\(\\overrightarrow{AB}\\) is \\(3\\); always do end minus start so the direction is correct." }, { stepNumber: 4, description: "Subtract the y-coordinates", workingLatex: "-2 - 2 = -4", explanation: "The \\(y\\)-component is \\(-4\\); subtracting from a negative is a common sign-error spot, so keep the minus." }, { stepNumber: 5, description: "Subtract the z-coordinates", workingLatex: "1 - 3 = -2", explanation: "The \\(z\\)-component is \\(-2\\); the sign will not matter once squared, but track it for correctness." }, { stepNumber: 6, description: "Apply the distance formula", workingLatex: "d = \\sqrt{3^2 + (-4)^2 + (-2)^2}", explanation: "Distance is the magnitude \\(\\sqrt{x^2+y^2+z^2}\\) of the displacement; squaring removes any sign concern." }, { stepNumber: 7, description: "Square each component", workingLatex: "= \\sqrt{9 + 16 + 4}", explanation: "Evaluate \\(3^2=9\\), \\((-4)^2=16\\), \\((-2)^2=4\\); remember a negative squared is positive." }, { stepNumber: 8, description: "Sum and take the root", workingLatex: "= \\sqrt{29}", explanation: "The total \\(29\\) is not a perfect square, so leave the answer as the exact surd \\(\\sqrt{29}\\)." } ], finalAnswer: "\\(\\sqrt{29}\\)." } },
  { id: "y2v2-004", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 04", difficulty: "Foundation", questionText: "Find the unit vector in the direction of \\(\\mathbf{a} = 6\\mathbf{i} - 2\\mathbf{j} + 3\\mathbf{k}\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["unit vector"], workedSolution: { steps: [ { stepNumber: 1, description: "State the unit-vector formula", workingLatex: "\\hat{\\mathbf{a}} = \\frac{\\mathbf{a}}{|\\mathbf{a}|}", explanation: "A unit vector is the original vector divided by its own magnitude, giving length \\(1\\) in the same direction. We must find \\(|\\mathbf{a}|\\) first." }, { stepNumber: 2, description: "Identify the components", workingLatex: "\\mathbf{a} = 6\\mathbf{i} - 2\\mathbf{j} + 3\\mathbf{k}", explanation: "The components are \\(6, -2, 3\\); keep the negative \\(\\mathbf{j}\\) component throughout." }, { stepNumber: 3, description: "Write the magnitude formula", workingLatex: "|\\mathbf{a}| = \\sqrt{6^2 + (-2)^2 + 3^2}", explanation: "Apply \\(\\sqrt{x^2+y^2+z^2}\\); squaring the components handles the negative sign automatically." }, { stepNumber: 4, description: "Square each component", workingLatex: "= \\sqrt{36 + 4 + 9}", explanation: "Compute \\(6^2=36\\), \\((-2)^2=4\\), \\(3^2=9\\), keeping terms separate to avoid mistakes." }, { stepNumber: 5, description: "Sum the squared terms", workingLatex: "= \\sqrt{49}", explanation: "Adding \\(36+4+9\\) gives \\(49\\), a perfect square — a good sign for a clean unit vector." }, { stepNumber: 6, description: "Take the magnitude", workingLatex: "|\\mathbf{a}| = 7", explanation: "Since \\(49 = 7^2\\), the magnitude is exactly \\(7\\)." }, { stepNumber: 7, description: "Divide the vector by its magnitude", workingLatex: "\\hat{\\mathbf{a}} = \\frac{1}{7}(6\\mathbf{i} - 2\\mathbf{j} + 3\\mathbf{k})", explanation: "Dividing each component by \\(7\\) gives the unit vector. Keeping the scalar \\(\\tfrac{1}{7}\\) outside is the tidiest exact form; do not round." } ], finalAnswer: "\\(\\tfrac{1}{7}(6\\mathbf{i} - 2\\mathbf{j} + 3\\mathbf{k})\\)." } },
  { id: "y2v2-005", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 05", difficulty: "Foundation", questionText: "A plane flies from \\(A(0, 0, 0)\\) to \\(B(8, 6, 0)\\) km. Find the distance.", marks: 2, examStyle: false, yearCreated: 2026, tags: ["applied", "distance"], workedSolution: { steps: [ { stepNumber: 1, description: "State the displacement vector", workingLatex: "\\overrightarrow{AB} = \\mathbf{b} - \\mathbf{a}", explanation: "The flight distance is the magnitude of the displacement from \\(A\\) to \\(B\\); subtract coordinates end minus start." }, { stepNumber: 2, description: "Write both coordinates", workingLatex: "A(0, 0, 0), \\quad B(8, 6, 0)", explanation: "Since \\(A\\) is the origin, the displacement equals \\(B\\)'s coordinates directly, but we show the subtraction for clarity." }, { stepNumber: 3, description: "Subtract each coordinate", workingLatex: "\\overrightarrow{AB} = (8 - 0,\\ 6 - 0,\\ 0 - 0) = (8, 6, 0)", explanation: "Each axis is subtracted independently, giving components \\(8, 6, 0\\); the zero \\(z\\)-component shows the flight is level." }, { stepNumber: 4, description: "Apply the distance formula", workingLatex: "d = \\sqrt{8^2 + 6^2 + 0^2}", explanation: "Distance is \\(\\sqrt{x^2+y^2+z^2}\\); include the \\(z\\)-term even though it is zero to keep the method general." }, { stepNumber: 5, description: "Square each component", workingLatex: "= \\sqrt{64 + 36 + 0}", explanation: "Compute \\(8^2=64\\), \\(6^2=36\\), \\(0^2=0\\); a careful square avoids the classic \\(8^2=16\\) slip." }, { stepNumber: 6, description: "Sum the squared terms", workingLatex: "= \\sqrt{100}", explanation: "Adding \\(64+36\\) gives \\(100\\), a perfect square." }, { stepNumber: 7, description: "Take the root and add units", workingLatex: "= 10 \\text{ km}", explanation: "Since \\(\\sqrt{100}=10\\), the distance is \\(10\\) km. Always restate the unit (km) since the problem is applied." } ], finalAnswer: "10 km." } },
  { id: "y2v2-006", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 06", difficulty: "Foundation", questionText: "Find \\(3\\mathbf{a} - 2\\mathbf{b}\\) for \\(\\mathbf{a} = (1, 2, -1)\\) and \\(\\mathbf{b} = (2, 0, 3)\\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["arithmetic"], workedSolution: { steps: [ { stepNumber: 1, description: "Write the target expression", workingLatex: "3\\mathbf{a} - 2\\mathbf{b}", explanation: "We need a linear combination; handle the two scalar multiples first, then subtract componentwise." }, { stepNumber: 2, description: "List both vectors", workingLatex: "\\mathbf{a} = (1, 2, -1), \\quad \\mathbf{b} = (2, 0, 3)", explanation: "Lay the components out so each axis can be processed independently; note the negative \\(z\\) of \\(\\mathbf{a}\\)." }, { stepNumber: 3, description: "Scale a by 3", workingLatex: "3\\mathbf{a} = (3, 6, -3)", explanation: "Multiply every component of \\(\\mathbf{a}\\) by \\(3\\); the negative \\(z\\) becomes \\(-3\\)." }, { stepNumber: 4, description: "Scale b by 2", workingLatex: "2\\mathbf{b} = (4, 0, 6)", explanation: "Multiply every component of \\(\\mathbf{b}\\) by \\(2\\); this is the quantity to be subtracted." }, { stepNumber: 5, description: "Subtract the x-components", workingLatex: "3 - 4 = -1", explanation: "Subtract \\(2\\mathbf{b}\\) from \\(3\\mathbf{a}\\) along \\(x\\), giving \\(-1\\)." }, { stepNumber: 6, description: "Subtract the y-components", workingLatex: "6 - 0 = 6", explanation: "The \\(y\\)-component of \\(2\\mathbf{b}\\) is \\(0\\), so the result stays \\(6\\)." }, { stepNumber: 7, description: "Subtract the z-components", workingLatex: "-3 - 6 = -9", explanation: "Subtracting \\(6\\) from \\(-3\\) gives \\(-9\\); subtracting from a negative is a common sign-error spot." }, { stepNumber: 8, description: "Assemble the result vector", workingLatex: "3\\mathbf{a} - 2\\mathbf{b} = (-1, 6, -9)", explanation: "Collecting the three component results gives the final vector \\((-1, 6, -9)\\)." } ], finalAnswer: "\\((-1, 6, -9)\\)." } },
  { id: "y2v2-007", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 07", difficulty: "Foundation", questionText: "Find the magnitude of \\(\\mathbf{a} + \\mathbf{b}\\) where \\(\\mathbf{a} = 2\\mathbf{i} + 3\\mathbf{j}\\), \\(\\mathbf{b} = \\mathbf{i} - \\mathbf{j} + 2\\mathbf{k}\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["magnitude"], workedSolution: { steps: [ { stepNumber: 1, description: "State the sum to find", workingLatex: "\\mathbf{s} = \\mathbf{a} + \\mathbf{b}", explanation: "Add the vectors first, then take the magnitude; never add magnitudes separately." }, { stepNumber: 2, description: "Write both vectors with all axes", workingLatex: "\\mathbf{a} = 2\\mathbf{i} + 3\\mathbf{j} + 0\\mathbf{k}, \\quad \\mathbf{b} = \\mathbf{i} - \\mathbf{j} + 2\\mathbf{k}", explanation: "Insert an explicit \\(0\\mathbf{k}\\) for \\(\\mathbf{a}\\) so the \\(\\mathbf{k}\\) components align and nothing is dropped." }, { stepNumber: 3, description: "Add the i-components", workingLatex: "2 + 1 = 3", explanation: "Combine the \\(\\mathbf{i}\\) terms to get \\(3\\)." }, { stepNumber: 4, description: "Add the j-components", workingLatex: "3 + (-1) = 2", explanation: "Combine the \\(\\mathbf{j}\\) terms, respecting the negative in \\(\\mathbf{b}\\), to get \\(2\\)." }, { stepNumber: 5, description: "Add the k-components", workingLatex: "0 + 2 = 2", explanation: "Combine the \\(\\mathbf{k}\\) terms; \\(\\mathbf{a}\\) contributes \\(0\\), so the result is \\(2\\)." }, { stepNumber: 6, description: "Assemble the resultant", workingLatex: "\\mathbf{a} + \\mathbf{b} = 3\\mathbf{i} + 2\\mathbf{j} + 2\\mathbf{k}", explanation: "Collecting the component sums gives the resultant vector." }, { stepNumber: 7, description: "Apply the magnitude formula", workingLatex: "|\\mathbf{a} + \\mathbf{b}| = \\sqrt{3^2 + 2^2 + 2^2}", explanation: "The magnitude is \\(\\sqrt{x^2+y^2+z^2}\\); square each component before summing." }, { stepNumber: 8, description: "Square each component", workingLatex: "= \\sqrt{9 + 4 + 4}", explanation: "Evaluate \\(3^2=9\\), \\(2^2=4\\), \\(2^2=4\\) explicitly." }, { stepNumber: 9, description: "Sum and take the root", workingLatex: "= \\sqrt{17}", explanation: "The total \\(17\\) has no square factor, so the exact magnitude is the surd \\(\\sqrt{17}\\)." } ], finalAnswer: "\\(\\sqrt{17}\\)." } },
  { id: "y2v2-008", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 08", difficulty: "Foundation", questionText: "Compute \\(\\mathbf{a} \\cdot \\mathbf{b}\\) for \\(\\mathbf{a} = 3\\mathbf{i} + 2\\mathbf{j} - \\mathbf{k}\\) and \\(\\mathbf{b} = \\mathbf{i} + 4\\mathbf{j} + 2\\mathbf{k}\\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["scalar product"], workedSolution: { steps: [ { stepNumber: 1, description: "State the scalar product formula", workingLatex: "\\mathbf{a} \\cdot \\mathbf{b} = a_1 b_1 + a_2 b_2 + a_3 b_3", explanation: "The dot product multiplies matching components and sums them, yielding a single number (a scalar), not a vector." }, { stepNumber: 2, description: "List the components", workingLatex: "\\mathbf{a} = (3, 2, -1), \\quad \\mathbf{b} = (1, 4, 2)", explanation: "Pair the components by axis; note the negative \\(\\mathbf{k}\\) component of \\(\\mathbf{a}\\)." }, { stepNumber: 3, description: "Multiply the i-components", workingLatex: "3 \\times 1 = 3", explanation: "Multiply the matching \\(\\mathbf{i}\\) terms to get \\(3\\)." }, { stepNumber: 4, description: "Multiply the j-components", workingLatex: "2 \\times 4 = 8", explanation: "Multiply the matching \\(\\mathbf{j}\\) terms to get \\(8\\)." }, { stepNumber: 5, description: "Multiply the k-components", workingLatex: "-1 \\times 2 = -2", explanation: "Multiply the matching \\(\\mathbf{k}\\) terms; the negative sign on \\(\\mathbf{a}\\)'s component gives \\(-2\\)." }, { stepNumber: 6, description: "Sum the three products", workingLatex: "\\mathbf{a} \\cdot \\mathbf{b} = 3 + 8 - 2 = 9", explanation: "Adding the products gives the scalar \\(9\\). Keep the sign of each product when summing." } ], finalAnswer: "9." } },
  { id: "y2v2-009", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 09", difficulty: "Foundation", questionText: "A robot moves 4 m east, 3 m north, and 12 m up. Find the straight-line distance from its starting point.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["applied", "magnitude"], workedSolution: { steps: [ { stepNumber: 1, description: "Model the motion as a vector", workingLatex: "\\mathbf{d} = (4, 3, 12)", explanation: "Treat east, north and up as the three perpendicular axes; the displacement components are \\(4, 3, 12\\) metres." }, { stepNumber: 2, description: "State the distance formula", workingLatex: "d = \\sqrt{x^2 + y^2 + z^2}", explanation: "Straight-line distance from the start is the magnitude of the displacement vector, an extension of Pythagoras to 3D." }, { stepNumber: 3, description: "Substitute the components", workingLatex: "d = \\sqrt{4^2 + 3^2 + 12^2}", explanation: "Insert \\(4, 3, 12\\) into the formula, squaring each before summing." }, { stepNumber: 4, description: "Square each component", workingLatex: "= \\sqrt{16 + 9 + 144}", explanation: "Compute \\(4^2=16\\), \\(3^2=9\\), \\(12^2=144\\); the largest term \\(12^2\\) is the easiest to miscompute." }, { stepNumber: 5, description: "Sum the squared terms", workingLatex: "= \\sqrt{169}", explanation: "Adding \\(16+9+144\\) gives \\(169\\), a perfect square." }, { stepNumber: 6, description: "Take the root and add units", workingLatex: "= 13 \\text{ m}", explanation: "Since \\(169 = 13^2\\), the straight-line distance is \\(13\\) m. State the unit since the context is physical." } ], finalAnswer: "13 m." } },
  { id: "y2v2-010", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 10", difficulty: "Foundation", questionText: "Find \\(|2\\mathbf{i} - 3\\mathbf{j} + 6\\mathbf{k}|\\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["magnitude"], workedSolution: { steps: [ { stepNumber: 1, description: "State the magnitude formula", workingLatex: "|x\\mathbf{i} + y\\mathbf{j} + z\\mathbf{k}| = \\sqrt{x^2 + y^2 + z^2}", explanation: "The magnitude of a 3D vector is the square root of the sum of the squares of its components, by Pythagoras in three dimensions. Avoid summing components without squaring first." }, { stepNumber: 2, description: "Identify the components", workingLatex: "x = 2,\\quad y = -3,\\quad z = 6", explanation: "Read the \\(\\mathbf{i},\\mathbf{j},\\mathbf{k}\\) coefficients directly. Keep the sign on \\(-3\\); it disappears only after squaring, not before." }, { stepNumber: 3, description: "Square the first component", workingLatex: "x^2 = 2^2 = 4", explanation: "Square each component separately to reduce slips. Here \\(2^2 = 4\\)." }, { stepNumber: 4, description: "Square the second component", workingLatex: "y^2 = (-3)^2 = 9", explanation: "Squaring a negative gives a positive: \\((-3)^2 = 9\\), not \\(-9\\)." }, { stepNumber: 5, description: "Square the third component", workingLatex: "z^2 = 6^2 = 36", explanation: "The largest term: \\(6^2 = 36\\). Double-check large squares as they dominate the sum." }, { stepNumber: 6, description: "Sum the squares", workingLatex: "x^2 + y^2 + z^2 = 4 + 9 + 36 = 49", explanation: "Add the three squared components. \\(4+9+36 = 49\\), a perfect square, which signals a clean root." }, { stepNumber: 7, description: "Take the square root", workingLatex: "|2\\mathbf{i} - 3\\mathbf{j} + 6\\mathbf{k}| = \\sqrt{49} = 7", explanation: "Take the positive square root; a magnitude is never negative. \\(\\sqrt{49} = 7\\)." } ], finalAnswer: "7." } },
  { id: "y2v2-011", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 11", difficulty: "Foundation", questionText: "Find the unit vector in the direction of the resultant of \\(\\mathbf{a} = \\mathbf{i} + 2\\mathbf{j} + 2\\mathbf{k}\\) and \\(\\mathbf{b} = 2\\mathbf{i} - \\mathbf{j} + 2\\mathbf{k}\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["unit vector", "resultant"], workedSolution: { steps: [ { stepNumber: 1, description: "Recall plan: resultant then unit vector", workingLatex: "\\hat{\\mathbf{r}} = \\frac{\\mathbf{a} + \\mathbf{b}}{|\\mathbf{a} + \\mathbf{b}|}", explanation: "First add the vectors to get the resultant \\(\\mathbf{r} = \\mathbf{a}+\\mathbf{b}\\), then divide by its magnitude. Do not unit-ise \\(\\mathbf{a}\\) and \\(\\mathbf{b}\\) separately." }, { stepNumber: 2, description: "Add the i-components", workingLatex: "1 + 2 = 3", explanation: "Add component-wise. The \\(\\mathbf{i}\\) parts give \\(1+2=3\\)." }, { stepNumber: 3, description: "Add the j-components", workingLatex: "2 + (-1) = 1", explanation: "The \\(\\mathbf{j}\\) parts: \\(2 + (-1) = 1\\). Mind the sign on \\(\\mathbf{b}\\)'s \\(\\mathbf{j}\\) term." }, { stepNumber: 4, description: "Add the k-components", workingLatex: "2 + 2 = 4", explanation: "The \\(\\mathbf{k}\\) parts: \\(2+2=4\\), giving the full resultant." }, { stepNumber: 5, description: "Write the resultant vector", workingLatex: "\\mathbf{a} + \\mathbf{b} = 3\\mathbf{i} + \\mathbf{j} + 4\\mathbf{k}", explanation: "Assemble the resultant from the three sums before computing its length." }, { stepNumber: 6, description: "Square each component of the resultant", workingLatex: "3^2 = 9,\\quad 1^2 = 1,\\quad 4^2 = 16", explanation: "Prepare the magnitude by squaring each component separately to avoid arithmetic slips." }, { stepNumber: 7, description: "Sum the squares", workingLatex: "9 + 1 + 16 = 26", explanation: "Add to get the radicand: \\(9+1+16=26\\)." }, { stepNumber: 8, description: "Take the magnitude", workingLatex: "|\\mathbf{a} + \\mathbf{b}| = \\sqrt{26}", explanation: "\\(26\\) is not a perfect square and has no square factor, so \\(\\sqrt{26}\\) is left in surd form." }, { stepNumber: 9, description: "Divide the resultant by its magnitude", workingLatex: "\\hat{\\mathbf{r}} = \\frac{1}{\\sqrt{26}}(3\\mathbf{i} + \\mathbf{j} + 4\\mathbf{k})", explanation: "Scaling by \\(1/|\\mathbf{r}|\\) makes the length \\(1\\) while preserving direction. This is the required unit vector." }, { stepNumber: 10, description: "Write in component form", workingLatex: "\\hat{\\mathbf{r}} = \\tfrac{1}{\\sqrt{26}}(3, 1, 4)", explanation: "Present the answer compactly. Optionally rationalise to \\(\\tfrac{1}{26}(3\\sqrt{26},\\sqrt{26},4\\sqrt{26})\\), but the factored form is standard." } ], finalAnswer: "\\(\\tfrac{1}{\\sqrt{26}}(3, 1, 4)\\)." } },
  { id: "y2v2-012", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 12", difficulty: "Foundation", questionText: "Show that \\(A(1, 2, 3),\\ B(3, 6, 9),\\ C(5, 10, 15)\\) are collinear.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["collinear"], workedSolution: { steps: [ { stepNumber: 1, description: "State the collinearity strategy", workingLatex: "A,B,C\\ \\text{collinear} \\iff \\overrightarrow{AB} \\parallel \\overrightarrow{BC}", explanation: "Three points are collinear if two displacement vectors sharing a common point are parallel (scalar multiples). The shared point \\(B\\) guarantees they lie on the same line." }, { stepNumber: 2, description: "Form AB by subtracting position vectors", workingLatex: "\\overrightarrow{AB} = B - A = (3-1,\\ 6-2,\\ 9-3)", explanation: "Displacement is endpoint minus start. Subtract in the order \\(B-A\\), not \\(A-B\\)." }, { stepNumber: 3, description: "Evaluate AB", workingLatex: "\\overrightarrow{AB} = (2, 4, 6)", explanation: "Compute each component to get the direction from \\(A\\) to \\(B\\)." }, { stepNumber: 4, description: "Form BC by subtracting position vectors", workingLatex: "\\overrightarrow{BC} = C - B = (5-3,\\ 10-6,\\ 15-9)", explanation: "Use the shared point \\(B\\) as the start so the two vectors meet, which is essential for collinearity." }, { stepNumber: 5, description: "Evaluate BC", workingLatex: "\\overrightarrow{BC} = (2, 4, 6)", explanation: "Compute the direction from \\(B\\) to \\(C\\)." }, { stepNumber: 6, description: "Compare the two vectors", workingLatex: "\\overrightarrow{BC} = (2,4,6) = 1\\cdot\\overrightarrow{AB}", explanation: "\\(\\overrightarrow{BC}\\) is a scalar multiple (here \\(\\times 1\\)) of \\(\\overrightarrow{AB}\\), so the vectors are parallel." }, { stepNumber: 7, description: "Conclude collinearity", workingLatex: "\\overrightarrow{AB} \\parallel \\overrightarrow{BC},\\ \\text{share } B \\Rightarrow A,B,C \\text{ collinear}", explanation: "Parallel vectors through the common point \\(B\\) force all three points onto one straight line. State the shared point explicitly to complete the proof." } ], finalAnswer: "Collinear." } },
  { id: "y2v2-013", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 13", difficulty: "Foundation", questionText: "Find a vector of magnitude 10 in the direction of \\((3, -4, 0)\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["unit vector"], workedSolution: { steps: [ { stepNumber: 1, description: "State the rescaling plan", workingLatex: "\\mathbf{v} = 10\\,\\hat{\\mathbf{a}} = \\frac{10}{|\\mathbf{a}|}\\,\\mathbf{a}", explanation: "To get a vector of given length \\(10\\) in the direction of \\(\\mathbf{a}\\), scale \\(\\mathbf{a}\\) by \\(10/|\\mathbf{a}|\\). Keeping it as one factor avoids messy unit-vector decimals." }, { stepNumber: 2, description: "Square each component", workingLatex: "3^2 = 9,\\quad (-4)^2 = 16,\\quad 0^2 = 0", explanation: "Square each component to find the magnitude; \\((-4)^2 = 16\\) is positive." }, { stepNumber: 3, description: "Sum the squares", workingLatex: "9 + 16 + 0 = 25", explanation: "Add the squared components to get the radicand \\(25\\)." }, { stepNumber: 4, description: "Take the magnitude", workingLatex: "|\\mathbf{a}| = \\sqrt{25} = 5", explanation: "\\(\\sqrt{25}=5\\); this clean value makes the scale factor simple." }, { stepNumber: 5, description: "Compute the scale factor", workingLatex: "\\frac{10}{|\\mathbf{a}|} = \\frac{10}{5} = 2", explanation: "Dividing the target length by the current length gives the multiplier \\(2\\)." }, { stepNumber: 6, description: "Multiply each component by the factor", workingLatex: "2(3, -4, 0) = (2\\cdot3,\\ 2\\cdot(-4),\\ 2\\cdot0)", explanation: "Distribute the scalar to every component, preserving the sign on \\(-4\\)." }, { stepNumber: 7, description: "Write the resulting vector", workingLatex: "\\mathbf{v} = (6, -8, 0)", explanation: "This is the required vector. As a check, \\(|\\mathbf{v}| = \\sqrt{36+64+0} = \\sqrt{100} = 10\\), confirming length \\(10\\)." } ], finalAnswer: "\\((6, -8, 0)\\)." } },
  { id: "y2v2-014", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 14", difficulty: "Foundation", questionText: "Find the midpoint of the line segment joining \\(P(1, -1, 2)\\) and \\(Q(5, 3, 6)\\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["midpoint"], workedSolution: { steps: [ { stepNumber: 1, description: "State the midpoint formula", workingLatex: "M = \\left(\\frac{x_P + x_Q}{2},\\ \\frac{y_P + y_Q}{2},\\ \\frac{z_P + z_Q}{2}\\right)", explanation: "The midpoint averages corresponding coordinates of the two endpoints. Add then halve each axis; do not subtract (that would give a displacement)." }, { stepNumber: 2, description: "Average the x-coordinates", workingLatex: "\\frac{1 + 5}{2} = \\frac{6}{2} = 3", explanation: "\\(x\\)-coordinate of the midpoint: \\((1+5)/2 = 3\\)." }, { stepNumber: 3, description: "Average the y-coordinates", workingLatex: "\\frac{-1 + 3}{2} = \\frac{2}{2} = 1", explanation: "\\(y\\)-coordinate: \\((-1+3)/2 = 1\\). Carry the negative sign on \\(-1\\) into the sum." }, { stepNumber: 4, description: "Average the z-coordinates", workingLatex: "\\frac{2 + 6}{2} = \\frac{8}{2} = 4", explanation: "\\(z\\)-coordinate: \\((2+6)/2 = 4\\)." }, { stepNumber: 5, description: "Assemble the midpoint", workingLatex: "M = (3, 1, 4)", explanation: "Combine the three averaged coordinates into the midpoint. It should lie symmetrically between \\(P\\) and \\(Q\\)." } ], finalAnswer: "\\((3, 1, 4)\\)." } },
  { id: "y2v2-015", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 15", difficulty: "Foundation", questionText: "State whether \\(\\mathbf{a} = 2\\mathbf{i} + 3\\mathbf{j} - \\mathbf{k}\\) and \\(\\mathbf{b} = 4\\mathbf{i} + 6\\mathbf{j} - 2\\mathbf{k}\\) are parallel.", marks: 1, examStyle: false, yearCreated: 2026, tags: ["parallel"], workedSolution: { steps: [ { stepNumber: 1, description: "State the parallel test", workingLatex: "\\mathbf{a} \\parallel \\mathbf{b} \\iff \\mathbf{b} = \\lambda\\mathbf{a}\\ \\text{for some scalar } \\lambda", explanation: "Two vectors are parallel exactly when one is a scalar multiple of the other. Look for a single \\(\\lambda\\) that works for all three components." }, { stepNumber: 2, description: "Compare i-components", workingLatex: "\\frac{4}{2} = 2", explanation: "Form the ratio of \\(\\mathbf{i}\\) components to propose a candidate \\(\\lambda = 2\\)." }, { stepNumber: 3, description: "Check j-components with the same ratio", workingLatex: "\\frac{6}{3} = 2", explanation: "The \\(\\mathbf{j}\\) ratio must equal the candidate \\(\\lambda\\); \\(6/3 = 2\\) agrees." }, { stepNumber: 4, description: "Check k-components with the same ratio", workingLatex: "\\frac{-2}{-1} = 2", explanation: "The \\(\\mathbf{k}\\) ratio: \\((-2)/(-1) = 2\\), matching. Equal ratios on every axis confirm proportionality." }, { stepNumber: 5, description: "Conclude parallelism", workingLatex: "\\mathbf{b} = 2\\mathbf{a} \\Rightarrow \\mathbf{a} \\parallel \\mathbf{b}", explanation: "Since a single scalar \\(\\lambda = 2\\) maps \\(\\mathbf{a}\\) onto \\(\\mathbf{b}\\), the vectors are parallel." } ], finalAnswer: "Yes, parallel." } },
  { id: "y2v2-016", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 16", difficulty: "Foundation", questionText: "Decide if \\(\\mathbf{a} = \\mathbf{i} + 2\\mathbf{j} + 3\\mathbf{k}\\) is perpendicular to \\(\\mathbf{b} = 4\\mathbf{i} - \\mathbf{j} - \\tfrac{2}{3}\\mathbf{k}\\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["perpendicular"], workedSolution: { steps: [ { stepNumber: 1, description: "State the perpendicularity test", workingLatex: "\\mathbf{a} \\perp \\mathbf{b} \\iff \\mathbf{a}\\cdot\\mathbf{b} = 0", explanation: "Two non-zero vectors are perpendicular precisely when their scalar (dot) product is zero. Compute the dot product and check against \\(0\\)." }, { stepNumber: 2, description: "Write the dot product formula", workingLatex: "\\mathbf{a}\\cdot\\mathbf{b} = a_1 b_1 + a_2 b_2 + a_3 b_3", explanation: "Multiply matching components and sum. Do not cross components between different axes." }, { stepNumber: 3, description: "Multiply the i-components", workingLatex: "1 \\times 4 = 4", explanation: "Product of the \\(\\mathbf{i}\\) terms: \\(1 \\times 4 = 4\\)." }, { stepNumber: 4, description: "Multiply the j-components", workingLatex: "2 \\times (-1) = -2", explanation: "Product of the \\(\\mathbf{j}\\) terms: \\(2 \\times (-1) = -2\\). Keep the negative sign from \\(\\mathbf{b}\\)." }, { stepNumber: 5, description: "Multiply the k-components", workingLatex: "3 \\times \\left(-\\tfrac{2}{3}\\right) = -2", explanation: "Product of the \\(\\mathbf{k}\\) terms: \\(3 \\times (-\\tfrac{2}{3}) = -2\\); the \\(3\\) cancels the denominator." }, { stepNumber: 6, description: "Sum the products", workingLatex: "\\mathbf{a}\\cdot\\mathbf{b} = 4 + (-2) + (-2) = 0", explanation: "Add the three products: \\(4 - 2 - 2 = 0\\)." }, { stepNumber: 7, description: "Conclude perpendicularity", workingLatex: "\\mathbf{a}\\cdot\\mathbf{b} = 0 \\Rightarrow \\mathbf{a} \\perp \\mathbf{b}", explanation: "A zero dot product with both vectors non-zero confirms they are perpendicular." } ], finalAnswer: "Yes, perpendicular." } },
  { id: "y2v2-017", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 17", difficulty: "Foundation", questionText: "Find the displacement from \\(P(3, 1, 2)\\) to \\(Q(8, 5, 1)\\) and its magnitude.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["distance"], workedSolution: { steps: [ { stepNumber: 1, description: "State the displacement formula", workingLatex: "\\overrightarrow{PQ} = Q - P", explanation: "Displacement from \\(P\\) to \\(Q\\) is endpoint minus start. Subtracting in the wrong order flips every sign." }, { stepNumber: 2, description: "Subtract the x-coordinates", workingLatex: "8 - 3 = 5", explanation: "The \\(\\mathbf{i}\\) component: \\(8-3 = 5\\)." }, { stepNumber: 3, description: "Subtract the y-coordinates", workingLatex: "5 - 1 = 4", explanation: "The \\(\\mathbf{j}\\) component: \\(5-1 = 4\\)." }, { stepNumber: 4, description: "Subtract the z-coordinates", workingLatex: "1 - 2 = -1", explanation: "The \\(\\mathbf{k}\\) component: \\(1-2 = -1\\); the negative is correct since \\(Q\\) is lower in \\(z\\)." }, { stepNumber: 5, description: "Write the displacement vector", workingLatex: "\\overrightarrow{PQ} = 5\\mathbf{i} + 4\\mathbf{j} - \\mathbf{k}", explanation: "Assemble the displacement before finding its magnitude." }, { stepNumber: 6, description: "Square each component", workingLatex: "5^2 = 25,\\quad 4^2 = 16,\\quad (-1)^2 = 1", explanation: "Square each component for the magnitude; \\((-1)^2 = 1\\) is positive." }, { stepNumber: 7, description: "Sum the squares", workingLatex: "25 + 16 + 1 = 42", explanation: "Add to obtain the radicand \\(42\\)." }, { stepNumber: 8, description: "Take the magnitude", workingLatex: "|\\overrightarrow{PQ}| = \\sqrt{42}", explanation: "\\(42 = 2\\cdot 3\\cdot 7\\) has no square factor, so \\(\\sqrt{42}\\) is the simplest surd form (\\(\\approx 6.48\\))." } ], finalAnswer: "\\(\\mathbf{PQ} = 5\\mathbf{i} + 4\\mathbf{j} - \\mathbf{k}\\); \\(\\sqrt{42}\\)." } },
  { id: "y2v2-018", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 18", difficulty: "Foundation", questionText: "A flight path is represented by \\(\\mathbf{d} = 30\\mathbf{i} + 40\\mathbf{j}\\) km. Find the total distance.", marks: 2, examStyle: false, yearCreated: 2026, tags: ["applied"], workedSolution: { steps: [ { stepNumber: 1, description: "Interpret distance as magnitude", workingLatex: "\\text{distance} = |\\mathbf{d}| = \\sqrt{x^2 + y^2}", explanation: "Total straight-line distance is the magnitude of the displacement vector. With no \\(\\mathbf{k}\\) term, this is a 2D Pythagoras calculation." }, { stepNumber: 2, description: "Identify the components", workingLatex: "x = 30,\\quad y = 40", explanation: "Read the \\(\\mathbf{i}\\) and \\(\\mathbf{j}\\) coefficients in km; the \\(\\mathbf{k}\\) component is \\(0\\)." }, { stepNumber: 3, description: "Square the components", workingLatex: "30^2 = 900,\\quad 40^2 = 1600", explanation: "Square each component separately to keep the large numbers manageable." }, { stepNumber: 4, description: "Sum the squares", workingLatex: "900 + 1600 = 2500", explanation: "Add the squared components to get the radicand \\(2500\\)." }, { stepNumber: 5, description: "Take the square root", workingLatex: "|\\mathbf{d}| = \\sqrt{2500} = 50", explanation: "\\(\\sqrt{2500}=50\\); this is the classic \\(3\\)-\\(4\\)-\\(5\\) triangle scaled by \\(10\\)." }, { stepNumber: 6, description: "State the answer with units", workingLatex: "\\text{distance} = 50\\ \\text{km}", explanation: "Attach the unit km from the question. Always restore units on an applied final answer." } ], finalAnswer: "50 km." } },
  { id: "y2v2-019", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 19", difficulty: "Foundation", questionText: "Find the angle \\(\\mathbf{a} = \\mathbf{i}\\) makes with the \\(y\\)-axis.", marks: 2, examStyle: false, yearCreated: 2026, tags: ["angle"], workedSolution: { steps: [ { stepNumber: 1, description: "Identify the given vector", workingLatex: "\\mathbf{a} = \\mathbf{i} = \\begin{pmatrix} 1 \\\\ 0 \\\\ 0 \\end{pmatrix}", explanation: "The vector \\(\\mathbf{i}\\) is the unit vector along the \\(x\\)-axis. Writing it in component form makes the dot product mechanical and avoids confusing the axis directions." }, { stepNumber: 2, description: "Identify the y-axis direction", workingLatex: "\\mathbf{j} = \\begin{pmatrix} 0 \\\\ 1 \\\\ 0 \\end{pmatrix}", explanation: "The \\(y\\)-axis points along the unit vector \\(\\mathbf{j}\\). The angle a vector makes with an axis is the angle between the vector and that axis's unit vector." }, { stepNumber: 3, description: "Write the angle formula", workingLatex: "\\cos\\theta = \\frac{\\mathbf{a}\\cdot\\mathbf{j}}{|\\mathbf{a}||\\mathbf{j}|}", explanation: "The angle between two vectors comes from the scalar product formula. Always divide by the product of magnitudes, not by either magnitude alone." }, { stepNumber: 4, description: "Compute the dot product", workingLatex: "\\mathbf{a}\\cdot\\mathbf{j} = (1)(0) + (0)(1) + (0)(0) = 0", explanation: "Multiply matching components and add. \\(\\mathbf{i}\\) and \\(\\mathbf{j}\\) share no common component, so the sum is \\(0\\)." }, { stepNumber: 5, description: "Substitute into the formula", workingLatex: "\\cos\\theta = \\frac{0}{(1)(1)} = 0", explanation: "Both unit vectors have magnitude \\(1\\), so the denominator is \\(1\\). A zero dot product makes \\(\\cos\\theta = 0\\)." }, { stepNumber: 6, description: "Solve for the angle", workingLatex: "\\theta = \\cos^{-1}(0) = 90^{\\circ}", explanation: "Since \\(\\cos\\theta = 0\\), the angle is \\(90^{\\circ}\\): \\(\\mathbf{i}\\) is perpendicular to the \\(y\\)-axis, as expected for two coordinate axes." } ], finalAnswer: "\\(90^{\\circ}\\)." } },
  { id: "y2v2-020", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 20", difficulty: "Foundation", questionText: "Given \\(\\mathbf{AB} = (3, 4, 0)\\) and \\(\\mathbf{AC} = (0, 0, 5)\\), find \\(|\\mathbf{AB}|\\) and \\(|\\mathbf{AC}|\\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["magnitude"], workedSolution: { steps: [ { stepNumber: 1, description: "Recall the magnitude formula", workingLatex: "|\\mathbf{v}| = \\sqrt{x^2 + y^2 + z^2}", explanation: "The magnitude of a 3D vector is the square root of the sum of squared components. This is the Pythagorean distance from the origin." }, { stepNumber: 2, description: "Square each component of AB", workingLatex: "3^2 = 9,\\quad 4^2 = 16,\\quad 0^2 = 0", explanation: "Square the components of \\(\\mathbf{AB} = (3,4,0)\\) one at a time. Squaring removes any sign, so direction does not affect magnitude." }, { stepNumber: 3, description: "Sum the squares for AB", workingLatex: "9 + 16 + 0 = 25", explanation: "Add the squared components before taking the root. The zero \\(z\\)-component contributes nothing here." }, { stepNumber: 4, description: "Take the root for AB", workingLatex: "|\\mathbf{AB}| = \\sqrt{25} = 5", explanation: "The square root of \\(25\\) is exactly \\(5\\). This is the classic \\(3\\)-\\(4\\)-\\(5\\) right triangle in the \\(xy\\)-plane." }, { stepNumber: 5, description: "Square each component of AC", workingLatex: "0^2 = 0,\\quad 0^2 = 0,\\quad 5^2 = 25", explanation: "Now apply the same process to \\(\\mathbf{AC} = (0,0,5)\\). Only the \\(z\\)-component is nonzero." }, { stepNumber: 6, description: "Sum the squares for AC", workingLatex: "0 + 0 + 25 = 25", explanation: "Add the squared components. The vector lies entirely along the \\(z\\)-axis." }, { stepNumber: 7, description: "Take the root for AC", workingLatex: "|\\mathbf{AC}| = \\sqrt{25} = 5", explanation: "The root gives \\(5\\); a vector along one axis has magnitude equal to that component. Both magnitudes equal \\(5\\)." } ], finalAnswer: "5 and 5." } },
  { id: "y2v2-021", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 21", difficulty: "Standard", questionText: "Find the angle between \\(\\mathbf{a} = 3\\mathbf{i} + 4\\mathbf{j}\\) and \\(\\mathbf{b} = 4\\mathbf{i} - 3\\mathbf{j}\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["angle"], workedSolution: { steps: [ { stepNumber: 1, description: "Write both vectors in components", workingLatex: "\\mathbf{a} = \\begin{pmatrix} 3 \\\\ 4 \\end{pmatrix},\\quad \\mathbf{b} = \\begin{pmatrix} 4 \\\\ -3 \\end{pmatrix}", explanation: "Convert from \\(\\mathbf{i},\\mathbf{j}\\) form to column vectors so the dot product is easy to read off. Keep track of the negative sign on \\(\\mathbf{b}\\)." }, { stepNumber: 2, description: "Write the angle formula", workingLatex: "\\cos\\theta = \\frac{\\mathbf{a}\\cdot\\mathbf{b}}{|\\mathbf{a}||\\mathbf{b}|}", explanation: "The scalar product gives the angle between two vectors. We will look at the numerator first since a zero there is decisive." }, { stepNumber: 3, description: "Multiply matching components", workingLatex: "\\mathbf{a}\\cdot\\mathbf{b} = (3)(4) + (4)(-3)", explanation: "Multiply \\(x\\) with \\(x\\) and \\(y\\) with \\(y\\). A common slip is to cross-multiply components, which is wrong." }, { stepNumber: 4, description: "Evaluate the products", workingLatex: "\\mathbf{a}\\cdot\\mathbf{b} = 12 - 12 = 0", explanation: "The two products cancel exactly, giving a dot product of zero. This is the key signal." }, { stepNumber: 5, description: "Interpret a zero dot product", workingLatex: "\\cos\\theta = \\frac{0}{|\\mathbf{a}||\\mathbf{b}|} = 0", explanation: "Both magnitudes are nonzero (they are both \\(5\\)), so the fraction is \\(0\\). No need to compute the magnitudes fully." }, { stepNumber: 6, description: "Solve for the angle", workingLatex: "\\theta = \\cos^{-1}(0) = 90^{\\circ}", explanation: "A zero scalar product means the vectors are perpendicular, so the angle is exactly \\(90^{\\circ}\\)." } ], finalAnswer: "\\(90^{\\circ}\\)." } },
  { id: "y2v2-022", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 22", difficulty: "Standard", questionText: "Given \\(A = (0, 0, 0)\\), \\(B = (6, 3, 2)\\), \\(C = (6, 0, 2)\\), show that \\(\\triangle ABC\\) is right-angled.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["right angle", "proof"], workedSolution: { steps: [ { stepNumber: 1, description: "Form vector AB", workingLatex: "\\mathbf{AB} = B - A = (6-0,\\ 3-0,\\ 2-0) = (6, 3, 2)", explanation: "Subtract the start point from the end point to get the displacement. To test for a right angle we need the edge vectors of the triangle." }, { stepNumber: 2, description: "Form vector AC", workingLatex: "\\mathbf{AC} = C - A = (6-0,\\ 0-0,\\ 2-0) = (6, 0, 2)", explanation: "Compute the second edge from \\(A\\). Consistency in the subtraction order matters for the directions." }, { stepNumber: 3, description: "Form vector BC", workingLatex: "\\mathbf{BC} = C - B = (6-6,\\ 0-3,\\ 2-2) = (0, -3, 0)", explanation: "The third edge connects \\(B\\) to \\(C\\). We now have all three side vectors to test which pair is perpendicular." }, { stepNumber: 4, description: "Build the vectors meeting at C", workingLatex: "\\mathbf{CA} = -\\mathbf{AC} = (-6, 0, -2),\\quad \\mathbf{CB} = -\\mathbf{BC} = (0, 3, 0)", explanation: "A right angle at \\(C\\) means the two edges emanating from \\(C\\) are perpendicular. Reverse \\(\\mathbf{AC}\\) and \\(\\mathbf{BC}\\) so both start at \\(C\\)." }, { stepNumber: 5, description: "Dot the edges at C", workingLatex: "\\mathbf{CA}\\cdot\\mathbf{CB} = (-6)(0) + (0)(3) + (-2)(0)", explanation: "Multiply matching components of the two edges meeting at \\(C\\). If the sum is zero the angle at \\(C\\) is a right angle." }, { stepNumber: 6, description: "Evaluate the dot product", workingLatex: "\\mathbf{CA}\\cdot\\mathbf{CB} = 0 + 0 + 0 = 0", explanation: "Every term vanishes, so the scalar product is \\(0\\). Reversing both vectors does not change their dot product, so \\(\\mathbf{AC}\\cdot\\mathbf{BC}=0\\) too." }, { stepNumber: 7, description: "Conclude the right angle", workingLatex: "\\mathbf{CA}\\cdot\\mathbf{CB} = 0 \\Rightarrow \\angle ACB = 90^{\\circ}", explanation: "Since the two sides at \\(C\\) are perpendicular, \\(\\triangle ABC\\) is right-angled at \\(C\\). Stating where the right angle is completes the proof." } ], finalAnswer: "Right-angled at \\(C\\)." } },
  { id: "y2v2-023", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 23", difficulty: "Standard", questionText: "Find the value of \\(k\\) such that \\((2, -1, k)\\) and \\((k, 3, 1)\\) are perpendicular.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["perpendicular"], workedSolution: { steps: [ { stepNumber: 1, description: "State the perpendicularity condition", workingLatex: "\\mathbf{u}\\cdot\\mathbf{v} = 0", explanation: "Two vectors are perpendicular exactly when their scalar product is zero. This gives an equation in \\(k\\)." }, { stepNumber: 2, description: "Write the two vectors", workingLatex: "\\mathbf{u} = (2, -1, k),\\quad \\mathbf{v} = (k, 3, 1)", explanation: "Label the vectors so the unknown \\(k\\) appears in both. Note \\(k\\) is the third component of one and the first of the other." }, { stepNumber: 3, description: "Form each component product", workingLatex: "\\mathbf{u}\\cdot\\mathbf{v} = (2)(k) + (-1)(3) + (k)(1)", explanation: "Multiply matching components carefully, watching the negative second component. Do not drop the sign on \\(-1\\)." }, { stepNumber: 4, description: "Simplify each product", workingLatex: "\\mathbf{u}\\cdot\\mathbf{v} = 2k - 3 + k", explanation: "Write out the three terms. The two \\(k\\)-terms can now be collected." }, { stepNumber: 5, description: "Collect like terms", workingLatex: "\\mathbf{u}\\cdot\\mathbf{v} = 3k - 3", explanation: "Combine \\(2k\\) and \\(k\\) into \\(3k\\). The expression is now linear in \\(k\\)." }, { stepNumber: 6, description: "Set the dot product to zero", workingLatex: "3k - 3 = 0", explanation: "Apply the perpendicularity condition. This is the equation that determines \\(k\\)." }, { stepNumber: 7, description: "Solve for k", workingLatex: "3k = 3 \\Rightarrow k = 1", explanation: "Add \\(3\\) to both sides then divide by \\(3\\). The vectors are perpendicular only when \\(k = 1\\)." } ], finalAnswer: "\\(k = 1\\)." } },
  { id: "y2v2-024", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 24", difficulty: "Standard", questionText: "Find the angle between \\(\\mathbf{a} = \\mathbf{i} + \\mathbf{j} + \\mathbf{k}\\) and \\(\\mathbf{b} = 2\\mathbf{i} - \\mathbf{j} + 2\\mathbf{k}\\) to the nearest degree.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["angle"], workedSolution: { steps: [ { stepNumber: 1, description: "Write both vectors in components", workingLatex: "\\mathbf{a} = (1, 1, 1),\\quad \\mathbf{b} = (2, -1, 2)", explanation: "Convert from \\(\\mathbf{i},\\mathbf{j},\\mathbf{k}\\) form to components, keeping the negative on the \\(\\mathbf{j}\\) term of \\(\\mathbf{b}\\)." }, { stepNumber: 2, description: "Write the angle formula", workingLatex: "\\cos\\theta = \\frac{\\mathbf{a}\\cdot\\mathbf{b}}{|\\mathbf{a}||\\mathbf{b}|}", explanation: "The angle needs the dot product and both magnitudes. We compute each piece separately to avoid errors." }, { stepNumber: 3, description: "Compute the dot product", workingLatex: "\\mathbf{a}\\cdot\\mathbf{b} = (1)(2) + (1)(-1) + (1)(2) = 2 - 1 + 2 = 3", explanation: "Multiply matching components and sum. The middle term is negative because of \\(\\mathbf{b}\\)'s \\(-1\\)." }, { stepNumber: 4, description: "Find magnitude of a", workingLatex: "|\\mathbf{a}| = \\sqrt{1^2 + 1^2 + 1^2} = \\sqrt{3}", explanation: "Square, sum, and root the components of \\(\\mathbf{a}\\). Keep \\(\\sqrt{3}\\) exact rather than rounding early." }, { stepNumber: 5, description: "Find magnitude of b", workingLatex: "|\\mathbf{b}| = \\sqrt{2^2 + (-1)^2 + 2^2} = \\sqrt{4 + 1 + 4} = \\sqrt{9} = 3", explanation: "Squaring \\(-1\\) gives \\(+1\\). The sum is \\(9\\), a perfect square, so \\(|\\mathbf{b}| = 3\\)." }, { stepNumber: 6, description: "Substitute into the formula", workingLatex: "\\cos\\theta = \\frac{3}{\\sqrt{3}\\times 3} = \\frac{3}{3\\sqrt{3}}", explanation: "Place the dot product over the product of magnitudes. The denominator is \\(3\\sqrt{3}\\)." }, { stepNumber: 7, description: "Simplify the cosine", workingLatex: "\\cos\\theta = \\frac{1}{\\sqrt{3}} \\approx 0.5774", explanation: "Cancel the factor of \\(3\\) to leave \\(\\tfrac{1}{\\sqrt{3}}\\). Keeping the exact form reduces rounding error before the inverse cosine." }, { stepNumber: 8, description: "Take the inverse cosine", workingLatex: "\\theta = \\cos^{-1}\\!\\left(\\tfrac{1}{\\sqrt{3}}\\right) \\approx 54.7^{\\circ}", explanation: "Apply \\(\\cos^{-1}\\) to get the angle in degrees. Make sure the calculator is in degree mode." }, { stepNumber: 9, description: "Round to the nearest degree", workingLatex: "\\theta \\approx 55^{\\circ}", explanation: "Rounding \\(54.7^{\\circ}\\) to the nearest degree gives \\(55^{\\circ}\\), as required." } ], finalAnswer: "\\(\\approx 55^{\\circ}\\)." } },
  { id: "y2v2-025", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 25", difficulty: "Standard", questionText: "The position vectors of \\(A,\\ B,\\ C\\) are \\(\\mathbf{a} = \\mathbf{i} + 2\\mathbf{j} + 3\\mathbf{k}\\), \\(\\mathbf{b} = 2\\mathbf{i} + 4\\mathbf{j} + 6\\mathbf{k}\\), \\(\\mathbf{c} = 3\\mathbf{i} + 6\\mathbf{j} + 9\\mathbf{k}\\). Show \\(A,\\ B,\\ C\\) are collinear.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["collinear"], workedSolution: { steps: [ { stepNumber: 1, description: "State the collinearity strategy", workingLatex: "A,\\ B,\\ C \\text{ collinear} \\iff \\mathbf{AB} \\parallel \\mathbf{BC}", explanation: "Three points are collinear if two displacement vectors sharing a point are parallel. We will use \\(\\mathbf{AB}\\) and \\(\\mathbf{BC}\\), which share point \\(B\\)." }, { stepNumber: 2, description: "Form vector AB", workingLatex: "\\mathbf{AB} = \\mathbf{b} - \\mathbf{a} = (2-1,\\ 4-2,\\ 6-3) = (1, 2, 3)", explanation: "Subtract \\(\\mathbf{a}\\) from \\(\\mathbf{b}\\) component by component. This is the direction from \\(A\\) to \\(B\\)." }, { stepNumber: 3, description: "Form vector BC", workingLatex: "\\mathbf{BC} = \\mathbf{c} - \\mathbf{b} = (3-2,\\ 6-4,\\ 9-6) = (1, 2, 3)", explanation: "Subtract \\(\\mathbf{b}\\) from \\(\\mathbf{c}\\). Comparing this with \\(\\mathbf{AB}\\) tests whether the directions match." }, { stepNumber: 4, description: "Compare the two vectors", workingLatex: "\\mathbf{BC} = (1,2,3) = 1\\times \\mathbf{AB}", explanation: "The two vectors are identical, so \\(\\mathbf{BC} = \\lambda\\,\\mathbf{AB}\\) with scalar \\(\\lambda = 1\\), confirming they are parallel." }, { stepNumber: 5, description: "Note the shared point", workingLatex: "\\mathbf{AB} \\parallel \\mathbf{BC} \\text{ and share } B", explanation: "Parallel vectors with a common point \\(B\\) must lie on the same straight line. Parallelism alone is not enough; the shared point is essential." }, { stepNumber: 6, description: "Conclude collinearity", workingLatex: "\\Rightarrow A,\\ B,\\ C \\text{ are collinear}", explanation: "Since \\(B\\) lies on both segments and the directions agree, \\(A\\), \\(B\\), \\(C\\) all lie on one line." } ], finalAnswer: "Collinear." } },
  { id: "y2v2-026", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 26", difficulty: "Standard", questionText: "A point \\(P\\) divides \\(AB\\) in ratio 1:2 where \\(A = (2, 0, 1)\\) and \\(B = (5, 6, 7)\\). Find \\(P\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["section formula"], workedSolution: { steps: [ { stepNumber: 1, description: "Recall the section formula", workingLatex: "P = \\frac{n\\,\\mathbf{A} + m\\,\\mathbf{B}}{m + n}", explanation: "For a point dividing \\(AB\\) internally in ratio \\(m:n\\), the position vector weights \\(\\mathbf{A}\\) by \\(n\\) and \\(\\mathbf{B}\\) by \\(m\\). Note the cross-pairing of weights." }, { stepNumber: 2, description: "Identify the ratio", workingLatex: "m:n = 1:2 \\Rightarrow m = 1,\\ n = 2,\\ m+n = 3", explanation: "Here \\(AP:PB = 1:2\\), so \\(P\\) is closer to \\(A\\). The weight on \\(\\mathbf{A}\\) is \\(n=2\\) and on \\(\\mathbf{B}\\) is \\(m=1\\)." }, { stepNumber: 3, description: "Substitute the points", workingLatex: "P = \\frac{2(2,0,1) + 1(5,6,7)}{3}", explanation: "Insert \\(A=(2,0,1)\\) and \\(B=(5,6,7)\\) with their weights. The larger weight on \\(A\\) reflects \\(P\\) being nearer \\(A\\)." }, { stepNumber: 4, description: "Scale each position vector", workingLatex: "2(2,0,1) = (4,0,2),\\quad 1(5,6,7) = (5,6,7)", explanation: "Multiply each component by its weight separately. This keeps the arithmetic per-component and error-free." }, { stepNumber: 5, description: "Add the scaled vectors", workingLatex: "(4,0,2) + (5,6,7) = (9, 6, 9)", explanation: "Sum component by component. The result is the numerator before dividing by the total weight." }, { stepNumber: 6, description: "Divide by the total weight", workingLatex: "P = \\frac{(9,6,9)}{3} = (3, 2, 3)", explanation: "Divide each component by \\(3\\). This gives the coordinates of \\(P\\) dividing \\(AB\\) in ratio \\(1:2\\)." } ], finalAnswer: "\\((3, 2, 3)\\)." } },
  { id: "y2v2-027", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 27", difficulty: "Standard", questionText: "Two forces act on a particle: \\(\\mathbf{F_{1}} = 4\\mathbf{i} + 3\\mathbf{j}\\) N and \\(\\mathbf{F_{2}} = -2\\mathbf{i} + 5\\mathbf{j} + \\mathbf{k}\\) N. Find the magnitude of the resultant.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["applied", "mechanics"], workedSolution: { steps: [ { stepNumber: 1, description: "Write the resultant as a sum", workingLatex: "\\mathbf{R} = \\mathbf{F_{1}} + \\mathbf{F_{2}}", explanation: "The resultant of forces is their vector sum. Add components before taking any magnitude." }, { stepNumber: 2, description: "Write both forces in components", workingLatex: "\\mathbf{F_{1}} = (4, 3, 0),\\quad \\mathbf{F_{2}} = (-2, 5, 1)", explanation: "Include the implicit zero \\(\\mathbf{k}\\)-component of \\(\\mathbf{F_{1}}\\). Omitting it is a common slip that throws off the third component." }, { stepNumber: 3, description: "Add the i-components", workingLatex: "4 + (-2) = 2", explanation: "Sum the \\(x\\)-components. The negative sign on \\(\\mathbf{F_{2}}\\) reduces the total." }, { stepNumber: 4, description: "Add the j-components", workingLatex: "3 + 5 = 8", explanation: "Sum the \\(y\\)-components to get the second entry of the resultant." }, { stepNumber: 5, description: "Add the k-components", workingLatex: "0 + 1 = 1", explanation: "Sum the \\(z\\)-components. Only \\(\\mathbf{F_{2}}\\) has a \\(\\mathbf{k}\\)-component, so the result is \\(1\\)." }, { stepNumber: 6, description: "State the resultant vector", workingLatex: "\\mathbf{R} = 2\\mathbf{i} + 8\\mathbf{j} + \\mathbf{k}", explanation: "Assemble the summed components into the resultant force. Now find its magnitude." }, { stepNumber: 7, description: "Square each component", workingLatex: "2^2 = 4,\\quad 8^2 = 64,\\quad 1^2 = 1", explanation: "Square each component of \\(\\mathbf{R}\\) separately ahead of summing for the magnitude." }, { stepNumber: 8, description: "Sum the squares", workingLatex: "4 + 64 + 1 = 69", explanation: "Add the squared components. This sum sits under the square root." }, { stepNumber: 9, description: "Take the root for the magnitude", workingLatex: "|\\mathbf{R}| = \\sqrt{69} \\text{ N}", explanation: "Since \\(69\\) has no square factors, \\(\\sqrt{69}\\) is already in simplest surd form. Include the unit newtons." } ], finalAnswer: "\\(\\sqrt{69}\\) N." } },
  { id: "y2v2-028", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 28", difficulty: "Standard", questionText: "Find the value of \\(\\lambda\\) such that \\(\\mathbf{a} = \\lambda\\mathbf{i} + 2\\mathbf{j} - \\mathbf{k}\\) and \\(\\mathbf{b} = 3\\mathbf{i} + \\lambda\\mathbf{j} + 2\\mathbf{k}\\) are parallel.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["parallel"], workedSolution: { steps: [ { stepNumber: 1, description: "State the parallel condition", workingLatex: "\\mathbf{a} = k\\mathbf{b}", explanation: "Two non-zero vectors are parallel exactly when one is a scalar multiple of the other, so we must find a single \\(k\\) that works for every component." }, { stepNumber: 2, description: "Write the three component equations", workingLatex: "\\lambda = 3k,\\quad 2 = k\\lambda,\\quad -1 = 2k", explanation: "Equate \\(\\mathbf{i},\\mathbf{j},\\mathbf{k}\\) components of \\(\\mathbf{a}=k\\mathbf{b}\\) separately; the danger is mixing up which vector carries the \\(k\\)." }, { stepNumber: 3, description: "Solve the k-component for k", workingLatex: "-1 = 2k \\Rightarrow k = -\\tfrac{1}{2}", explanation: "The third component contains only \\(k\\), so it fixes the scalar immediately and is the cleanest place to start." }, { stepNumber: 4, description: "Substitute k into the i-component", workingLatex: "\\lambda = 3k = 3\\left(-\\tfrac{1}{2}\\right) = -\\tfrac{3}{2}", explanation: "Using the value of \\(k\\) in \\(\\lambda = 3k\\) gives the only candidate value of \\(\\lambda\\) consistent with the first and third components." }, { stepNumber: 5, description: "Test the j-component for consistency", workingLatex: "k\\lambda = \\left(-\\tfrac{1}{2}\\right)\\left(-\\tfrac{3}{2}\\right) = \\tfrac{3}{4}", explanation: "Every component equation must hold simultaneously, so we check the remaining \\(\\mathbf{j}\\) equation \\(2 = k\\lambda\\) with our values." }, { stepNumber: 6, description: "Compare with required value", workingLatex: "\\tfrac{3}{4} \\neq 2", explanation: "The \\(\\mathbf{j}\\)-component demands \\(k\\lambda = 2\\) but our forced values give \\(\\tfrac{3}{4}\\); the contradiction means no single \\(k\\) fits all three." }, { stepNumber: 7, description: "Conclude no value exists", workingLatex: "\\nexists\\,\\lambda : \\mathbf{a} \\parallel \\mathbf{b}", explanation: "Because the system is over-determined and inconsistent, there is no \\(\\lambda\\) making the vectors parallel." } ], finalAnswer: "No such \\(\\lambda\\)." } },
  { id: "y2v2-029", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 29", difficulty: "Standard", questionText: "Find the angle \\(\\mathbf{a} = 2\\mathbf{i} + \\mathbf{j} + 2\\mathbf{k}\\) makes with the \\(z\\)-axis.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["angle"], workedSolution: { steps: [ { stepNumber: 1, description: "Identify the z-axis direction vector", workingLatex: "\\mathbf{k} = (0, 0, 1)", explanation: "The angle a vector makes with the \\(z\\)-axis is the angle it makes with the unit vector \\(\\mathbf{k}\\), so we use \\(\\mathbf{k}\\) as the reference direction." }, { stepNumber: 2, description: "Compute the dot product with k", workingLatex: "\\mathbf{a}\\cdot\\mathbf{k} = 2(0) + 1(0) + 2(1) = 2", explanation: "Dotting with \\(\\mathbf{k}\\) simply picks out the \\(\\mathbf{k}\\)-component of \\(\\mathbf{a}\\); avoid the slip of using the \\(\\mathbf{i}\\)-component instead." }, { stepNumber: 3, description: "Square each component of a", workingLatex: "2^{2} = 4,\\quad 1^{2} = 1,\\quad 2^{2} = 4", explanation: "We square the components separately as the first stage of finding \\(|\\mathbf{a}|\\)." }, { stepNumber: 4, description: "Sum the squares", workingLatex: "4 + 1 + 4 = 9", explanation: "Adding the squared components gives the quantity under the root for the magnitude." }, { stepNumber: 5, description: "Take the magnitude of a", workingLatex: "|\\mathbf{a}| = \\sqrt{9} = 3", explanation: "Taking the square root gives \\(|\\mathbf{a}|=3\\); the surd simplifies to a whole number here." }, { stepNumber: 6, description: "Form the cosine ratio", workingLatex: "\\cos\\theta = \\frac{\\mathbf{a}\\cdot\\mathbf{k}}{|\\mathbf{a}||\\mathbf{k}|} = \\frac{2}{3\\cdot 1} = \\frac{2}{3}", explanation: "Since \\(|\\mathbf{k}|=1\\), the formula reduces to the \\(\\mathbf{k}\\)-component over \\(|\\mathbf{a}|\\), which is the direction cosine for the \\(z\\)-axis." }, { stepNumber: 7, description: "Invert to find the angle", workingLatex: "\\theta = \\cos^{-1}\\left(\\tfrac{2}{3}\\right) \\approx 48.2^{\\circ}", explanation: "Applying \\(\\cos^{-1}\\) in degrees gives the angle; keep the calculator in degree mode to avoid a radian answer." } ], finalAnswer: "\\(\\approx 48.2^{\\circ}\\)." } },
  { id: "y2v2-030", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 30", difficulty: "Standard", questionText: "Find the value of \\(p\\) so that \\(|\\mathbf{a}| = 7\\) for \\(\\mathbf{a} = 2\\mathbf{i} + p\\mathbf{j} + 6\\mathbf{k}\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["magnitude"], workedSolution: { steps: [ { stepNumber: 1, description: "Write the magnitude formula", workingLatex: "|\\mathbf{a}| = \\sqrt{2^{2} + p^{2} + 6^{2}}", explanation: "The magnitude of a 3D vector is the root of the sum of squared components; here the \\(\\mathbf{j}\\)-component is the unknown \\(p\\)." }, { stepNumber: 2, description: "Set the magnitude equal to 7", workingLatex: "\\sqrt{2^{2} + p^{2} + 6^{2}} = 7", explanation: "We impose the given condition \\(|\\mathbf{a}|=7\\) so we can solve for \\(p\\)." }, { stepNumber: 3, description: "Square both sides", workingLatex: "2^{2} + p^{2} + 6^{2} = 49", explanation: "Squaring removes the root; remember to square the right side to \\(49\\), not leave it as \\(7\\)." }, { stepNumber: 4, description: "Evaluate the known squares", workingLatex: "4 + p^{2} + 36 = 49", explanation: "Compute \\(2^2=4\\) and \\(6^2=36\\) to collect the constants." }, { stepNumber: 5, description: "Combine the constants", workingLatex: "p^{2} + 40 = 49", explanation: "Adding \\(4+36=40\\) tidies the equation before isolating \\(p^2\\)." }, { stepNumber: 6, description: "Isolate p squared", workingLatex: "p^{2} = 9", explanation: "Subtracting \\(40\\) from both sides leaves \\(p^2\\) alone." }, { stepNumber: 7, description: "Take both square roots", workingLatex: "p = \\pm\\sqrt{9} = \\pm 3", explanation: "Solving \\(p^2=9\\) gives two roots; forgetting the negative sign is the classic error since both signs give the same magnitude." } ], finalAnswer: "\\(p = \\pm 3\\)." } },
  { id: "y2v2-031", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 31", difficulty: "Standard", questionText: "A ship's position at time \\(t\\) is \\(\\mathbf{r}(t) = (1 + 3t, 2t, 0)\\) km. Find the ship's speed.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["applied", "kinematics"], workedSolution: { steps: [ { stepNumber: 1, description: "Write the position vector", workingLatex: "\\mathbf{r}(t) = (1 + 3t,\\ 2t,\\ 0)", explanation: "Speed is the magnitude of velocity, and velocity is the time-derivative of position, so we start from \\(\\mathbf{r}(t)\\)." }, { stepNumber: 2, description: "Differentiate each component", workingLatex: "\\mathbf{v} = \\frac{d\\mathbf{r}}{dt} = (3,\\ 2,\\ 0)", explanation: "Differentiating component-wise: the constants vanish and each \\(t\\)-coefficient remains, giving the constant velocity vector." }, { stepNumber: 3, description: "Square each velocity component", workingLatex: "3^{2} = 9,\\quad 2^{2} = 4,\\quad 0^{2} = 0", explanation: "We square the components individually as the first stage of finding the speed (the magnitude of \\(\\mathbf{v}\\))." }, { stepNumber: 4, description: "Sum the squares", workingLatex: "9 + 4 + 0 = 13", explanation: "Adding the squared components gives the value under the root." }, { stepNumber: 5, description: "Take the root for speed", workingLatex: "|\\mathbf{v}| = \\sqrt{13}", explanation: "Speed is \\(|\\mathbf{v}|=\\sqrt{13}\\); since \\(13\\) is prime the surd cannot be simplified further." }, { stepNumber: 6, description: "State speed with units", workingLatex: "\\text{speed} = \\sqrt{13}\\ \\text{km/h}", explanation: "Because position was in km and time in hours, the speed carries units km/h; do not drop the units in an applied answer." } ], finalAnswer: "\\(\\sqrt{13}\\) km/h." } },
  { id: "y2v2-032", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 32", difficulty: "Standard", questionText: "Given \\(\\mathbf{a}\\cdot\\mathbf{b} = 8\\), \\(|\\mathbf{a}| = 4\\), \\(|\\mathbf{b}| = 5\\), find the angle between \\(\\mathbf{a}\\) and \\(\\mathbf{b}\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["angle"], workedSolution: { steps: [ { stepNumber: 1, description: "Write the angle formula", workingLatex: "\\cos\\theta = \\frac{\\mathbf{a}\\cdot\\mathbf{b}}{|\\mathbf{a}||\\mathbf{b}|}", explanation: "The angle between two vectors comes from rearranging the dot-product definition \\(\\mathbf{a}\\cdot\\mathbf{b}=|\\mathbf{a}||\\mathbf{b}|\\cos\\theta\\)." }, { stepNumber: 2, description: "Substitute the given values", workingLatex: "\\cos\\theta = \\frac{8}{4\\cdot 5}", explanation: "We insert \\(\\mathbf{a}\\cdot\\mathbf{b}=8\\), \\(|\\mathbf{a}|=4\\), \\(|\\mathbf{b}|=5\\) directly; no components are needed since these are already supplied." }, { stepNumber: 3, description: "Multiply the magnitudes", workingLatex: "\\cos\\theta = \\frac{8}{20}", explanation: "Compute the denominator \\(4\\times 5 = 20\\) before simplifying the fraction." }, { stepNumber: 4, description: "Simplify the fraction", workingLatex: "\\cos\\theta = 0.4", explanation: "Reducing \\(\\tfrac{8}{20}\\) gives the cosine as a decimal ready for the inverse." }, { stepNumber: 5, description: "Invert to find the angle", workingLatex: "\\theta = \\cos^{-1}(0.4) \\approx 66.4^{\\circ}", explanation: "Applying \\(\\cos^{-1}\\) in degree mode gives the angle; a positive cosine confirms an acute angle as expected." } ], finalAnswer: "\\(\\approx 66.4^{\\circ}\\)." } },
  { id: "y2v2-033", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 33", difficulty: "Standard", questionText: "Show that \\(A(1, 1, 1),\\ B(2, 3, 5),\\ C(3, 5, 9)\\) are collinear.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["collinear"], workedSolution: { steps: [ { stepNumber: 1, description: "State the collinearity strategy", workingLatex: "A,B,C \\text{ collinear} \\iff \\vec{AB} \\parallel \\vec{BC}", explanation: "Three points lie on one line iff two displacement vectors sharing a point are scalar multiples; sharing \\(B\\) also guarantees a common point." }, { stepNumber: 2, description: "Compute vector AB", workingLatex: "\\vec{AB} = B - A = (2-1,\\ 3-1,\\ 5-1) = (1, 2, 4)", explanation: "Subtract position of \\(A\\) from \\(B\\) component-wise; the order (head minus tail) sets the direction." }, { stepNumber: 3, description: "Compute vector BC", workingLatex: "\\vec{BC} = C - B = (3-2,\\ 5-3,\\ 9-5) = (1, 2, 4)", explanation: "Likewise subtract \\(B\\) from \\(C\\); using the shared point \\(B\\) keeps the two vectors chained together." }, { stepNumber: 4, description: "Compare the two vectors", workingLatex: "\\vec{BC} = (1,2,4) = 1\\cdot\\vec{AB}", explanation: "The vectors are identical, so \\(\\vec{BC}=k\\,\\vec{AB}\\) with \\(k=1\\), confirming they are parallel." }, { stepNumber: 5, description: "Note the shared point", workingLatex: "\\vec{AB}\\parallel\\vec{BC},\\ \\text{common point } B", explanation: "Parallel vectors alone are not enough; sharing point \\(B\\) rules out parallel-but-separate lines." }, { stepNumber: 6, description: "Conclude collinearity", workingLatex: "\\therefore A, B, C \\text{ are collinear}", explanation: "Parallel displacements through a common point force all three points onto a single straight line." } ], finalAnswer: "Collinear." } },
  { id: "y2v2-034", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 34", difficulty: "Standard", questionText: "Calculate the area of the parallelogram with adjacent sides \\(\\mathbf{a} = (3, 4, 0)\\) and \\(\\mathbf{b} = (0, 0, 5)\\) using \\(A = |\\mathbf{a}||\\mathbf{b}|\\sin\\theta\\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["geometry"], workedSolution: { steps: [ { stepNumber: 1, description: "Compute the dot product", workingLatex: "\\mathbf{a}\\cdot\\mathbf{b} = 3(0) + 4(0) + 0(5) = 0", explanation: "We find the dot product to determine the angle \\(\\theta\\) between the sides, which the area formula requires." }, { stepNumber: 2, description: "Deduce the angle", workingLatex: "\\mathbf{a}\\cdot\\mathbf{b} = 0 \\Rightarrow \\theta = 90^{\\circ}", explanation: "A zero dot product means the vectors are perpendicular, so \\(\\sin\\theta=\\sin 90^{\\circ}=1\\)." }, { stepNumber: 3, description: "Find magnitude of a", workingLatex: "|\\mathbf{a}| = \\sqrt{3^{2}+4^{2}+0^{2}} = \\sqrt{25} = 5", explanation: "Square, sum, and root the components of \\(\\mathbf{a}\\); the \\(3,4,5\\) pattern gives a clean magnitude." }, { stepNumber: 4, description: "Find magnitude of b", workingLatex: "|\\mathbf{b}| = \\sqrt{0^{2}+0^{2}+5^{2}} = \\sqrt{25} = 5", explanation: "Only the \\(\\mathbf{k}\\)-component is non-zero, so \\(|\\mathbf{b}|=5\\)." }, { stepNumber: 5, description: "Write the area formula", workingLatex: "A = |\\mathbf{a}||\\mathbf{b}|\\sin\\theta", explanation: "The parallelogram area is the product of side lengths times the sine of the included angle, as stated in the question." }, { stepNumber: 6, description: "Substitute the values", workingLatex: "A = 5 \\cdot 5 \\cdot \\sin 90^{\\circ} = 5 \\cdot 5 \\cdot 1", explanation: "Insert the magnitudes and \\(\\sin 90^{\\circ}=1\\); forgetting that \\(\\sin 90^{\\circ}=1\\) (not \\(0\\)) is the common slip." }, { stepNumber: 7, description: "Evaluate the area", workingLatex: "A = 25", explanation: "Multiplying gives the area; the units would be square units of the original lengths." } ], finalAnswer: "25." } },
  { id: "y2v2-035", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 35", difficulty: "Standard", questionText: "The coordinates of three points are \\(A(1, 2, 0)\\), \\(B(4, 6, 0)\\), \\(C(1, 6, 0)\\). Classify the triangle.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["geometry"], workedSolution: { steps: [ { stepNumber: 1, description: "Compute side AB", workingLatex: "\\vec{AB} = (4-1,\\ 6-2,\\ 0-0) = (3, 4, 0)", explanation: "Subtract \\(A\\) from \\(B\\) to get the displacement along side \\(AB\\)." }, { stepNumber: 2, description: "Length of AB", workingLatex: "|AB| = \\sqrt{3^{2}+4^{2}+0^{2}} = \\sqrt{25} = 5", explanation: "Square, sum, and root the components to get the side length." }, { stepNumber: 3, description: "Compute side AC", workingLatex: "\\vec{AC} = (1-1,\\ 6-2,\\ 0-0) = (0, 4, 0)", explanation: "Subtract \\(A\\) from \\(C\\) to get the displacement along side \\(AC\\)." }, { stepNumber: 4, description: "Length of AC", workingLatex: "|AC| = \\sqrt{0^{2}+4^{2}+0^{2}} = \\sqrt{16} = 4", explanation: "Only the \\(y\\)-component is non-zero, so the length is \\(4\\)." }, { stepNumber: 5, description: "Compute side BC", workingLatex: "\\vec{BC} = (1-4,\\ 6-6,\\ 0-0) = (-3, 0, 0)", explanation: "Subtract \\(B\\) from \\(C\\); the sign does not affect the length we compute next." }, { stepNumber: 6, description: "Length of BC", workingLatex: "|BC| = \\sqrt{(-3)^{2}+0^{2}+0^{2}} = \\sqrt{9} = 3", explanation: "Squaring removes the negative sign, giving length \\(3\\)." }, { stepNumber: 7, description: "Test the Pythagorean relation", workingLatex: "3^{2} + 4^{2} = 9 + 16 = 25 = 5^{2}", explanation: "Check whether the two shorter sides' squares sum to the longest side's square; equality signals a right angle." }, { stepNumber: 8, description: "Classify the triangle", workingLatex: "|BC|^{2} + |AC|^{2} = |AB|^{2} \\Rightarrow \\text{right-angled at } C", explanation: "Since Pythagoras holds, the triangle is right-angled, with the right angle opposite the longest side \\(AB\\)." } ], finalAnswer: "Right-angled triangle." } },
  { id: "y2v2-036", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 36", difficulty: "Standard", questionText: "Given \\(\\mathbf{a} = \\mathbf{i} + 2\\mathbf{j} - 2\\mathbf{k}\\) and \\(\\mathbf{b} = 3\\mathbf{i} - 6\\mathbf{j} + 6\\mathbf{k}\\), show they are parallel and state the scalar.", marks: 2, examStyle: false, yearCreated: 2026, tags: ["parallel"], workedSolution: { steps: [ { stepNumber: 1, description: "State the parallel test", workingLatex: "\\mathbf{a} \\parallel \\mathbf{b} \\iff \\mathbf{b} = k\\mathbf{a}", explanation: "Parallel vectors require one common scalar \\(k\\) linking every component; we test for such a \\(k\\)." }, { stepNumber: 2, description: "Ratio of i-components", workingLatex: "\\frac{b_1}{a_1} = \\frac{3}{1} = 3", explanation: "Dividing the \\(\\mathbf{i}\\)-components gives a candidate scalar \\(k=3\\)." }, { stepNumber: 3, description: "Ratio of j-components", workingLatex: "\\frac{b_2}{a_2} = \\frac{-6}{2} = -3", explanation: "The \\(\\mathbf{j}\\)-component ratio gives \\(-3\\), which must match the previous ratio if the vectors are parallel." }, { stepNumber: 4, description: "Ratio of k-components", workingLatex: "\\frac{b_3}{a_3} = \\frac{6}{-2} = -3", explanation: "The \\(\\mathbf{k}\\)-component ratio also gives \\(-3\\); now we compare all three ratios." }, { stepNumber: 5, description: "Compare the ratios", workingLatex: "3 \\neq -3", explanation: "The \\(\\mathbf{i}\\)-ratio (\\(+3\\)) disagrees in sign with the other two (\\(-3\\)), so no single \\(k\\) works." }, { stepNumber: 6, description: "Conclude not parallel", workingLatex: "\\mathbf{b} \\neq k\\mathbf{a} \\Rightarrow \\mathbf{a} \\nparallel \\mathbf{b}", explanation: "Because the component ratios are not all equal, the vectors are not scalar multiples and hence not parallel." } ], finalAnswer: "Not parallel (signs inconsistent)." } },
  { id: "y2v2-037", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 37", difficulty: "Standard", questionText: "A particle moves so its position is \\(\\mathbf{r}(t) = (2t, t^{2}, 3)\\) m. Find the speed at \\(t = 1\\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["applied", "kinematics"], workedSolution: { steps: [ { stepNumber: 1, description: "State the position vector", workingLatex: "\\mathbf{r}(t) = (2t,\\ t^{2},\\ 3)", explanation: "Write down the given position-time function so each component can be differentiated separately. Velocity is the time-derivative of position, so we differentiate component-by-component next." }, { stepNumber: 2, description: "Differentiate the first component", workingLatex: "\\frac{d}{dt}(2t) = 2", explanation: "The \\(x\\)-component \\(2t\\) differentiates to the constant \\(2\\). Treat each component as an independent function of \\(t\\)." }, { stepNumber: 3, description: "Differentiate the second component", workingLatex: "\\frac{d}{dt}(t^{2}) = 2t", explanation: "Apply the power rule to \\(t^{2}\\) to get \\(2t\\). A common slip is forgetting the factor of \\(2\\) from the exponent." }, { stepNumber: 4, description: "Differentiate the third component", workingLatex: "\\frac{d}{dt}(3) = 0", explanation: "The constant \\(3\\) has zero derivative, so the particle has no motion in the \\(k\\)-direction. Constants always vanish on differentiation." }, { stepNumber: 5, description: "Assemble the velocity vector", workingLatex: "\\mathbf{v}(t) = (2,\\ 2t,\\ 0)", explanation: "Collect the three derivatives into the velocity vector \\(\\mathbf{v}(t)\\). This is valid for all \\(t\\)." }, { stepNumber: 6, description: "Substitute t = 1", workingLatex: "\\mathbf{v}(1) = (2,\\ 2(1),\\ 0) = (2,\\ 2,\\ 0)", explanation: "Evaluate the velocity at the required instant \\(t = 1\\). Speed is the magnitude of this specific velocity vector." }, { stepNumber: 7, description: "Write the magnitude formula", workingLatex: "|\\mathbf{v}(1)| = \\sqrt{2^{2} + 2^{2} + 0^{2}}", explanation: "Speed is \\(|\\mathbf{v}|\\), the square root of the sum of squared components. Include the zero term to keep all three dimensions accounted for." }, { stepNumber: 8, description: "Square and sum each component", workingLatex: "= \\sqrt{4 + 4 + 0} = \\sqrt{8}", explanation: "Square each component then add: \\(4 + 4 + 0 = 8\\). Squaring removes any sign, so direction does not affect speed." }, { stepNumber: 9, description: "Simplify the surd", workingLatex: "\\sqrt{8} = \\sqrt{4 \\cdot 2} = 2\\sqrt{2}", explanation: "Extract the perfect-square factor \\(4\\) from \\(8\\) to write the answer in exact surd form \\(2\\sqrt{2}\\) m/s rather than a rounded decimal." } ], finalAnswer: "\\(2\\sqrt{2}\\) m/s." } },
  { id: "y2v2-038", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 38", difficulty: "Standard", questionText: "The point \\(P\\) divides \\(AB\\) externally in ratio 3:1 where \\(A = (2, 0, 1)\\) and \\(B = (5, 3, 4)\\). Find \\(P\\) using \\(P = \\tfrac{-A + 3B}{2}\\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["section formula"], workedSolution: { steps: [ { stepNumber: 1, description: "State the external section formula", workingLatex: "P = \\frac{-A + 3B}{2}", explanation: "Use the formula supplied in the stem for an external division in ratio \\(3:1\\). The denominator \\(2\\) is the difference \\(3-1\\) of the ratio parts, characteristic of external division." }, { stepNumber: 2, description: "Write the two position vectors", workingLatex: "A = (2, 0, 1),\\quad B = (5, 3, 4)", explanation: "Record the coordinates of \\(A\\) and \\(B\\) so each component can be combined separately. Keep the order \\(A\\) then \\(B\\) consistent with the formula." }, { stepNumber: 3, description: "Compute negative A", workingLatex: "-A = (-2,\\ 0,\\ -1)", explanation: "Negate every component of \\(A\\). Sign errors here are the most common cause of a wrong external section point." }, { stepNumber: 4, description: "Compute three times B", workingLatex: "3B = (15,\\ 9,\\ 12)", explanation: "Multiply each component of \\(B\\) by \\(3\\). Scalar multiplication scales every component equally." }, { stepNumber: 5, description: "Add the two vectors", workingLatex: "-A + 3B = (-2+15,\\ 0+9,\\ -1+12) = (13,\\ 9,\\ 11)", explanation: "Add corresponding components. This numerator vector is twice the position of \\(P\\)." }, { stepNumber: 6, description: "Divide by two", workingLatex: "P = \\frac{(13,\\ 9,\\ 11)}{2} = (6.5,\\ 4.5,\\ 5.5)", explanation: "Divide each component by \\(2\\) to obtain \\(P\\). Halving all three gives the final coordinates of the external division point." } ], finalAnswer: "\\((6.5, 4.5, 5.5)\\)." } },
  { id: "y2v2-039", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 39", difficulty: "Standard", questionText: "A boat steers with velocity \\(\\mathbf{v_{b}} = 6\\mathbf{i} + 8\\mathbf{j}\\) m/s and a current has velocity \\(\\mathbf{v_{c}} = -2\\mathbf{i} + \\mathbf{j}\\) m/s. Find the ground velocity and ground speed.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["applied", "kinematics"], workedSolution: { steps: [ { stepNumber: 1, description: "State the ground velocity rule", workingLatex: "\\mathbf{v_{g}} = \\mathbf{v_{b}} + \\mathbf{v_{c}}", explanation: "Ground velocity is the vector sum of the boat's steered velocity and the current's velocity. Velocities add by the triangle (parallelogram) law." }, { stepNumber: 2, description: "Write the two velocities", workingLatex: "\\mathbf{v_{b}} = 6\\mathbf{i} + 8\\mathbf{j},\\quad \\mathbf{v_{c}} = -2\\mathbf{i} + \\mathbf{j}", explanation: "Record both velocities in component form. Note \\(\\mathbf{v_{c}}\\) has coefficient \\(+1\\) on \\(\\mathbf{j}\\)." }, { stepNumber: 3, description: "Add the i-components", workingLatex: "6 + (-2) = 4", explanation: "Combine the \\(\\mathbf{i}\\)-components. The current opposes the boat in the \\(x\\)-direction, reducing it from \\(6\\) to \\(4\\)." }, { stepNumber: 4, description: "Add the j-components", workingLatex: "8 + 1 = 9", explanation: "Combine the \\(\\mathbf{j}\\)-components. The current adds to the boat in the \\(y\\)-direction, giving \\(9\\)." }, { stepNumber: 5, description: "Write the ground velocity", workingLatex: "\\mathbf{v_{g}} = 4\\mathbf{i} + 9\\mathbf{j}", explanation: "Assemble the resultant velocity. This is the boat's actual velocity relative to the ground." }, { stepNumber: 6, description: "Set up the speed formula", workingLatex: "|\\mathbf{v_{g}}| = \\sqrt{4^{2} + 9^{2}}", explanation: "Ground speed is the magnitude of \\(\\mathbf{v_{g}}\\). Take the square root of the sum of squared components." }, { stepNumber: 7, description: "Square and sum the components", workingLatex: "= \\sqrt{16 + 81} = \\sqrt{97}", explanation: "Compute \\(16 + 81 = 97\\). Since \\(97\\) is prime it has no square factor, so the surd cannot be simplified." }, { stepNumber: 8, description: "Give the decimal value", workingLatex: "\\sqrt{97} \\approx 9.85", explanation: "Evaluate the root to give the ground speed \\(\\approx 9.85\\) m/s. Quote both the exact surd and the rounded value." } ], finalAnswer: "\\(4\\mathbf{i} + 9\\mathbf{j}\\); \\(\\sqrt{97} \\approx 9.85\\) m/s." } },
  { id: "y2v2-040", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 40", difficulty: "Standard", questionText: "Given \\(\\mathbf{a}\\) is perpendicular to \\(\\mathbf{b}\\), show that \\(|\\mathbf{a} + \\mathbf{b}|^{2} = |\\mathbf{a}|^{2} + |\\mathbf{b}|^{2}\\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["proof"], workedSolution: { steps: [ { stepNumber: 1, description: "Write magnitude as a dot product", workingLatex: "|\\mathbf{a} + \\mathbf{b}|^{2} = (\\mathbf{a} + \\mathbf{b}) \\cdot (\\mathbf{a} + \\mathbf{b})", explanation: "The squared magnitude of any vector equals its dot product with itself, \\(|\\mathbf{u}|^{2} = \\mathbf{u}\\cdot\\mathbf{u}\\). This converts a length into an expandable algebraic expression." }, { stepNumber: 2, description: "Expand using distributivity", workingLatex: "= \\mathbf{a}\\cdot\\mathbf{a} + \\mathbf{a}\\cdot\\mathbf{b} + \\mathbf{b}\\cdot\\mathbf{a} + \\mathbf{b}\\cdot\\mathbf{b}", explanation: "The dot product distributes over addition just like ordinary multiplication. Expand the bracket fully into four terms." }, { stepNumber: 3, description: "Use commutativity of the dot product", workingLatex: "\\mathbf{a}\\cdot\\mathbf{b} = \\mathbf{b}\\cdot\\mathbf{a}", explanation: "The dot product is commutative, so the two cross terms are equal and combine into \\(2\\,\\mathbf{a}\\cdot\\mathbf{b}\\)." }, { stepNumber: 4, description: "Rewrite self-dot-products as squares", workingLatex: "= |\\mathbf{a}|^{2} + 2\\,\\mathbf{a}\\cdot\\mathbf{b} + |\\mathbf{b}|^{2}", explanation: "Replace \\(\\mathbf{a}\\cdot\\mathbf{a}\\) by \\(|\\mathbf{a}|^{2}\\) and \\(\\mathbf{b}\\cdot\\mathbf{b}\\) by \\(|\\mathbf{b}|^{2}\\). This mirrors the scalar identity \\((a+b)^{2} = a^{2} + 2ab + b^{2}\\)." }, { stepNumber: 5, description: "Apply the perpendicularity condition", workingLatex: "\\mathbf{a} \\perp \\mathbf{b} \\Rightarrow \\mathbf{a}\\cdot\\mathbf{b} = 0", explanation: "Perpendicular vectors have a zero dot product because \\(\\cos 90^{\\circ} = 0\\). This is the key hypothesis that kills the cross term." }, { stepNumber: 6, description: "Cancel the cross term", workingLatex: "= |\\mathbf{a}|^{2} + 2(0) + |\\mathbf{b}|^{2}", explanation: "Substitute \\(\\mathbf{a}\\cdot\\mathbf{b} = 0\\) so the middle term vanishes entirely. Only the two squared magnitudes survive." }, { stepNumber: 7, description: "State the result", workingLatex: "|\\mathbf{a} + \\mathbf{b}|^{2} = |\\mathbf{a}|^{2} + |\\mathbf{b}|^{2}", explanation: "This is the required Pythagorean identity for perpendicular vectors, completing the proof. \\(\\blacksquare\\)" } ], finalAnswer: "Shown (Pythagorean identity for vectors)." } },
  { id: "y2v2-041", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 41", difficulty: "Challenge", questionText: "A plane flies from \\(A(10, 5, 2)\\) km with a constant velocity \\(\\mathbf{v} = 30\\mathbf{i} + 20\\mathbf{j} + 8\\mathbf{k}\\) km/h. Find (a) the position after 45 minutes, (b) the distance from the origin at that moment.", marks: 7, examStyle: true, yearCreated: 2026, tags: ["applied", "kinematics"], workedSolution: { steps: [ { stepNumber: 1, description: "State the constant-velocity position law", workingLatex: "\\mathbf{r}(t) = \\mathbf{r_{0}} + t\\,\\mathbf{v}", explanation: "When velocity is constant the path is a straight line, so the displacement from the start is simply velocity multiplied by elapsed time, with no acceleration term. Geometrically \\(\\mathbf{r}(t)\\) traces the ray that leaves \\(A\\) in the fixed direction of \\(\\mathbf{v}\\). Recognise this law whenever a problem says \"constant velocity\" and gives a starting point — there is no need for the full \\(\\mathbf{r_0}+\\mathbf{u}t+\\tfrac12\\mathbf{a}t^2\\) here. The common slip is to forget the \\(\\mathbf{r_0}\\) term and report only the displacement." }, { stepNumber: 2, description: "Identify the start point and velocity", workingLatex: "\\mathbf{r_{0}} = (10,\\ 5,\\ 2),\\quad \\mathbf{v} = (30,\\ 20,\\ 8)", explanation: "The plane begins at \\(A(10,5,2)\\) km and moves with \\(\\mathbf{v}=30\\mathbf{i}+20\\mathbf{j}+8\\mathbf{k}\\) km/h. Writing both as ordered triples now means the later vector arithmetic is just three parallel number lines. Keeping units in mind — kilometres for position, km/h for velocity — flags that a time conversion is coming." }, { stepNumber: 3, description: "Convert the time to hours", workingLatex: "t = \\frac{45}{60} = 0.75\\ \\text{h}", explanation: "Because the velocity is quoted per hour, the time must also be in hours for the product \\(t\\mathbf{v}\\) to carry units of kilometres. Substituting \\(t=45\\) (minutes) would inflate every displacement by a factor of \\(60\\), the single most common error in this kind of question. As a sanity check, \\(45\\) minutes is three-quarters of an hour, matching \\(0.75\\)." }, { stepNumber: 4, description: "Scale velocity to get displacement", workingLatex: "t\\,\\mathbf{v} = 0.75\\,(30,\\ 20,\\ 8) = (22.5,\\ 15,\\ 6)", explanation: "Multiplying the velocity by \\(0.75\\) gives how far the plane travels along each axis in the three-quarters of an hour. This vector is the straight-line shift from \\(A\\), pointing the same way as \\(\\mathbf{v}\\) but shorter. Multiply each component independently: \\(30\\to22.5\\), \\(20\\to15\\), \\(8\\to6\\); a frequent slip is scaling only the first component." }, { stepNumber: 5, description: "Add displacement to the start point", workingLatex: "\\mathbf{r}(0.75) = (10,\\ 5,\\ 2) + (22.5,\\ 15,\\ 6)", explanation: "Adding the displacement to the initial position tip-to-tail relocates the plane in space. Only matching components combine — \\(x\\) with \\(x\\), and so on — which is why aligning the triples vertically helps. Do not mix the start coordinates with the velocity components." }, { stepNumber: 6, description: "State the position after 45 minutes", workingLatex: "\\mathbf{r}(0.75) = (32.5,\\ 20,\\ 8)", explanation: "Summing each axis gives the plane's location, answering part (a). Notice the \\(z\\)-coordinate is \\(2+6=8\\): the plane has climbed only \\(6\\) km while moving \\(22.5\\) km east, consistent with the small \\(\\mathbf{k}\\)-component of the velocity. A quick reasonableness check is that every coordinate has grown, as expected for all-positive velocity." }, { stepNumber: 7, description: "Set up distance as a magnitude", workingLatex: "|\\mathbf{r}| = \\sqrt{32.5^{2} + 20^{2} + 8^{2}}", explanation: "Distance from the origin is the length of the position vector, i.e. the 3D Pythagoras applied to its coordinates. This works because the origin is the reference point; if a distance from another point were wanted, we would first subtract that point. Square every coordinate before adding — never add then square." }, { stepNumber: 8, description: "Square the largest coordinate", workingLatex: "32.5^{2} = 1056.25", explanation: "Squaring the decimal \\(32.5\\) needs care: \\(32.5^2 = (32+0.5)^2 = 1024 + 32 + 0.25\\). This term dominates the sum because \\(32.5\\) is by far the largest coordinate, so an error here would skew the final distance most. Writing the full four-figure decimal avoids premature rounding." }, { stepNumber: 9, description: "Square the remaining coordinates", workingLatex: "20^{2} = 400,\\quad 8^{2} = 64", explanation: "Evaluating these separately keeps the arithmetic clean before the final sum. Both are exact integers, so they contribute no rounding. The relative sizes — \\(400\\) and \\(64\\) against \\(1056.25\\) — confirm the \\(x\\)-direction is the principal contributor to the distance." }, { stepNumber: 10, description: "Sum the squared coordinates", workingLatex: "1056.25 + 400 + 64 = 1520.25", explanation: "Adding the three squares gives the radicand. Aligning the decimal point matters here since only the first term has a fractional part. This total is the squared distance in \\(\\text{km}^2\\)." }, { stepNumber: 11, description: "Take the root for the distance", workingLatex: "|\\mathbf{r}| = \\sqrt{1520.25} \\approx 38.99", explanation: "The square root converts the squared distance back to kilometres, giving \\(\\approx 38.99\\) km and answering part (b). A sanity check: the largest coordinate is \\(32.5\\), and the true straight-line distance must exceed any single coordinate but stay below their sum \\(60.5\\) — \\(38.99\\) sits comfortably in that range. Keep the calculator in exact mode until the last step to avoid rounding drift." } ], finalAnswer: "Position \\((32.5, 20, 8)\\); distance \\(\\approx 38.99\\) km." } },
  { id: "y2v2-042", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 42", difficulty: "Challenge", questionText: "Two planes fly with constant velocities \\(\\mathbf{v_{1}} = 2\\mathbf{i} + 3\\mathbf{j}\\) km/h starting from \\(A(0, 0, 0)\\) and \\(\\mathbf{v_{2}} = \\mathbf{i} + 4\\mathbf{j}\\) km/h starting from \\(B(5, 0, 0)\\). Find the time at which they are closest and the minimum distance.", marks: 8, examStyle: true, yearCreated: 2026, tags: ["applied", "kinematics"], workedSolution: { steps: [ { stepNumber: 1, description: "Write position of plane 1", workingLatex: "\\mathbf{r_{1}}(t) = (0,0) + t(2,3) = (2t,\\ 3t)", explanation: "Each plane moves in a straight line, so its position is start plus time-scaled velocity. Plane 1 leaves the origin, so its location is purely \\(t\\) times its velocity, sweeping out the line \\(y=\\tfrac32 x\\). Both planes have zero \\(z\\)-component, so the whole problem collapses to a 2D plane — work in two coordinates throughout to save effort." }, { stepNumber: 2, description: "Write position of plane 2", workingLatex: "\\mathbf{r_{2}}(t) = (5,0) + t(1,4) = (5 + t,\\ 4t)", explanation: "Plane 2 starts \\(5\\) km east of plane 1 along the \\(x\\)-axis and drifts with velocity \\((1,4)\\). The constant \\(5\\) stays in the \\(x\\)-component for all time, encoding the initial head start. The common slip is to add the start point to the wrong component, so keep \\((5,0)\\) explicitly separate from \\(t(1,4)\\)." }, { stepNumber: 3, description: "Form the separation vector", workingLatex: "\\mathbf{d}(t) = \\mathbf{r_{2}} - \\mathbf{r_{1}} = (5 + t - 2t,\\ 4t - 3t)", explanation: "Subtracting the position vectors gives the vector pointing from plane 1 to plane 2, whose length is the gap between them. Tracking this single vector reduces a two-body problem to one moving point relative to the other. The direction of subtraction is irrelevant to the distance, since \\(|\\mathbf{d}|=|-\\mathbf{d}|\\)." }, { stepNumber: 4, description: "Simplify the separation", workingLatex: "\\mathbf{d}(t) = (5 - t,\\ t)", explanation: "Collecting like terms in each component gives a clean linear-in-\\(t\\) separation. The \\(x\\)-gap shrinks from \\(5\\) as \\(t\\) grows while the \\(y\\)-gap opens up, so the planes approach then recede — this competition is exactly why a finite minimum exists. Mishandling the signs when combining \\(5+t-2t\\) is the usual error; it is \\(5-t\\), not \\(5+t\\)." }, { stepNumber: 5, description: "Write the squared distance", workingLatex: "d^{2}(t) = (5 - t)^{2} + t^{2}", explanation: "We minimise \\(d^2\\) rather than \\(d\\) because the square root is a strictly increasing function, so both reach their minimum at the same \\(t\\), and a polynomial is far easier to differentiate than a root. Geometrically \\(d^2\\) is the sum of the squared axis-gaps. This avoids ever differentiating an awkward \\(\\sqrt{\\,}\\)." }, { stepNumber: 6, description: "Expand the squared bracket", workingLatex: "d^{2}(t) = 25 - 10t + t^{2} + t^{2}", explanation: "Expanding \\((5-t)^2\\) gives \\(25-10t+t^2\\); the cross term is \\(-2\\cdot5\\cdot t=-10t\\), and a dropped or mis-signed cross term is the classic mistake here. Keep the second \\(t^2\\) (from the \\(y\\)-component) written separately for now so nothing is lost. Every term is exact." }, { stepNumber: 7, description: "Collect into a quadratic", workingLatex: "d^{2}(t) = 2t^{2} - 10t + 25", explanation: "Combining the two \\(t^2\\) terms yields an upward-opening parabola in \\(t\\) (positive leading coefficient), so its single turning point is guaranteed to be a minimum. This shape confirms physically that the planes have exactly one moment of closest approach. The vertex could even be found by completing the square, but calculus is used next." }, { stepNumber: 8, description: "Differentiate the squared distance", workingLatex: "\\frac{d}{dt}\\big(d^{2}\\big) = 4t - 10", explanation: "Differentiating locates the stationary point where the rate of change of separation is zero — the instant the planes stop approaching and begin receding. The derivative of \\(2t^2\\) is \\(4t\\) and of \\(-10t\\) is \\(-10\\); the constant \\(25\\) vanishes. Differentiating \\(d^2\\) is legitimate precisely because its minimum coincides with that of \\(d\\)." }, { stepNumber: 9, description: "Solve for the closest-approach time", workingLatex: "4t - 10 = 0 \\Rightarrow t = 2.5", explanation: "Setting the derivative to zero and solving gives \\(t=2.5\\) h. The positive \\(t^2\\)-coefficient (\\(2>0\\)) confirms this is a minimum rather than a maximum, so a second-derivative test is unnecessary. Since \\(t\\ge0\\) is physically required, this value is admissible." }, { stepNumber: 10, description: "Substitute back into the quadratic", workingLatex: "d^{2}(2.5) = 2(2.5)^{2} - 10(2.5) + 25", explanation: "Putting \\(t=2.5\\) back into \\(d^2\\) recovers the minimum squared separation. Substituting into the simplified quadratic is quicker and less error-prone than going back to \\((5-t)^2+t^2\\). Use the \\(d^2\\) form, not the derivative, at this stage — a frequent confusion." }, { stepNumber: 11, description: "Evaluate the minimum squared distance", workingLatex: "d^{2}(2.5) = 12.5 - 25 + 25 = 12.5", explanation: "Here \\(2\\times(2.5)^2=2\\times6.25=12.5\\), and the linear and constant terms \\(-25\\) and \\(+25\\) cancel, leaving \\(12.5\\,\\text{km}^2\\). The cancellation is a neat consequence of evaluating at the vertex. This is the smallest the squared gap ever gets." }, { stepNumber: 12, description: "Take the root and simplify", workingLatex: "d = \\sqrt{12.5} = \\sqrt{\\tfrac{25}{2}} = \\frac{5}{\\sqrt{2}}", explanation: "Rewriting \\(12.5\\) as \\(\\tfrac{25}{2}\\) lets the numerator's perfect square come out as \\(5\\), giving the exact minimum distance \\(\\tfrac{5}{\\sqrt2}\\approx3.54\\) km. An exact surd answer is preferred over a decimal in pure work. Check: this is below the initial \\(5\\) km gap, as it must be since the planes do approach before separating." } ], finalAnswer: "\\(t = 2.5\\) h; \\(\\tfrac{5}{\\sqrt{2}}\\) km." } },
  { id: "y2v2-043", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 43", difficulty: "Challenge", questionText: "A rigid triangle \\(ABC\\) has vertices \\(A(0, 0, 0)\\), \\(B(5, 0, 0)\\), \\(C(2, 3, 4)\\). Find the area of \\(\\triangle ABC\\).", marks: 6, examStyle: true, yearCreated: 2026, tags: ["geometry"], workedSolution: { steps: [ { stepNumber: 1, description: "Choose a common hinge vertex", workingLatex: "\\mathbf{AB} = B - A,\\quad \\mathbf{AC} = C - A", explanation: "The triangle's area is governed by two edges meeting at a common vertex; we pick \\(A\\) as that hinge. Subtracting position vectors turns the three points into two free direction vectors lying in the triangle's plane. Any vertex could serve as the hinge — the area is the same — but reusing the origin vertex \\(A(0,0,0)\\) keeps the subtraction trivial." }, { stepNumber: 2, description: "Compute edge AB", workingLatex: "\\mathbf{AB} = (5-0,\\ 0-0,\\ 0-0) = (5, 0, 0)", explanation: "Component-wise subtraction gives \\(\\mathbf{AB}=(5,0,0)\\), a vector lying flat along the \\(x\\)-axis with length \\(5\\). That it has only one non-zero component reflects \\(B\\) sitting directly east of \\(A\\). Because \\(A\\) is the origin, \\(\\mathbf{AB}\\) is just \\(B\\)'s coordinates." }, { stepNumber: 3, description: "Compute edge AC", workingLatex: "\\mathbf{AC} = (2-0,\\ 3-0,\\ 4-0) = (2, 3, 4)", explanation: "Likewise \\(\\mathbf{AC}=(2,3,4)\\), a vector that rises out of the \\(xy\\)-plane because of its non-zero \\(z\\)-component. Together \\(\\mathbf{AB}\\) and \\(\\mathbf{AC}\\) span the slanted plane in which the triangle sits. These two vectors, not the original points, drive every remaining step." }, { stepNumber: 4, description: "State the cross-product area formula", workingLatex: "\\text{Area} = \\tfrac{1}{2}\\,|\\mathbf{AB} \\times \\mathbf{AC}|", explanation: "The magnitude of the cross product equals the area of the parallelogram spanned by the two edges, and the triangle is exactly half of that parallelogram. This method is preferred over \\(\\tfrac12 ab\\sin C\\) in 3D because the cross product builds the \\(\\sin\\theta\\) factor in automatically, with no need to find the angle. It works in 3D where a simple base-times-height is awkward." }, { stepNumber: 5, description: "Set up the cross-product minors", workingLatex: "\\mathbf{AB} \\times \\mathbf{AC} = \\begin{pmatrix} 0\\cdot4 - 0\\cdot3 \\\\ 0\\cdot2 - 5\\cdot4 \\\\ 5\\cdot3 - 0\\cdot2 \\end{pmatrix}", explanation: "The cross product is computed from the determinant of the \\(2\\times2\\) minors of the two component rows. The middle (\\(\\mathbf{j}\\)) entry carries a built-in sign reversal, written here as \\(AB_z AC_x - AB_x AC_z\\); mishandling that minus is the single most common cross-product error. Lay the components out in order so each minor pairs the correct entries." }, { stepNumber: 6, description: "Evaluate the i and j components", workingLatex: "i:\\ 0\\cdot4 - 0\\cdot3 = 0,\\qquad j:\\ 0\\cdot2 - 5\\cdot4 = -20", explanation: "The \\(\\mathbf{i}\\)-component vanishes because both \\(y\\)- and \\(z\\)-entries of \\(\\mathbf{AB}\\) are zero, while the \\(\\mathbf{j}\\)-component evaluates to \\(-20\\). The negative \\(\\mathbf{j}\\)-value comes directly from that swapped-order minor, and getting its sign right is the crux of the calculation. Keeping the two components separate here makes the sign easy to audit." }, { stepNumber: 7, description: "Evaluate the k component", workingLatex: "k:\\ 5\\cdot3 - 0\\cdot2 = 15 \\;\\Rightarrow\\; \\mathbf{AB} \\times \\mathbf{AC} = (0,\\ -20,\\ 15)", explanation: "The \\(\\mathbf{k}\\)-component is \\(15-0=15\\), completing the normal vector \\((0,-20,15)\\) perpendicular to the triangle's plane — which is why its length captures the spanned area. As a quick check, dotting it with either edge should give zero; e.g. \\((0,-20,15)\\cdot(5,0,0)=0\\). This orthogonality confirms the cross product was assembled correctly." }, { stepNumber: 8, description: "Square and sum the components", workingLatex: "0^{2} + (-20)^{2} + 15^{2} = 0 + 400 + 225 = 625", explanation: "Squaring each component and summing gives \\(625\\), the squared length of the normal. Squaring removes the sign on \\(-20\\), so the negative component causes no trouble. That the radicand is a perfect square is a reassuring sign the earlier arithmetic was clean." }, { stepNumber: 9, description: "Take the root for the parallelogram area", workingLatex: "|\\mathbf{AB} \\times \\mathbf{AC}| = \\sqrt{625} = 25", explanation: "The square root of \\(625\\) is the tidy value \\(25\\), which is the area of the parallelogram spanned by the two edges. This magnitude already encodes the \\(|\\mathbf{AB}||\\mathbf{AC}|\\sin\\theta\\) product, so no angle was ever needed. The triangle is half of this region." }, { stepNumber: 10, description: "Halve to get the triangle area", workingLatex: "\\text{Area} = \\tfrac{1}{2}(25) = 12.5", explanation: "Halving the parallelogram area gives the triangle's area, \\(12.5\\) square units. The factor of one half is the only thing separating the parallelogram from the triangle, so never omit it. As a rough check, \\(\\mathbf{AB}\\) has length \\(5\\) and \\(C\\) sits a few units off that base, so an area around \\(12\\)–\\(13\\) is plausible." } ], finalAnswer: "12.5." } },
  { id: "y2v2-044", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 44", difficulty: "Challenge", questionText: "A rod has one end at \\(A(0, 0, 0)\\) and extends in the direction of \\(\\mathbf{d} = (2, 1, 2)\\). A force \\(\\mathbf{F} = (3, 4, 0)\\) N is applied at the free end. Find the component of this force along the rod.", marks: 5, examStyle: true, yearCreated: 2026, tags: ["applied", "scalar product"], workedSolution: { steps: [ { stepNumber: 1, description: "Identify the rod's direction vector", workingLatex: "\\mathbf{d} = (2, 1, 2)", explanation: "The rod points along \\(\\mathbf{d}=(2,1,2)\\), and the \"component of force along the rod\" is the scalar projection of \\(\\mathbf{F}\\) onto this line. Physically this is the part of the push that acts to stretch or compress the rod, the part that does work along its axis. The perpendicular part of \\(\\mathbf{F}\\) would instead bend the rod and is discarded here." }, { stepNumber: 2, description: "Note the applied force vector", workingLatex: "\\mathbf{F} = (3, 4, 0)\\ \\text{N}", explanation: "The force has components only in \\(x\\) and \\(y\\), with nothing along \\(z\\). Its magnitude is \\(|\\mathbf F|=\\sqrt{9+16}=5\\) N, a useful upper bound for any projected component. Recording \\(\\mathbf{F}\\) cleanly now avoids mismatching its entries with the rod's later." }, { stepNumber: 3, description: "Write the scalar-projection definition", workingLatex: "F_{\\parallel} = \\mathbf{F} \\cdot \\hat{\\mathbf{d}}", explanation: "The component along a direction is the dot product of the force with the unit vector in that direction; the dot product naturally extracts \\(|\\mathbf F|\\cos\\theta\\). It is essential to project onto a unit vector — using the raw \\(\\mathbf{d}\\) would scale the answer by \\(|\\mathbf{d}|\\) and give a wrong, dimensionally inconsistent result. So a normalisation step must come first." }, { stepNumber: 4, description: "Square the rod's components", workingLatex: "2^{2} + 1^{2} + 2^{2} = 4 + 1 + 4 = 9", explanation: "To find the rod's length we first sum the squares of its components, getting \\(9\\). Squaring before rooting is the correct order; squaring the sum instead would be wrong. The clean total \\(9\\) hints the length will be a whole number." }, { stepNumber: 5, description: "Find the magnitude of d", workingLatex: "|\\mathbf{d}| = \\sqrt{9} = 3", explanation: "The length \\(|\\mathbf{d}|=3\\) is needed to rescale \\(\\mathbf{d}\\) to unit length. The neat value \\(3\\) (a \\(2,1,2\\) Pythagorean-style triple) makes the upcoming division clean. This magnitude is the normalising factor for the direction." }, { stepNumber: 6, description: "Form the unit direction vector", workingLatex: "\\hat{\\mathbf{d}} = \\tfrac{1}{3}(2, 1, 2)", explanation: "Dividing \\(\\mathbf{d}\\) by its length gives a unit vector pointing along the rod but with magnitude exactly \\(1\\), so it encodes pure direction. Keeping the \\(\\tfrac13\\) as a common factor outside the bracket is cleaner than writing three separate fractions. This unit vector is what makes the projection give a true force component in newtons." }, { stepNumber: 7, description: "Substitute force and unit vector", workingLatex: "F_{\\parallel} = \\tfrac{1}{3}\\big(3\\cdot2 + 4\\cdot1 + 0\\cdot2\\big)", explanation: "Inserting \\(\\mathbf{F}=(3,4,0)\\) and \\(\\hat{\\mathbf{d}}=\\tfrac13(2,1,2)\\), the dot product pairs matching components and the shared \\(\\tfrac13\\) factors out front. Note the \\(z\\)-term \\(0\\cdot2\\) vanishes because the force has no \\(z\\)-component, even though the rod does. Pairing components in the right order is critical." }, { stepNumber: 8, description: "Multiply matching components", workingLatex: "3\\cdot2 = 6,\\quad 4\\cdot1 = 4,\\quad 0\\cdot2 = 0", explanation: "Each pair of matching components multiplies independently: \\(6\\), \\(4\\) and \\(0\\). The vanishing \\(z\\)-term reflects that the force does nothing in the direction where it has no component. Computing them separately reduces the chance of a sign or pairing slip." }, { stepNumber: 9, description: "Sum the products", workingLatex: "6 + 4 + 0 = 10", explanation: "Adding the three products gives \\(10\\), the raw dot product \\(\\mathbf F\\cdot\\mathbf d\\) before the \\(\\tfrac13\\) normalisation. This is the projection scaled up by \\(|\\mathbf d|\\). Dividing by \\(3\\) next restores the true component." }, { stepNumber: 10, description: "Divide by the rod length", workingLatex: "F_{\\parallel} = \\tfrac{1}{3}(10) = \\tfrac{10}{3}", explanation: "Dividing by \\(3\\) yields \\(\\tfrac{10}{3}\\approx3.33\\) N along the rod. The result is positive, meaning the force has a genuine pulling component in the rod's direction rather than against it. As a sanity check, \\(\\tfrac{10}{3}\\) is comfortably less than \\(|\\mathbf F|=5\\) N, exactly as a projected component must be." } ], finalAnswer: "\\(\\tfrac{10}{3}\\) N." } },
  { id: "y2v2-045", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 45", difficulty: "Challenge", questionText: "A particle moves so that its position at time \\(t\\) s is \\(\\mathbf{r}(t) = (t^{2}, 2t, 3 - t)\\) m. Find the velocity and acceleration at \\(t = 2\\) and the speed at \\(t = 2\\).", marks: 6, examStyle: true, yearCreated: 2026, tags: ["applied", "kinematics"], workedSolution: { steps: [ { stepNumber: 1, description: "State the position vector", workingLatex: "\\mathbf{r}(t) = (t^{2},\\ 2t,\\ 3 - t)", explanation: "The position function gives the particle's location at any instant, with each component a separate function of \\(t\\). Differentiating once yields velocity and twice yields acceleration, so this expression is the source of everything asked. Note the components are independent, so the calculus can be done axis by axis." }, { stepNumber: 2, description: "Set up componentwise differentiation", workingLatex: "\\mathbf{v}(t) = \\Big(\\tfrac{d}{dt}t^{2},\\ \\tfrac{d}{dt}2t,\\ \\tfrac{d}{dt}(3 - t)\\Big)", explanation: "Velocity is the time-derivative of position, computed component by component because differentiation is linear and the axes are independent. Setting out each derivative explicitly guards against skipping a term. The \\(z\\)-component \\(3-t\\) is where a sign error most often creeps in, so it is kept visible here." }, { stepNumber: 3, description: "Differentiate each component", workingLatex: "\\tfrac{d}{dt}t^{2} = 2t,\\quad \\tfrac{d}{dt}2t = 2,\\quad \\tfrac{d}{dt}(3-t) = -1", explanation: "Applying the power rule gives \\(t^2\\to2t\\), the linear term \\(2t\\to2\\), and the constant-minus-linear \\(3-t\\to-1\\). The constant \\(3\\) differentiates away, while \\(-t\\) leaves \\(-1\\) — that minus sign is essential and easily dropped. Doing the three derivatives side by side keeps each rule explicit." }, { stepNumber: 4, description: "Assemble the velocity function", workingLatex: "\\mathbf{v}(t) = (2t,\\ 2,\\ -1)", explanation: "Collecting the three derivatives gives the velocity field valid for all \\(t\\). Only the \\(x\\)-velocity still depends on time; the other two components are constant. This is the function we evaluate at the requested instant and differentiate again for acceleration." }, { stepNumber: 5, description: "Differentiate again for acceleration", workingLatex: "\\mathbf{a}(t) = (2,\\ 0,\\ 0)", explanation: "Acceleration is the derivative of velocity: \\(2t\\to2\\), while the constants \\(2\\) and \\(-1\\) differentiate to \\(0\\). The acceleration is therefore constant and purely in the \\(x\\)-direction, telling us the only changing speed is along \\(x\\). A constant acceleration here also means the motion's \\(x\\)-part is uniformly accelerated, like projectile-style motion confined to one axis." }, { stepNumber: 6, description: "Evaluate velocity at t = 2", workingLatex: "\\mathbf{v}(2) = (2\\cdot2,\\ 2,\\ -1) = (4,\\ 2,\\ -1)", explanation: "Substituting \\(t=2\\) updates only the time-dependent \\(x\\)-component to \\(4\\); the others are already constant. This is the instantaneous velocity vector at the requested moment, pointing forward in \\(x\\) and \\(y\\) but downward in \\(z\\). Substitute only into terms containing \\(t\\) to avoid needless re-evaluation." }, { stepNumber: 7, description: "State acceleration at t = 2", workingLatex: "\\mathbf{a}(2) = (2,\\ 0,\\ 0)", explanation: "Since the acceleration is independent of \\(t\\), its value at \\(t=2\\) is the same \\((2,0,0)\\,\\text{m s}^{-2}\\) as at every instant. There is nothing to substitute. This constancy is a useful check: a position quadratic in only one coordinate must give acceleration along only that axis." }, { stepNumber: 8, description: "Set up the speed formula", workingLatex: "|\\mathbf{v}(2)| = \\sqrt{4^{2} + 2^{2} + (-1)^{2}}", explanation: "Speed is the magnitude of the velocity vector, found by 3D Pythagoras on its components. Squaring \\(-1\\) gives \\(+1\\), so the downward \\(z\\)-motion still adds to the speed — speed is direction-blind. Remember to square each component before summing, not the other way around." }, { stepNumber: 9, description: "Square and sum the components", workingLatex: "4^{2} + 2^{2} + (-1)^{2} = 16 + 4 + 1 = 21", explanation: "Squaring each velocity component gives \\(16\\), \\(4\\) and \\(1\\), summing to \\(21\\). The \\((-1)^2=1\\) confirms the negative \\(z\\)-velocity contributes positively, since squaring erases sign. This total is the squared speed under the root." }, { stepNumber: 10, description: "Take the root for the speed", workingLatex: "|\\mathbf{v}(2)| = \\sqrt{21}", explanation: "Rooting \\(21\\) gives the speed \\(\\sqrt{21}\\approx4.58\\) m/s. Since \\(21=3\\times7\\) has no square factor, the surd cannot be simplified and is the exact answer. As a check, the speed must exceed the largest single component \\(4\\) but stay below their sum \\(7\\), and \\(4.58\\) fits that window." } ], finalAnswer: "\\(\\mathbf{v} = (4, 2, -1),\\ \\mathbf{a} = (2, 0, 0),\\ |\\mathbf{v}| = \\sqrt{21}\\) m/s." } },
  { id: "y2v2-046", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 46", difficulty: "Challenge", questionText: "Find the values of \\(\\lambda\\) for which \\(\\mathbf{a} = \\lambda\\mathbf{i} + 2\\mathbf{j} + 3\\mathbf{k}\\) and \\(\\mathbf{b} = \\mathbf{i} - \\lambda\\mathbf{j} + 4\\mathbf{k}\\) are perpendicular, and hence find one such pair of vectors.", marks: 5, examStyle: true, yearCreated: 2026, tags: ["perpendicular"], workedSolution: { steps: [ { stepNumber: 1, description: "State the perpendicularity condition", workingLatex: "\\mathbf{a} \\perp \\mathbf{b} \\iff \\mathbf{a}\\cdot\\mathbf{b} = 0", explanation: "Two non-zero vectors are perpendicular exactly when their dot product is zero, because \\(\\mathbf{a}\\cdot\\mathbf{b}=|\\mathbf{a}||\\mathbf{b}|\\cos\\theta\\) and \\(\\cos90^\\circ=0\\). This turns a geometric condition into a single algebraic equation in \\(\\lambda\\), which is the whole strategy. Do not reach for magnitudes or the cross product — only the dot product is needed." }, { stepNumber: 2, description: "List both vectors in components", workingLatex: "\\mathbf{a} = (\\lambda,\\ 2,\\ 3),\\quad \\mathbf{b} = (1,\\ -\\lambda,\\ 4)", explanation: "Writing the \\(\\mathbf{i},\\mathbf{j},\\mathbf{k}\\) components in order ensures the dot product pairs them correctly. The \\(\\mathbf{j}\\)-component of \\(\\mathbf{b}\\) is \\(-\\lambda\\), a signed term that is the most common thing to mishandle. Notice \\(\\lambda\\) appears in both vectors, which is why the dot product will turn out to be linear in \\(\\lambda\\)." }, { stepNumber: 3, description: "Write the dot-product formula", workingLatex: "\\mathbf{a}\\cdot\\mathbf{b} = a_1 b_1 + a_2 b_2 + a_3 b_3", explanation: "The dot product multiplies matching components and sums them — \\(x\\) with \\(x\\), \\(y\\) with \\(y\\), \\(z\\) with \\(z\\). Stating the general pattern first prevents accidentally pairing the \\(\\mathbf{j}\\) term of one vector with the \\(\\mathbf{k}\\) term of the other. This is purely a scalar result, not a vector." }, { stepNumber: 4, description: "Substitute the components", workingLatex: "\\mathbf{a}\\cdot\\mathbf{b} = (\\lambda)(1) + (2)(-\\lambda) + (3)(4)", explanation: "Inserting each pair, the brackets around \\(-\\lambda\\) keep the middle product negative. The third pair \\((3)(4)\\) is the only purely numerical term and will become the constant. Carrying the signs through carefully here is what determines the final value of \\(\\lambda\\)." }, { stepNumber: 5, description: "Evaluate each product", workingLatex: "(\\lambda)(1) = \\lambda,\\quad (2)(-\\lambda) = -2\\lambda,\\quad (3)(4) = 12", explanation: "The three products are \\(\\lambda\\), \\(-2\\lambda\\) and \\(12\\). Computing them one at a time, with the bracket keeping \\((2)(-\\lambda)=-2\\lambda\\) negative, isolates exactly where a sign slip could occur. The \\(\\mathbf{j}\\)-term is the dangerous one; the \\(\\mathbf{k}\\)-term is a pure constant." }, { stepNumber: 6, description: "Form the linear expression", workingLatex: "\\mathbf{a}\\cdot\\mathbf{b} = \\lambda - 2\\lambda + 12", explanation: "Summing the three products gives the dot product as a sum of two \\(\\lambda\\)-terms and a constant. Writing them out unsimplified first separates the variable parts from the number, which reduces slip-ups when collecting. Nothing has been combined yet." }, { stepNumber: 7, description: "Collect like terms", workingLatex: "\\mathbf{a}\\cdot\\mathbf{b} = -\\lambda + 12", explanation: "Combining \\(\\lambda-2\\lambda=-\\lambda\\) leaves a linear expression in \\(\\lambda\\). Because there is no \\(\\lambda^2\\) term, the perpendicularity equation will have a single solution, not the two a quadratic would give. This linearity is a consequence of \\(\\lambda\\) appearing once in each vector." }, { stepNumber: 8, description: "Apply the zero condition", workingLatex: "-\\lambda + 12 = 0", explanation: "Setting the dot product to zero enforces the perpendicularity required in step 1, converting geometry into a one-line equation. This is the pivotal moment where the condition is imposed. Any \\(\\lambda\\) satisfying it makes the angle between the vectors exactly \\(90^\\circ\\)." }, { stepNumber: 9, description: "Solve for lambda", workingLatex: "\\lambda = 12", explanation: "Adding \\(\\lambda\\) to both sides gives \\(\\lambda=12\\), the unique value making the vectors perpendicular. Since the equation was linear, no second solution exists. This single answer is consistent with the geometry: only one scaling of these particular vectors makes them meet at a right angle." }, { stepNumber: 10, description: "Write the perpendicular pair", workingLatex: "\\mathbf{a} = 12\\mathbf{i} + 2\\mathbf{j} + 3\\mathbf{k},\\quad \\mathbf{b} = \\mathbf{i} - 12\\mathbf{j} + 4\\mathbf{k}", explanation: "Substituting \\(\\lambda=12\\) into both vectors produces one explicit orthogonal pair, answering the \"hence\" part. As a verification, their dot product is \\(12-24+12=0\\), confirming the right angle. Always perform this back-check — it catches sign errors in the \\(\\mathbf{j}\\)-term immediately." } ], finalAnswer: "\\(\\lambda = 12\\)." } },
  { id: "y2v2-047", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 47", difficulty: "Challenge", questionText: "A ski lift cable runs from \\(A(0, 0, 0)\\) to \\(B(200, 300, 100)\\) m. (a) Find the length of the cable. (b) Find the angle the cable makes with the horizontal plane.", marks: 6, examStyle: true, yearCreated: 2026, tags: ["applied", "geometry"], workedSolution: { steps: [ { stepNumber: 1, description: "Form the displacement vector AB", workingLatex: "\\mathbf{AB} = B - A = (200,\\ 300,\\ 100)", explanation: "Subtracting the lower station \\(A\\) from the upper station \\(B\\) gives the cable's displacement vector, whose length is the cable length and whose direction sets the angle. Because \\(A\\) is the origin, the displacement equals \\(B\\)'s coordinates directly. The \\(z=100\\) entry is the vertical rise, which will matter for the angle part." }, { stepNumber: 2, description: "Write the 3D length formula", workingLatex: "L = |\\mathbf{AB}| = \\sqrt{x^2 + y^2 + z^2}", explanation: "The cable length is the magnitude of the displacement, given by Pythagoras extended to three dimensions. Each component must be squared before they are summed under one root. This single straight-line distance is what part (a) asks for." }, { stepNumber: 3, description: "Square each component", workingLatex: "200^2 = 40000,\\ \\ 300^2 = 90000,\\ \\ 100^2 = 10000", explanation: "Squaring each component separately keeps the large numbers manageable and avoids slips. Squaring also removes signs, though here all components are positive anyway. Keeping the trailing zeros aligned now prevents a factor-of-ten error when they are added." }, { stepNumber: 4, description: "Sum the squares", workingLatex: "40000 + 90000 + 10000 = 140000", explanation: "Adding the squared components gives the radicand \\(140000\\,\\text{m}^2\\). Careful place-value alignment matters with numbers this size, as a stray zero changes the answer tenfold. This total is the squared cable length." }, { stepNumber: 5, description: "Take the root for the cable length", workingLatex: "L = \\sqrt{140000} = 100\\sqrt{14} \\approx 374.17\\text{ m}", explanation: "Factoring out \\(\\sqrt{10000}=100\\) gives the exact form \\(100\\sqrt{14}\\), which evaluates to \\(\\approx374.17\\) m and answers part (a). The cable must be longer than the horizontal run alone and longer than the \\(300\\) m largest component, and \\(374.17\\) satisfies both checks. Carry the unrounded value forward for the angle calculation." }, { stepNumber: 6, description: "Separate vertical from horizontal parts", workingLatex: "z = 100,\\quad \\text{horizontal} = \\sqrt{200^2 + 300^2}", explanation: "The angle to the horizontal plane is set by a right triangle whose vertical side is the rise \\(z=100\\) and whose base is the cable's shadow on the \\(xy\\)-plane. Only the \\(z\\)-component is vertical; both \\(x\\) and \\(y\\) lie in the horizontal plane and combine into the run. Confusing the cable length with the horizontal run is the key error to avoid here." }, { stepNumber: 7, description: "Compute the horizontal run", workingLatex: "\\sqrt{40000 + 90000} = \\sqrt{130000} \\approx 360.56", explanation: "Combining only the \\(x\\) and \\(y\\) squares gives the horizontal distance \\(\\sqrt{130000}\\approx360.56\\) m, the base of the angle triangle. This is shorter than the full cable \\(374.17\\) m, as it must be, since the cable also climbs. Using this true run — not the slant length — is essential for the correct angle." }, { stepNumber: 8, description: "Write the tangent of the elevation", workingLatex: "\\tan\\phi = \\frac{\\text{vertical}}{\\text{horizontal}} = \\frac{100}{\\sqrt{130000}}", explanation: "The elevation angle \\(\\phi\\) satisfies opposite over adjacent, namely rise over run. Tangent is the right ratio because we have the two legs of the right triangle, not the hypotenuse-and-leg that would call for sine or cosine. Pairing the \\(100\\) m rise with the horizontal run \\(\\sqrt{130000}\\) is what makes this the angle above the horizontal plane." }, { stepNumber: 9, description: "Evaluate the tangent ratio", workingLatex: "\\tan\\phi = \\frac{100}{360.56} \\approx 0.2774", explanation: "Dividing rise by run gives \\(\\tan\\phi\\approx0.2774\\). Retaining four decimal places here ensures the inverse tangent rounds correctly at the end. A value well below \\(1\\) already signals a shallow angle under \\(45^\\circ\\)." }, { stepNumber: 10, description: "Take the inverse tangent", workingLatex: "\\phi = \\tan^{-1}(0.2774) \\approx 15.5^{\\circ}", explanation: "Applying \\(\\tan^{-1}\\) recovers the angle as \\(\\approx15.5^\\circ\\), with the calculator necessarily in degree mode. This gentle slope is reasonable for a ski lift that rises \\(100\\) m over a \\(360\\) m horizontal span. A common slip is leaving the calculator in radians, which would give an absurd value near \\(0.27\\)." } ], finalAnswer: "\\(\\approx 374.17\\) m; angle \\(\\approx 15.5^{\\circ}\\)." } },
  { id: "y2v2-048", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 48", difficulty: "Challenge", questionText: "A particle of mass 2 kg has position \\(\\mathbf{r}(t) = (t^{2}, 2t, \\ln(1 + t))\\) m for \\(t \\geq 0\\). Find the kinetic energy at \\(t = 1\\). (KE \\(= \\tfrac{1}{2}m|\\mathbf{v}|^{2}\\).)", marks: 7, examStyle: true, yearCreated: 2026, tags: ["applied", "kinematics"], workedSolution: { steps: [ { stepNumber: 1, description: "Define velocity as the position derivative", workingLatex: "\\mathbf{v}(t) = \\frac{d\\mathbf{r}}{dt}", explanation: "Velocity is the time-derivative of the position vector, differentiated component by component since the axes are independent. Kinetic energy depends on speed, so this derivative is the essential first link before any energy can be computed. We never need the position values themselves, only how fast each coordinate changes." }, { stepNumber: 2, description: "Differentiate the x-component", workingLatex: "\\frac{d}{dt}(t^2) = 2t", explanation: "The power rule sends \\(t^2\\) to \\(2t\\), the velocity in the \\(x\\)-direction. This component grows linearly with time, so the particle accelerates along \\(x\\). Treating each component as an ordinary single-variable derivative is exactly what vector differentiation allows." }, { stepNumber: 3, description: "Differentiate the y-component", workingLatex: "\\frac{d}{dt}(2t) = 2", explanation: "The derivative of the linear term \\(2t\\) is its constant coefficient \\(2\\), so the \\(y\\)-velocity is steady for all time. A constant component means no acceleration along \\(y\\). This is the simplest of the three derivatives and easy to get right." }, { stepNumber: 4, description: "Differentiate the z-component", workingLatex: "\\frac{d}{dt}\\big(\\ln(1+t)\\big) = \\frac{1}{1+t}", explanation: "Applying the chain rule to \\(\\ln(1+t)\\) gives \\(\\frac{1}{1+t}\\) times the inside derivative \\(1\\). Forgetting the \\(+t\\) and writing \\(\\frac1t\\), or dropping the chain-rule factor, are the usual mistakes here. This component decays as \\(t\\) grows, so the vertical motion slows over time." }, { stepNumber: 5, description: "Assemble the velocity vector", workingLatex: "\\mathbf{v}(t) = \\left(2t,\\ 2,\\ \\frac{1}{1+t}\\right)", explanation: "Collecting the three derivatives gives the full velocity field, valid for all \\(t\\ge0\\). Each component behaves differently — increasing, constant, and decreasing — which is what makes the motion three-dimensional and non-trivial. This vector is now ready to be evaluated at the required instant." }, { stepNumber: 6, description: "Evaluate velocity at t = 1", workingLatex: "\\mathbf{v}(1) = \\left(2,\\ 2,\\ \\tfrac{1}{2}\\right)", explanation: "Substituting \\(t=1\\) gives \\(2(1)=2\\), the constant \\(2\\), and \\(\\frac{1}{1+1}=\\tfrac12\\). These are the instantaneous velocity components at the moment the energy is wanted. The small \\(z\\)-component shows the particle is moving mainly in the \\(xy\\)-plane at this instant." }, { stepNumber: 7, description: "Write the speed-squared formula", workingLatex: "|\\mathbf{v}|^2 = v_x^2 + v_y^2 + v_z^2", explanation: "Kinetic energy uses \\(|\\mathbf{v}|^2\\) directly, so we square and sum the components without ever taking a square root. Skipping the root avoids introducing rounding error and extra work — a neat efficiency the KE formula permits. This is the squared magnitude of the velocity vector." }, { stepNumber: 8, description: "Square each velocity component", workingLatex: "2^2 = 4,\\quad 2^2 = 4,\\quad \\left(\\tfrac{1}{2}\\right)^2 = 0.25", explanation: "Squaring each component gives \\(4\\), \\(4\\) and \\(0.25\\); the fraction \\(\\tfrac12\\) squares to \\(0.25\\), conveniently written as a decimal for the sum. Squaring keeps every term positive, so directions no longer matter for energy. The small \\(z\\)-contribution confirms the vertical motion barely affects the speed here." }, { stepNumber: 9, description: "Sum to get speed squared", workingLatex: "|\\mathbf{v}|^2 = 4 + 4 + 0.25 = 8.25", explanation: "Adding the three squares gives \\(|\\mathbf{v}|^2 = 8.25\\,\\text{m}^2\\,\\text{s}^{-2}\\), the quantity the energy formula needs. This is the squared speed at \\(t=1\\), not the speed itself. Keeping it as \\(8.25\\) rather than rooting it saves a step, since KE wants the square anyway." }, { stepNumber: 10, description: "Apply the kinetic-energy formula", workingLatex: "\\text{KE} = \\tfrac{1}{2}m|\\mathbf{v}|^2 = \\tfrac{1}{2}(2)(8.25)", explanation: "Substituting mass \\(m=2\\) kg and \\(|\\mathbf{v}|^2=8.25\\) into \\(\\text{KE}=\\tfrac12 m|\\mathbf v|^2\\), the factor \\(\\tfrac12\\) and the mass \\(2\\) multiply to \\(1\\). Using \\(|\\mathbf v|^2\\) here, not \\(|\\mathbf v|\\), is the whole point of having avoided the square root earlier. Mixing up mass and speed in the formula is the slip to watch for." }, { stepNumber: 11, description: "Evaluate the kinetic energy", workingLatex: "\\text{KE} = 8.25\\text{ J}", explanation: "Since \\(\\tfrac12\\times2=1\\), the kinetic energy equals \\(8.25\\) joules at \\(t=1\\). The numerical coincidence with \\(|\\mathbf v|^2\\) arises only because the mass happens to be \\(2\\) kg, cancelling the half. The positive result in joules is the expected unit and sign for kinetic energy." } ], finalAnswer: "8.25 J." } },
  { id: "y2v2-049", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 49", difficulty: "Challenge", questionText: "Points \\(A,\\ B,\\ C\\) have position vectors \\(\\mathbf{a} = 2\\mathbf{i} + \\mathbf{j} + 3\\mathbf{k}\\), \\(\\mathbf{b} = 4\\mathbf{i} - \\mathbf{j} + 2\\mathbf{k}\\), \\(\\mathbf{c} = \\mathbf{i} + 5\\mathbf{j} - \\mathbf{k}\\). (a) Find \\(\\mathbf{AB},\\ \\mathbf{AC}\\). (b) Find the angle \\(\\angle BAC\\) to the nearest degree.", marks: 6, examStyle: true, yearCreated: 2026, tags: ["angle"], workedSolution: { steps: [ { stepNumber: 1, description: "Set up AB as displacement from A", workingLatex: "\\mathbf{AB} = \\mathbf{b} - \\mathbf{a}", explanation: "The angle \\(\\angle BAC\\) is measured at the vertex \\(A\\), so both arms of the angle must emanate from \\(A\\). Geometrically, \\(\\mathbf{AB}\\) is the arrow that carries you from \\(A\\) to \\(B\\), and \\\"head minus tail\\\" gives \\(\\mathbf{b}-\\mathbf{a}\\). The single most common slip in this whole problem is computing \\(\\mathbf{a}-\\mathbf{b}\\) instead; that reverses the arrow and, while it happens to give the same angle here, it corrupts the geometric picture and bites you in problems where direction matters." }, { stepNumber: 2, description: "Compute AB components", workingLatex: "\\mathbf{AB} = (4-2,\\ -1-1,\\ 2-3) = (2,\\ -2,\\ -1)", explanation: "Subtract \\(\\mathbf{a}=(2,1,3)\\) from \\(\\mathbf{b}=(4,-1,2)\\) coordinate by coordinate. The two negative results, \\(-1-1=-2\\) and \\(2-3=-1\\), are where arithmetic errors creep in, so write each subtraction explicitly. A quick sanity check: \\(\\mathbf{AB}\\) should point generally toward \\(B\\), which sits lower and to the side of \\(A\\), consistent with the negative \\(y\\)- and \\(z\\)-components." }, { stepNumber: 3, description: "Set up AC as displacement from A", workingLatex: "\\mathbf{AC} = \\mathbf{c} - \\mathbf{a}", explanation: "The second arm of the angle runs from the same vertex \\(A\\) to \\(C\\), so again use head minus tail with \\(A\\) as the tail. Sharing the start point \\(A\\) is exactly what makes the two vectors meet at the angle we want; if you accidentally used \\(B\\) or \\(C\\) as the common point you would be computing a different angle of the triangle entirely." }, { stepNumber: 4, description: "Compute AC components", workingLatex: "\\mathbf{AC} = (1-2,\\ 5-1,\\ -1-3) = (-1,\\ 4,\\ -4)", explanation: "Subtract \\(\\mathbf{a}=(2,1,3)\\) from \\(\\mathbf{c}=(1,5,-1)\\). Note the large swing in the \\(y\\)-component (\\(+4\\)) and a strongly negative \\(z\\) (\\(-4\\)): \\(\\mathbf{AC}\\) points in a noticeably different direction from \\(\\mathbf{AB}\\), which already hints the angle between them is wide rather than narrow." }, { stepNumber: 5, description: "Recall the cosine-via-dot-product formula", workingLatex: "\\cos\\theta = \\frac{\\mathbf{AB}\\cdot\\mathbf{AC}}{|\\mathbf{AB}||\\mathbf{AC}|}", explanation: "This is the workhorse identity \\(\\mathbf{u}\\cdot\\mathbf{v}=|\\mathbf{u}||\\mathbf{v}|\\cos\\theta\\) rearranged to isolate the angle. The dot product alone measures alignment but is scaled by the lengths, so dividing by the magnitudes strips out that scaling and leaves a pure cosine between \\(-1\\) and \\(1\\). Recognise this method whenever you are asked for an angle between two vectors or at a vertex defined by position vectors." }, { stepNumber: 6, description: "Substitute into the dot product", workingLatex: "\\mathbf{AB}\\cdot\\mathbf{AC} = (2)(-1) + (-2)(4) + (-1)(-4)", explanation: "The dot product pairs matching components and adds them. Keeping every factor in brackets is essential here because two of the three products involve negatives, and the last one, \\((-1)(-4)\\), is a negative-times-negative that turns positive — a sign students routinely drop." }, { stepNumber: 7, description: "Evaluate the dot product", workingLatex: "\\mathbf{AB}\\cdot\\mathbf{AC} = -2 - 8 + 4 = -6", explanation: "Summing gives \\(-6\\). The sign of the dot product is the headline: a negative value means the two arms point more away from each other than toward, so the angle must be obtuse (greater than \\(90^\\circ\\)). This lets you predict the answer's ballpark before any trig, and flag an error instantly if your final angle comes out acute." }, { stepNumber: 8, description: "Find the magnitude of AB", workingLatex: "|\\mathbf{AB}| = \\sqrt{2^2 + (-2)^2 + (-1)^2} = \\sqrt{9} = 3", explanation: "The magnitude is the 3D Pythagoras of the components; squaring discards the signs so \\(4+4+1=9\\). The clean value \\(3\\) is a small gift — when one magnitude is a whole number, only the other surd needs care, reducing the chance of a slip in the denominator." }, { stepNumber: 9, description: "Find the magnitude of AC", workingLatex: "|\\mathbf{AC}| = \\sqrt{(-1)^2 + 4^2 + (-4)^2} = \\sqrt{33}", explanation: "Here \\(1+16+16=33\\), which is not a perfect square, so resist the urge to round now. Carrying \\(\\sqrt{33}\\) exactly into the next line preserves accuracy; rounding magnitudes early is a classic way to lose a degree in the final answer." }, { stepNumber: 10, description: "Assemble the cosine ratio", workingLatex: "\\cos\\theta = \\frac{-6}{3\\sqrt{33}}", explanation: "Drop the dot product over the product of magnitudes. The denominator \\(3\\sqrt{33}\\approx17.23\\) is positive, so the whole fraction inherits the sign of the numerator, \\(-6\\). This is the exact form of the cosine, and keeping it symbolic until the last moment is the safest route." }, { stepNumber: 11, description: "Evaluate the cosine as a decimal", workingLatex: "\\cos\\theta \\approx \\frac{-6}{17.23} \\approx -0.3482", explanation: "Dividing gives roughly \\(-0.348\\). A magnitude well below \\(1\\) is reassuring — a cosine outside \\([-1,1]\\) would signal an arithmetic blunder upstream. The negative sign confirms the obtuse-angle prediction made from the dot product." }, { stepNumber: 12, description: "Take the inverse cosine", workingLatex: "\\theta = \\cos^{-1}(-0.3482) \\approx 110.4^{\\circ}", explanation: "Apply \\(\\cos^{-1}\\) in degree mode; this returns the principal value in \\([0^\\circ,180^\\circ]\\), which is exactly the range a geometric angle lives in, so no quadrant ambiguity arises. Ensure the calculator is not in radians, the single most frequent cause of a nonsensical answer here." }, { stepNumber: 13, description: "Round to the nearest degree", workingLatex: "\\theta \\approx 110^{\\circ}", explanation: "Rounding \\(110.4^\\circ\\) gives \\(110^\\circ\\). As a final sanity check, this is comfortably obtuse, matching the negative dot product, and is a plausible interior angle for a triangle, so the result hangs together." } ], finalAnswer: "\\(\\approx 110^{\\circ}\\)." } },
  { id: "y2v2-050", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 50", difficulty: "Challenge", questionText: "Find the values of \\(\\mu\\) such that \\((1, \\mu, -2)\\) and \\((-2, 3, \\mu)\\) are perpendicular.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["perpendicular"], workedSolution: { steps: [ { stepNumber: 1, description: "State the perpendicularity condition", workingLatex: "\\mathbf{u}\\cdot\\mathbf{v} = 0", explanation: "Two non-zero vectors are perpendicular exactly when their dot product vanishes, because \\(\\mathbf{u}\\cdot\\mathbf{v}=|\\mathbf{u}||\\mathbf{v}|\\cos\\theta\\) and \\(\\cos 90^\\circ=0\\). This is the key conceptual move: it converts a geometric condition (a right angle in 3D) into a single algebraic equation in \\(\\mu\\). Recognise this template whenever a question asks for a parameter that makes vectors perpendicular, orthogonal, or \\\"at right angles\\\"." }, { stepNumber: 2, description: "Label the two vectors", workingLatex: "\\mathbf{u} = (1,\\ \\mu,\\ -2),\\quad \\mathbf{v} = (-2,\\ 3,\\ \\mu)", explanation: "Writing the components in order keeps the pairing straight when you take the dot product. Notice the unknown \\(\\mu\\) sits in the second slot of \\(\\mathbf{u}\\) but the third slot of \\(\\mathbf{v}\\); this staggering is deliberate and means \\(\\mu\\) will appear in two different products, so do not expect it to cancel." }, { stepNumber: 3, description: "Write the dot product formula", workingLatex: "\\mathbf{u}\\cdot\\mathbf{v} = u_1v_1 + u_2v_2 + u_3v_3", explanation: "The dot product multiplies corresponding components and sums them. Stating the index pattern first is a guard against the common mistake of pairing \\(u_2\\) with \\(v_3\\) or otherwise misaligning the terms that carry \\(\\mu\\), which would give a wrong equation." }, { stepNumber: 4, description: "Substitute the components", workingLatex: "\\mathbf{u}\\cdot\\mathbf{v} = (1)(-2) + (\\mu)(3) + (-2)(\\mu)", explanation: "Insert each matched pair: \\(u_1v_1=(1)(-2)\\), \\(u_2v_2=(\\mu)(3)\\), \\(u_3v_3=(-2)(\\mu)\\). The brackets on \\((-2)(\\mu)\\) matter: it must stay \\(-2\\mu\\), not \\(+2\\mu\\). Two of the three terms contain \\(\\mu\\), which is what makes the equation worth setting up carefully." }, { stepNumber: 5, description: "Evaluate the constant product", workingLatex: "(1)(-2) = -2", explanation: "The first pairing involves no \\(\\mu\\) and contributes a fixed constant of \\(-2\\) to the dot product. Isolating it first separates the parts of the expression that depend on \\(\\mu\\) from the part that does not, which clarifies the structure of the equation to come." }, { stepNumber: 6, description: "Evaluate the two mu products", workingLatex: "(\\mu)(3) = 3\\mu,\\quad (-2)(\\mu) = -2\\mu", explanation: "The remaining two pairings each carry \\(\\mu\\), with a positive coefficient \\(+3\\) from \\(\\mathbf{v}\\)'s second slot and a negative coefficient \\(-2\\) from \\(\\mathbf{u}\\)'s third slot. Because their signs differ, they will partly cancel rather than reinforce — anticipate this so a sign error stands out." }, { stepNumber: 7, description: "Assemble the full expression", workingLatex: "\\mathbf{u}\\cdot\\mathbf{v} = -2 + 3\\mu - 2\\mu", explanation: "Gather the constant and the two \\(\\mu\\)-terms into one expression. Laying them out unsimplified before collecting reduces the risk of accidentally merging the constant \\(-2\\) into the \\(\\mu\\)-terms, a slip that would give a wrong coefficient." }, { stepNumber: 8, description: "Collect like terms", workingLatex: "\\mathbf{u}\\cdot\\mathbf{v} = \\mu - 2", explanation: "Combining the variable terms, \\(3\\mu-2\\mu=\\mu\\), leaves the linear expression \\(\\mu-2\\). Because it is linear (no \\(\\mu^2\\)), there will be exactly one value of \\(\\mu\\); a quadratic would have warned of possibly two solutions, a contrast worth noting for similar problems." }, { stepNumber: 9, description: "Set the expression to zero", workingLatex: "\\mu - 2 = 0", explanation: "Now impose the perpendicularity condition from step 1 by equating the dot product to zero. This is the moment the geometric requirement of a right angle becomes a single solvable algebraic equation in \\(\\mu\\)." }, { stepNumber: 10, description: "Solve for mu", workingLatex: "\\mu = 2", explanation: "Adding \\(2\\) to both sides gives \\(\\mu=2\\). The unique solution reflects that there is exactly one value making the angle a right angle for these particular vectors." }, { stepNumber: 11, description: "Verify by back-substitution", workingLatex: "(1)(-2) + (2)(3) + (-2)(2) = -2 + 6 - 4 = 0", explanation: "Substituting \\(\\mu=2\\) back into the dot product gives exactly zero, confirming the vectors \\((1,2,-2)\\) and \\((-2,3,2)\\) are genuinely perpendicular. This quick check costs little and catches any sign error made in the earlier algebra, so it is always worth doing." } ], finalAnswer: "\\(\\mu = 2\\)." } },
  { id: "y2v2-051", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 51", difficulty: "Challenge", questionText: "A crane lifts a load along the cable from \\(A(0, 0, 0)\\) to \\(B(3, 4, 12)\\) m. A horizontal wind force of \\(\\mathbf{F} = (10, 0, 0)\\) N acts on the load. Find the component of wind force along and perpendicular to the cable.", marks: 7, examStyle: true, yearCreated: 2026, tags: ["applied", "scalar product"], workedSolution: { steps: [ { stepNumber: 1, description: "Form the cable direction vector AB", workingLatex: "\\mathbf{AB} = B - A = (3,\\ 4,\\ 12)", explanation: "The cable defines the direction along which we want to resolve the wind force. Since \\(A\\) is the origin, \\(B-A\\) is simply \\(B\\)'s coordinates. Conceptually we are about to split the horizontal wind into one piece that pulls along the slanted cable and one that pushes across it — a standard resolution of a force into parallel and perpendicular parts relative to a chosen line." }, { stepNumber: 2, description: "Compute the magnitude of AB", workingLatex: "|\\mathbf{AB}| = \\sqrt{3^2 + 4^2 + 12^2} = \\sqrt{9 + 16 + 144} = \\sqrt{169} = 13", explanation: "The length of the cable's direction vector is needed to normalise it. Here \\(9+16+144=169\\) is a perfect square giving exactly \\(13\\) (a \\(3\\text{-}4\\text{-}12\\text{-}13\\) Pythagorean quadruple), so no rounding error enters at this stage." }, { stepNumber: 3, description: "Form the unit vector along the cable", workingLatex: "\\hat{\\mathbf{AB}} = \\frac{1}{13}(3,\\ 4,\\ 12)", explanation: "Dividing by the magnitude produces a unit vector — a pure direction of length \\(1\\) — which is essential because the scalar projection formula only gives the correct component if the direction vector is normalised. Skipping the normalisation is the single biggest error in projection problems: it inflates the answer by a factor of the cable length." }, { stepNumber: 4, description: "Write the parallel-component formula", workingLatex: "F_{\\parallel} = \\mathbf{F}\\cdot\\hat{\\mathbf{AB}}", explanation: "The component of \\(\\mathbf{F}\\) along the cable is its scalar projection, the dot product with the unit direction. Geometrically this is \\(|\\mathbf{F}|\\cos\\theta\\), the shadow of the force on the cable line, and its sign tells you whether the wind helps or hinders motion up the cable." }, { stepNumber: 5, description: "Substitute force and unit vector", workingLatex: "F_{\\parallel} = (10,\\ 0,\\ 0)\\cdot\\tfrac{1}{13}(3,\\ 4,\\ 12) = \\frac{(10)(3) + 0 + 0}{13}", explanation: "Because the wind is purely horizontal, \\(\\mathbf{F}=(10,0,0)\\), only its \\(x\\)-component meets the cable's \\(x\\)-direction; the \\(y\\)- and \\(z\\)-products are zero. The factor \\(\\tfrac{1}{13}\\) pulls out cleanly, leaving \\(30/13\\). This is a nice illustration that a force perpendicular-ish to a line still has a non-zero along-line component unless it is exactly perpendicular." }, { stepNumber: 6, description: "Evaluate the parallel component", workingLatex: "F_{\\parallel} = \\frac{30}{13} \\approx 2.31\\text{ N}", explanation: "Dividing, \\(30/13=2.307\\ldots\\) N. This is small relative to the \\(10\\) N total because the cable is steeply inclined (mostly vertical) while the wind is horizontal, so only a little of the wind lines up with the cable. Keep the unrounded value for the next step." }, { stepNumber: 7, description: "Relate components by Pythagoras", workingLatex: "|\\mathbf{F}|^2 = F_{\\parallel}^2 + F_{\\perp}^2", explanation: "The parallel and perpendicular pieces are by construction at right angles, so they form the legs of a right triangle whose hypotenuse is the full force. This lets us find the perpendicular magnitude without resolving it as a vector — a clean shortcut, though it gives only the magnitude, not the direction, of the perpendicular part." }, { stepNumber: 8, description: "Compute the total force magnitude", workingLatex: "|\\mathbf{F}| = \\sqrt{10^2 + 0^2 + 0^2} = 10,\\quad |\\mathbf{F}|^2 = 100", explanation: "The wind force has magnitude \\(10\\) N, so \\(|\\mathbf{F}|^2=100\\) is the total \\\"energy budget\\\" being split between along- and across-cable directions. Using the squared magnitude avoids a premature square root." }, { stepNumber: 9, description: "Rearrange for the perpendicular component", workingLatex: "F_{\\perp} = \\sqrt{|\\mathbf{F}|^2 - F_{\\parallel}^2} = \\sqrt{100 - (2.307)^2}", explanation: "Solving the Pythagoras relation for \\(F_\\perp\\) subtracts the parallel share from the total before rooting. Crucially, feed in the unrounded \\(F_\\parallel=30/13\\) here; using the rounded \\(2.31\\) can shift the last decimal of the answer." }, { stepNumber: 10, description: "Evaluate the perpendicular component", workingLatex: "F_{\\perp} = \\sqrt{100 - 5.33} = \\sqrt{94.67} \\approx 9.73\\text{ N}", explanation: "Computing \\(100-5.33=94.67\\) and rooting gives about \\(9.73\\) N across the cable. As a sanity check, \\(2.31^2+9.73^2\\approx5.3+94.7=100=10^2\\), so the two components correctly recombine to the full force — and the perpendicular part dominates, exactly as expected for a horizontal wind on a steep cable." } ], finalAnswer: "\\(\\parallel \\approx 2.31\\) N; \\(\\perp \\approx 9.73\\) N." } },
  { id: "y2v2-052", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 52", difficulty: "Challenge", questionText: "Given \\(|\\mathbf{a}| = 4,\\ |\\mathbf{b}| = 3\\), and \\(\\mathbf{a}\\cdot\\mathbf{b} = -6\\). Find \\(|\\mathbf{a} + \\mathbf{b}|\\) and the angle between \\(\\mathbf{a}\\) and \\(\\mathbf{b}\\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["magnitude", "angle"], workedSolution: { steps: [ { stepNumber: 1, description: "Write magnitude squared as a self dot product", workingLatex: "|\\mathbf{a} + \\mathbf{b}|^2 = (\\mathbf{a} + \\mathbf{b})\\cdot(\\mathbf{a} + \\mathbf{b})", explanation: "We are given only magnitudes and a dot product, never the components themselves, so the only route to \\(|\\mathbf{a}+\\mathbf{b}|\\) is the identity \\(|\\mathbf{v}|^2=\\mathbf{v}\\cdot\\mathbf{v}\\). Recognising that you can work entirely in dot-product algebra — without ever knowing \\(\\mathbf{a}\\) or \\(\\mathbf{b}\\) explicitly — is the central insight of this problem." }, { stepNumber: 2, description: "Distribute the dot product", workingLatex: "|\\mathbf{a} + \\mathbf{b}|^2 = \\mathbf{a}\\cdot\\mathbf{a} + \\mathbf{a}\\cdot\\mathbf{b} + \\mathbf{b}\\cdot\\mathbf{a} + \\mathbf{b}\\cdot\\mathbf{b}", explanation: "The dot product distributes over addition just like ordinary multiplication, so expand the bracket as a FOIL. Writing all four terms first makes the next simplification transparent and prevents accidentally dropping a cross term." }, { stepNumber: 3, description: "Merge the equal cross terms", workingLatex: "|\\mathbf{a} + \\mathbf{b}|^2 = \\mathbf{a}\\cdot\\mathbf{a} + 2\\,\\mathbf{a}\\cdot\\mathbf{b} + \\mathbf{b}\\cdot\\mathbf{b}", explanation: "The dot product is commutative, \\(\\mathbf{a}\\cdot\\mathbf{b}=\\mathbf{b}\\cdot\\mathbf{a}\\), so the two middle terms combine into \\(2\\,\\mathbf{a}\\cdot\\mathbf{b}\\). This mirrors the scalar identity \\((x+y)^2=x^2+2xy+y^2\\), a useful analogy to remember the expansion." }, { stepNumber: 4, description: "Replace self-dots with magnitudes squared", workingLatex: "|\\mathbf{a} + \\mathbf{b}|^2 = |\\mathbf{a}|^2 + 2(\\mathbf{a}\\cdot\\mathbf{b}) + |\\mathbf{b}|^2", explanation: "Using \\(\\mathbf{a}\\cdot\\mathbf{a}=|\\mathbf{a}|^2\\) turns the self-products into the given lengths. Now every term on the right is a known number, which is precisely why this dot-product expansion was the right tool." }, { stepNumber: 5, description: "Substitute the given values", workingLatex: "|\\mathbf{a} + \\mathbf{b}|^2 = 4^2 + 2(-6) + 3^2", explanation: "Insert \\(|\\mathbf{a}|=4\\), \\(|\\mathbf{b}|=3\\) and \\(\\mathbf{a}\\cdot\\mathbf{b}=-6\\). The negative dot product is the crucial input here; keeping its sign inside the bracket is what makes the cross term \\(2(-6)=-12\\) rather than \\(+12\\)." }, { stepNumber: 6, description: "Evaluate the three terms", workingLatex: "|\\mathbf{a} + \\mathbf{b}|^2 = 16 - 12 + 9 = 13", explanation: "Computing \\(16-12+9=13\\). The negative cross term shrinks the resultant: because \\(\\mathbf{a}\\) and \\(\\mathbf{b}\\) point more than \\(90^\\circ\\) apart, adding them partly cancels, so \\(|\\mathbf{a}+\\mathbf{b}|\\) ends up smaller than \\(|\\mathbf{a}|\\) alone — a useful geometric sanity check." }, { stepNumber: 7, description: "Take the square root", workingLatex: "|\\mathbf{a} + \\mathbf{b}| = \\sqrt{13}", explanation: "Root the squared magnitude. Since \\(13\\) is prime it has no square factor, so \\(\\sqrt{13}\\) is already in simplest exact form; leave it as a surd rather than rounding, as the question gives exact data." }, { stepNumber: 8, description: "Write the angle formula", workingLatex: "\\cos\\theta = \\frac{\\mathbf{a}\\cdot\\mathbf{b}}{|\\mathbf{a}||\\mathbf{b}|}", explanation: "Rearranging \\(\\mathbf{a}\\cdot\\mathbf{b}=|\\mathbf{a}||\\mathbf{b}|\\cos\\theta\\) isolates the cosine. This is the second, independent use of the data — note the same dot product \\(-6\\) drives both the magnitude and the angle, tying the two parts of the question together." }, { stepNumber: 9, description: "Substitute the values", workingLatex: "\\cos\\theta = \\frac{-6}{(4)(3)} = \\frac{-6}{12}", explanation: "The denominator is the product of magnitudes, \\(4\\times3=12\\). The numerator keeps its negative sign, so the cosine is negative — immediately telling us the angle is obtuse before we even compute it." }, { stepNumber: 10, description: "Simplify the cosine", workingLatex: "\\cos\\theta = -\\tfrac{1}{2}", explanation: "Reducing \\(-6/12\\) gives the clean exact value \\(-\\tfrac12\\). Spotting a familiar exact cosine here signals that the final angle will be a standard value, so no calculator rounding is required." }, { stepNumber: 11, description: "Take the inverse cosine", workingLatex: "\\theta = \\cos^{-1}\\left(-\\tfrac{1}{2}\\right) = 120^{\\circ}", explanation: "The angle in \\([0^\\circ,180^\\circ]\\) with cosine \\(-\\tfrac12\\) is exactly \\(120^\\circ\\), the supplement of the well-known \\(60^\\circ\\). Being obtuse, it matches the negative dot product, and being an exact value it confirms the answer needs no rounding." } ], finalAnswer: "\\(\\sqrt{13}\\) and \\(120^{\\circ}\\)." } },
  { id: "y2v2-053", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 53", difficulty: "Challenge", questionText: "A helicopter at \\((0, 0, 50)\\) m observes a moving object at \\((1 + t, 2 - t, 0)\\) m. Find the time at which the helicopter and object are closest, and the minimum distance.", marks: 7, examStyle: true, yearCreated: 2026, tags: ["applied", "kinematics"], workedSolution: { steps: [ { stepNumber: 1, description: "Form the time-dependent separation vector", workingLatex: "\\mathbf{d}(t) = \\text{object} - \\text{helicopter} = (1+t,\\ 2-t,\\ -50)", explanation: "The gap between the two objects is the vector joining them, found by subtracting position coordinates. The helicopter is fixed at height \\(50\\) m while the object moves in the horizontal plane \\(z=0\\), so the \\(z\\)-component is a constant \\(-50\\); only the \\(x\\)- and \\(y\\)-parts depend on \\(t\\). This separation vector is the object we will minimise the length of." }, { stepNumber: 2, description: "Write the distance squared", workingLatex: "d^2 = (1+t)^2 + (2-t)^2 + (-50)^2", explanation: "Distance is the magnitude of \\(\\mathbf{d}(t)\\), but we minimise \\(d^2\\) instead of \\(d\\) to avoid differentiating a square root. This is legitimate because \\(d\\ge0\\), so \\(d\\) and \\(d^2\\) are minimised at the same \\(t\\) — a standard and exam-safe simplification." }, { stepNumber: 3, description: "Insert the constant z-term", workingLatex: "d^2 = (1+t)^2 + (2-t)^2 + 2500", explanation: "The vertical term \\((-50)^2=2500\\) is independent of \\(t\\). It does not influence where the minimum occurs (its derivative is zero) but it dominates the actual distance, since the horizontal motion is tiny compared with the \\(50\\) m height. Keep it for the final numerical answer." }, { stepNumber: 4, description: "Differentiate distance squared", workingLatex: "\\frac{d(d^2)}{dt} = 2(1+t)(1) + 2(2-t)(-1)", explanation: "Apply the chain rule to each squared bracket: derivative of the outer square times derivative of the inside. The inside of \\((2-t)^2\\) differentiates to \\(-1\\), introducing the crucial minus sign that many students miss. The constant \\(2500\\) vanishes." }, { stepNumber: 5, description: "Expand the derivative", workingLatex: "\\frac{d(d^2)}{dt} = 2 + 2t - 4 + 2t", explanation: "Multiply out: \\(2(1+t)=2+2t\\) and \\(-2(2-t)=-4+2t\\). The double sign in the second term is the danger point; writing it out fully before collecting prevents \\(-2(2-t)\\) being mistaken for \\(-4-2t\\)." }, { stepNumber: 6, description: "Simplify the derivative", workingLatex: "\\frac{d(d^2)}{dt} = 4t - 2", explanation: "Collecting, the \\(t\\)-terms give \\(2t+2t=4t\\) and the constants \\(2-4=-2\\). The derivative is linear, confirming \\(d^2\\) is a quadratic in \\(t\\) — an upward parabola with a single turning point." }, { stepNumber: 7, description: "Set the derivative to zero", workingLatex: "4t - 2 = 0", explanation: "The closest approach is a stationary point of distance, where the rate of change of \\(d^2\\) is zero. Setting the derivative to zero locates that instant. Conceptually, this is the moment the object stops getting nearer and starts moving away." }, { stepNumber: 8, description: "Solve for the time", workingLatex: "t = \\tfrac{2}{4} = 0.5\\text{ s}", explanation: "Solving gives \\(t=0.5\\) s. Because the coefficient of \\(t^2\\) in \\(d^2\\) is positive (the parabola opens upward), this stationary point is a minimum, not a maximum — so it genuinely is the closest approach, as the physics demands." }, { stepNumber: 9, description: "Substitute t into distance squared", workingLatex: "d^2(0.5) = (1.5)^2 + (1.5)^2 + 2500", explanation: "At \\(t=0.5\\), the horizontal coordinates are \\(1+t=1.5\\) and \\(2-t=1.5\\); interestingly they coincide, meaning the object sits symmetrically at the moment of closest approach. Substitute these back into the distance-squared expression, restoring the \\(2500\\) we set aside." }, { stepNumber: 10, description: "Evaluate distance squared", workingLatex: "d^2(0.5) = 2.25 + 2.25 + 2500 = 2504.5", explanation: "Computing \\(1.5^2=2.25\\) twice and adding \\(2500\\) gives \\(2504.5\\). The horizontal contribution of \\(4.5\\) is minuscule beside the \\(2500\\) from the height, which already foreshadows a minimum distance just barely above \\(50\\) m." }, { stepNumber: 11, description: "Take the square root for the distance", workingLatex: "d = \\sqrt{2504.5} \\approx 50.04\\text{ m}", explanation: "Rooting gives about \\(50.04\\) m. The sanity check is compelling: the answer barely exceeds the helicopter's \\(50\\) m altitude, exactly because the object passes almost directly beneath it with only a tiny horizontal offset, so the slant distance is dominated by the vertical gap." } ], finalAnswer: "\\(t = 0.5\\) s; \\(\\approx 50.04\\) m." } },
  { id: "y2v2-054", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 54", difficulty: "Challenge", questionText: "Three points \\(A(1, 2, 3)\\), \\(B(4, -1, 5)\\), \\(C(-2, 3, 4)\\). Find the perimeter of the triangle \\(ABC\\).", marks: 6, examStyle: true, yearCreated: 2026, tags: ["applied", "distance"], workedSolution: { steps: [ { stepNumber: 1, description: "Express perimeter as a sum of side lengths", workingLatex: "P = |\\mathbf{AB}| + |\\mathbf{BC}| + |\\mathbf{CA}|", explanation: "The perimeter is the distance all the way round the triangle, so it is the sum of the three edge lengths. Each edge length is the magnitude of the displacement vector between two vertices, which reduces the whole problem to three applications of the 3D distance formula. Choosing a consistent loop \\(A\\to B\\to C\\to A\\) ensures you cover each side exactly once." }, { stepNumber: 2, description: "Compute displacement AB", workingLatex: "\\mathbf{AB} = B - A = (4-1,\\ -1-2,\\ 5-3) = (3,\\ -3,\\ 2)", explanation: "Subtract \\(A=(1,2,3)\\) from \\(B=(4,-1,5)\\) component by component. The middle entry \\(-1-2=-3\\) is the easy place to slip a sign. Since only the length matters for a perimeter, the direction of this vector is irrelevant — \\(\\mathbf{AB}\\) and \\(\\mathbf{BA}\\) give the same magnitude." }, { stepNumber: 3, description: "Find the length AB", workingLatex: "|\\mathbf{AB}| = \\sqrt{3^2 + (-3)^2 + 2^2} = \\sqrt{9 + 9 + 4} = \\sqrt{22}", explanation: "The 3D Pythagoras gives \\(9+9+4=22\\); squaring the components discards their signs, so the negative middle entry contributes the same as a positive \\(3\\). Leave the result as the exact surd \\(\\sqrt{22}\\) rather than rounding, to keep full precision until the final sum." }, { stepNumber: 4, description: "Compute displacement BC", workingLatex: "\\mathbf{BC} = C - B = (-2-4,\\ 3-(-1),\\ 4-5) = (-6,\\ 4,\\ -1)", explanation: "Subtract \\(B=(4,-1,5)\\) from \\(C=(-2,3,4)\\). The second component \\(3-(-1)=4\\) involves subtracting a negative, the single most error-prone step in this problem; written carefully it becomes \\(3+1=4\\)." }, { stepNumber: 5, description: "Find the length BC", workingLatex: "|\\mathbf{BC}| = \\sqrt{(-6)^2 + 4^2 + (-1)^2} = \\sqrt{36 + 16 + 1} = \\sqrt{53}", explanation: "Squaring gives \\(36+16+1=53\\), which is prime and so leaves \\(\\sqrt{53}\\) in simplest surd form. This is the longest side, consistent with \\(\\mathbf{BC}\\) having the largest single component, \\(-6\\)." }, { stepNumber: 6, description: "Compute displacement CA", workingLatex: "\\mathbf{CA} = A - C = (1-(-2),\\ 2-3,\\ 3-4) = (3,\\ -1,\\ -1)", explanation: "Subtract \\(C=(-2,3,4)\\) from \\(A=(1,2,3)\\) to close the loop back to the start. Again a double negative appears, \\(1-(-2)=3\\); handling it correctly completes the circuit of the triangle." }, { stepNumber: 7, description: "Find the length CA", workingLatex: "|\\mathbf{CA}| = \\sqrt{3^2 + (-1)^2 + (-1)^2} = \\sqrt{9 + 1 + 1} = \\sqrt{11}", explanation: "Squaring and summing gives \\(9+1+1=11\\), so \\(|\\mathbf{CA}|=\\sqrt{11}\\), the shortest side. Note that using \\(\\mathbf{CA}\\) rather than \\(\\mathbf{AC}\\) makes no difference to the length, since reversing a vector leaves its magnitude unchanged." }, { stepNumber: 8, description: "Write the exact perimeter", workingLatex: "P = \\sqrt{22} + \\sqrt{53} + \\sqrt{11}", explanation: "Add the three exact side lengths. These surds have no common factor under the root, so they cannot be combined into a single surd; the exact perimeter is genuinely this irreducible sum. Presenting the exact form first is good practice before any decimal approximation." }, { stepNumber: 9, description: "Evaluate each surd numerically", workingLatex: "\\sqrt{22} \\approx 4.690,\\ \\ \\sqrt{53} \\approx 7.280,\\ \\ \\sqrt{11} \\approx 3.317", explanation: "Convert each surd to a decimal carrying at least three places. Rounding each too early — say to one decimal — could shift the final total by enough to spoil a 2-decimal answer, so retain the extra digits through the addition." }, { stepNumber: 10, description: "Sum for the numerical perimeter", workingLatex: "P \\approx 4.690 + 7.280 + 3.317 \\approx 15.29", explanation: "Adding the decimals gives \\(P\\approx15.29\\) length units. A quick sanity check: each side lies between \\(3\\) and \\(8\\), so a perimeter around \\(15\\) is entirely reasonable, and the three sides satisfy the triangle inequality (no side exceeds the sum of the other two), confirming a valid triangle." } ], finalAnswer: "\\(\\sqrt{22} + \\sqrt{53} + \\sqrt{11} \\approx 15.29\\)." } },
  { id: "y2v2-055", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 55", difficulty: "Challenge", questionText: "A straight line passes through \\(A(1, 0, 2)\\) with direction \\((2, 1, -1)\\). Find the foot of the perpendicular from \\(P(4, 3, 5)\\) to this line, and the shortest distance from \\(P\\) to the line.", marks: 7, examStyle: true, yearCreated: 2026, tags: ["applied", "geometry"], workedSolution: { steps: [ { stepNumber: 1, description: "Write the parametric equation of the line", workingLatex: "\\mathbf{r} = \\begin{pmatrix} 1 \\\\ 0 \\\\ 2 \\end{pmatrix} + t\\begin{pmatrix} 2 \\\\ 1 \\\\ -1 \\end{pmatrix}", explanation: "Every point on the line is the fixed point \\(A\\) plus some scalar multiple \\(t\\) of the direction \\(\\mathbf{d}\\); the parameter \\(t\\) slides you along the line. The foot of the perpendicular is one specific such point, so the strategy is to leave \\(t\\) unknown, impose a right-angle condition, and solve for the single value of \\(t\\) that locates the foot." }, { stepNumber: 2, description: "Express the general point R", workingLatex: "R = (1 + 2t,\\; t,\\; 2 - t)", explanation: "Reading off each coordinate from the parametric form gives a moving point \\(R(t)\\). This is the candidate foot of the perpendicular; pinning down \\(t\\) will freeze it at the closest point on the line to \\(P\\). Keep the components in terms of \\(t\\) so they can be differentiated implicitly through the dot product." }, { stepNumber: 3, description: "Form the vector from P to R", workingLatex: "\\mathbf{PR} = R - P = (1 + 2t - 4,\\; t - 3,\\; 2 - t - 5)", explanation: "Subtract \\(P=(4,3,5)\\) from \\(R\\) componentwise to get the connector. This vector reaches from the external point \\(P\\) out to the line; at the special value of \\(t\\) it will be exactly perpendicular to the line, making it the shortest such connector. Order matters only for the sign, not the eventual length." }, { stepNumber: 4, description: "Simplify the components of PR", workingLatex: "\\mathbf{PR} = (2t - 3,\\; t - 3,\\; -t - 3)", explanation: "Collect constants in each slot. The third component needs care: \\(2 - t - 5 = -t - 3\\), where the two separate subtractions are easy to merge wrongly into \\(-t+3\\). Getting this sign right is essential, as it feeds directly into the perpendicularity equation." }, { stepNumber: 5, description: "State the perpendicularity condition", workingLatex: "\\mathbf{PR} \\cdot \\mathbf{d} = 0", explanation: "The shortest line from a point to a line meets it at a right angle, so at the foot \\(\\mathbf{PR}\\) is orthogonal to the direction \\(\\mathbf{d}\\) and their dot product vanishes. This is the key idea that converts \\\"closest point\\\" into a solvable algebraic equation — recognise it whenever you need a foot of perpendicular or a shortest distance to a line." }, { stepNumber: 6, description: "Substitute components into the dot product", workingLatex: "(2t - 3)(2) + (t - 3)(1) + (-t - 3)(-1) = 0", explanation: "Pair each component of \\(\\mathbf{PR}\\) with the matching component of \\(\\mathbf{d}=(2,1,-1)\\). Watch the final product: a negative component times \\(-1\\) flips to positive, \\((-t-3)(-1)=t+3\\). A dropped sign here is the commonest cause of a wrong \\(t\\)." }, { stepNumber: 7, description: "Expand each bracket", workingLatex: "(4t - 6) + (t - 3) + (t + 3) = 0", explanation: "Multiply out term by term, keeping the three groups separate for now. Expanding before combining is a deliberate safeguard: it isolates each sign so none gets lost when the like terms are gathered in the next step." }, { stepNumber: 8, description: "Collect like terms", workingLatex: "6t - 6 = 0", explanation: "The \\(t\\)-terms add to \\(4t+t+t=6t\\) and the constants to \\(-6-3+3=-6\\). Notice the \\(\\pm3\\) constants cancel neatly, leaving a clean linear equation — a reassuring sign the algebra has gone correctly." }, { stepNumber: 9, description: "Solve for the parameter t", workingLatex: "t = 1", explanation: "Rearranging \\(6t=6\\) gives \\(t=1\\). This single parameter value marks the foot of the perpendicular on the line; because the perpendicular from a point to a line is unique, we expect exactly one solution, which is what the linear equation delivered." }, { stepNumber: 10, description: "Substitute t back to find the foot", workingLatex: "R = (1 + 2(1),\\; 1,\\; 2 - 1) = (3, 1, 1)", explanation: "Putting \\(t=1\\) into the general point gives the foot \\((3,1,1)\\), the closest point on the line to \\(P\\). It is worth a mental check that these coordinates do satisfy the line's parametric form, confirming the point genuinely lies on the line." }, { stepNumber: 11, description: "Evaluate PR at t = 1", workingLatex: "\\mathbf{PR} = (2(1) - 3,\\; 1 - 3,\\; -1 - 3) = (-1, -2, -4)", explanation: "The shortest distance is the length of the perpendicular connector, so first evaluate its components at \\(t=1\\). As a verification, \\(\\mathbf{PR}\\cdot\\mathbf{d}=(-1)(2)+(-2)(1)+(-4)(-1)=-2-2+4=0\\), confirming \\(\\mathbf{PR}\\) really is perpendicular to the line." }, { stepNumber: 12, description: "Square each component of PR", workingLatex: "(-1)^2 + (-2)^2 + (-4)^2 = 1 + 4 + 16", explanation: "Squaring the components removes the signs, so all three contributions are positive and the order/direction of \\(\\mathbf{PR}\\) no longer matters. The sum \\(1+4+16\\) is the radicand for the magnitude." }, { stepNumber: 13, description: "Sum and take the square root", workingLatex: "|\\mathbf{PR}| = \\sqrt{1 + 4 + 16} = \\sqrt{21}", explanation: "Adding gives \\(21\\), and since \\(21=3\\times7\\) has no square factor, \\(\\sqrt{21}\\) is already simplest surd form. As a final sanity check this distance, about \\(4.58\\), is shorter than \\(|PA|\\) would be, exactly as the perpendicular (shortest) distance must be." } ], finalAnswer: "Foot \\((3, 1, 1)\\); distance \\(\\sqrt{21}\\)." } },
  { id: "y2v2-056", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 56", difficulty: "Challenge", questionText: "A particle of mass 3 kg is at rest at the origin. A constant force \\(\\mathbf{F} = 6\\mathbf{i} + 12\\mathbf{j} + 3\\mathbf{k}\\) N acts on it for 4 seconds. Find (a) the acceleration, (b) the velocity after 4 s, (c) the displacement after 4 s.", marks: 6, examStyle: true, yearCreated: 2026, tags: ["applied", "mechanics"], workedSolution: { steps: [ { stepNumber: 1, description: "State Newton's second law", workingLatex: "\\mathbf{F} = m\\mathbf{a}", explanation: "Newton's second law links force, mass and acceleration, and it holds componentwise for vectors: each direction obeys it independently. Here \\(\\mathbf{F}\\) and \\(m\\) are given, so the law is the gateway to the acceleration. Because the force is constant, the acceleration will be constant too, which justifies using SUVAT later." }, { stepNumber: 2, description: "Rearrange for acceleration", workingLatex: "\\mathbf{a} = \\frac{\\mathbf{F}}{m} = \\frac{1}{3}(6\\mathbf{i} + 12\\mathbf{j} + 3\\mathbf{k})", explanation: "Dividing the force vector by the scalar mass \\(3\\) kg means scaling every component by \\(\\tfrac13\\); a scalar divides a vector by acting on each entry equally. The direction of \\(\\mathbf{a}\\) is identical to that of \\(\\mathbf{F}\\), only its length changes — acceleration always points the same way as the net force." }, { stepNumber: 3, description: "Divide each component by 3", workingLatex: "\\mathbf{a} = (2, 4, 1)\\text{ m/s}^2", explanation: "Computing \\(6/3,\\ 12/3,\\ 3/3\\) gives the acceleration for part (a), with units \\(\\text{m/s}^2\\). Quoting the units is part of a complete mechanics answer; a bare vector loses marks even when the numbers are right." }, { stepNumber: 4, description: "State the velocity SUVAT equation", workingLatex: "\\mathbf{v} = \\mathbf{u} + \\mathbf{a}t", explanation: "Under constant acceleration, velocity increases linearly with time, captured by the vector SUVAT relation \\(\\mathbf{v}=\\mathbf{u}+\\mathbf{a}t\\). The phrase \\\"at rest at the origin\\\" fixes the initial velocity \\(\\mathbf{u}=\\mathbf{0}\\); overlooking this and carrying a phantom initial velocity is the classic error in this part." }, { stepNumber: 5, description: "Substitute zero initial velocity and t", workingLatex: "\\mathbf{v}(4) = \\mathbf{0} + (2, 4, 1)(4)", explanation: "With \\(\\mathbf{u}=\\mathbf{0}\\), only the \\(\\mathbf{a}t\\) term survives at \\(t=4\\) s. The acceleration vector is simply scaled by the elapsed time, since constant acceleration adds the same velocity increment each second." }, { stepNumber: 6, description: "Compute the velocity after 4 s", workingLatex: "\\mathbf{v}(4) = (8, 16, 4)\\text{ m/s}", explanation: "Multiplying each component of \\(\\mathbf{a}\\) by \\(4\\) gives the velocity for part (b), in \\(\\text{m/s}\\). Note it stays parallel to \\(\\mathbf{a}\\) and \\(\\mathbf{F}\\): a constant force on an initially stationary particle produces straight-line motion along the force direction." }, { stepNumber: 7, description: "State the displacement SUVAT equation", workingLatex: "\\mathbf{s} = \\mathbf{u}t + \\tfrac{1}{2}\\mathbf{a}t^2", explanation: "This is the vector form of the displacement SUVAT formula. Once more \\(\\mathbf{u}=\\mathbf{0}\\) kills the first term, leaving \\(\\mathbf{s}=\\tfrac12\\mathbf{a}t^2\\). The \\(t^2\\) dependence reflects that displacement accumulates faster than velocity under steady acceleration." }, { stepNumber: 8, description: "Substitute the known values", workingLatex: "\\mathbf{s}(4) = \\tfrac{1}{2}(2, 4, 1)(4)^2", explanation: "Insert \\(\\mathbf{a}=(2,4,1)\\) and \\(t=4\\). The crucial detail is to square the time, \\((4)^2=16\\), before multiplying — using \\(4\\) instead of \\(16\\) is the most frequent slip and quarters the answer." }, { stepNumber: 9, description: "Compute the scalar factor", workingLatex: "\\tfrac{1}{2}(16) = 8", explanation: "Combine the \\(\\tfrac12\\) and \\(t^2=16\\) into a single scalar multiplier of \\(8\\) before scaling the acceleration vector. Doing the scalar arithmetic first keeps the vector multiplication clean and reduces the chance of a per-component error." }, { stepNumber: 10, description: "Scale the acceleration vector", workingLatex: "\\mathbf{s}(4) = 8(2, 4, 1) = (16, 32, 8)\\text{ m}", explanation: "Multiplying each component by \\(8\\) gives the displacement for part (c), in metres. A neat sanity check links the parts: under constant acceleration from rest, average velocity is half the final velocity, so \\(\\mathbf{s}=\\tfrac12\\mathbf{v}(4)\\times4=\\tfrac12(8,16,4)\\times4=(16,32,8)\\), exactly matching." } ], finalAnswer: "\\(\\mathbf{a} = (2, 4, 1)\\); \\(\\mathbf{v}(4) = (8, 16, 4)\\); \\(\\mathbf{s}(4) = (16, 32, 8)\\)." } },
  { id: "y2v2-057", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 57", difficulty: "Challenge", questionText: "Given \\(\\mathbf{a} = 2\\mathbf{i} - 3\\mathbf{j} + \\mathbf{k}\\), find values of \\(c\\) such that \\(|\\mathbf{a} + c\\mathbf{k}| = 7\\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["magnitude"], workedSolution: { steps: [ { stepNumber: 1, description: "Write a in component form", workingLatex: "\\mathbf{a} = \\begin{pmatrix} 2 \\\\ -3 \\\\ 1 \\end{pmatrix}", explanation: "Reading \\(\\mathbf{a} = 2\\mathbf{i} - 3\\mathbf{j} + \\mathbf{k}\\) as a column vector makes the next operation, adding a vector along \\(\\mathbf{k}\\), purely mechanical. The key observation is that \\(c\\mathbf{k}\\) lives entirely along the third axis, so it can only move the \\(z\\)-coordinate. Geometrically we are sliding the tip of \\(\\mathbf{a}\\) up or down a vertical line and asking when its distance from the origin hits \\(7\\)." }, { stepNumber: 2, description: "Add the c k term to a", workingLatex: "\\mathbf{a} + c\\mathbf{k} = 2\\mathbf{i} - 3\\mathbf{j} + (1 + c)\\mathbf{k}", explanation: "Only the \\(\\mathbf{k}\\)-component changes, becoming \\(1 + c\\); the \\(\\mathbf{i}\\) and \\(\\mathbf{j}\\) parts are untouched because \\(c\\mathbf{k}\\) has zero \\(x\\)- and \\(y\\)-components. A frequent slip is to add \\(c\\) onto every component or to write the new \\(z\\) as just \\(c\\) rather than \\(1+c\\); always combine the existing \\(1\\) with the new \\(c\\)." }, { stepNumber: 3, description: "Write the magnitude expression", workingLatex: "|\\mathbf{a} + c\\mathbf{k}| = \\sqrt{2^2 + (-3)^2 + (1 + c)^2}", explanation: "The magnitude is the square root of the sum of the squared components, the 3D Pythagoras. Keep the \\(\\mathbf{k}\\)-component as the unexpanded bracket \\((1+c)^2\\); expanding it now to \\(1+2c+c^2\\) only clutters the algebra and invites sign errors, since we intend to take a square root of it later." }, { stepNumber: 4, description: "Set the magnitude equal to 7", workingLatex: "\\sqrt{4 + 9 + (1 + c)^2} = 7", explanation: "Substituting the given condition \\(|\\mathbf{a}+c\\mathbf{k}|=7\\) turns the geometry into a single equation in \\(c\\). We have already evaluated \\(2^2 = 4\\) and \\((-3)^2 = 9\\); note \\((-3)^2\\) is \\(+9\\), not \\(-9\\), a sign trap worth pausing on. Because a magnitude is never negative, demanding it equal a positive \\(7\\) is geometrically sensible." }, { stepNumber: 5, description: "Square both sides to remove the root", workingLatex: "4 + 9 + (1 + c)^2 = 49", explanation: "Squaring is valid here because both sides are non-negative, so no spurious solutions are introduced. The right-hand side becomes \\(7^2 = 49\\). This step trades a hard equation with a surd for a clean quadratic-in-disguise that we can finish by inspection." }, { stepNumber: 6, description: "Combine the constant terms", workingLatex: "13 + (1 + c)^2 = 49", explanation: "Add the fixed contributions from the unchanged components, \\(4 + 9 = 13\\). These \\(13\\) units of squared length come from the \\(x\\)- and \\(y\\)-directions and can never be removed, so the smallest possible magnitude is \\(\\sqrt{13}\\approx 3.6\\); since \\(7>\\sqrt{13}\\) we already know real solutions exist." }, { stepNumber: 7, description: "Isolate the squared bracket", workingLatex: "(1 + c)^2 = 36", explanation: "Subtract \\(13\\) from \\(49\\) to leave a perfect-square equation. The value \\(36\\) is the squared length the \\(z\\)-direction must supply, so \\(|1+c|=6\\): the tip must sit exactly \\(6\\) units above or below the \\(xy\\)-plane reference of the original \\(z=1\\)." }, { stepNumber: 8, description: "Take square roots, keeping both signs", workingLatex: "1 + c = \\pm 6", explanation: "Both \\(+6\\) and \\(-6\\) square to \\(36\\), so both must be kept; dropping the negative root is the single most common error here and would lose one valid value of \\(c\\). Geometrically the two signs correspond to the tip being raised above or lowered below the origin's level by the same amount." }, { stepNumber: 9, description: "Solve the positive branch for c", workingLatex: "1 + c = 6 \\;\\Rightarrow\\; c = 5", explanation: "Subtracting \\(1\\) from the \\(+6\\) case gives \\(c = 5\\), which makes the \\(z\\)-component \\(1+5 = 6\\). This is the solution where the added vector pushes the point further up the \\(z\\)-axis." }, { stepNumber: 10, description: "Solve the negative branch for c", workingLatex: "1 + c = -6 \\;\\Rightarrow\\; c = -7", explanation: "Subtracting \\(1\\) from the \\(-6\\) case gives \\(c = -7\\), making the \\(z\\)-component \\(1-7 = -6\\). The added vector now drags the point below the plane; both extremes are the same distance from the origin, which is why both are answers." }, { stepNumber: 11, description: "Sanity-check both magnitudes", workingLatex: "\\sqrt{4+9+6^2} = \\sqrt{49} = 7,\\quad \\sqrt{4+9+(-6)^2} = \\sqrt{49} = 7", explanation: "Substituting \\(c=5\\) and \\(c=-7\\) back both reproduce the target magnitude \\(7\\), confirming the algebra. This check costs almost nothing and instantly catches an arithmetic slip in the constants, so it is well worth doing in an exam." } ], finalAnswer: "\\(c = 5\\) or \\(c = -7\\)." } },
  { id: "y2v2-058", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 58", difficulty: "Challenge", questionText: "An object moves with constant acceleration \\(\\mathbf{a} = (1, 0, 2)\\) m/s². Initially at origin with velocity \\(\\mathbf{u} = (2, 3, 0)\\) m/s. Find the position at \\(t = 5\\) s.", marks: 5, examStyle: true, yearCreated: 2026, tags: ["applied", "kinematics"], workedSolution: { steps: [ { stepNumber: 1, description: "State the vector position equation", workingLatex: "\\mathbf{r}(t) = \\mathbf{r}_0 + \\mathbf{u}t + \\tfrac{1}{2}\\mathbf{a}t^2", explanation: "This is the constant-acceleration (\"suvat\") displacement formula, applied as a single vector identity rather than three separate scalar equations. Because acceleration is constant, each component obeys the same quadratic-in-\\(t\\) law independently, which is exactly why the vector form is legitimate. Recognise this template whenever you are given \\(\\mathbf{u}\\), \\(\\mathbf{a}\\) and a time and asked for position." }, { stepNumber: 2, description: "Record the starting position", workingLatex: "\\mathbf{r}_0 = \\begin{pmatrix} 0 \\\\ 0 \\\\ 0 \\end{pmatrix}", explanation: "The phrase \"initially at origin\" fixes \\(\\mathbf{r}_0 = \\mathbf{0}\\). It is worth writing this explicitly: forgetting a non-zero start is a classic error, and stating it here reminds us that the answer will be a true position, not merely a displacement." }, { stepNumber: 3, description: "Drop the zero starting position", workingLatex: "\\mathbf{r}(t) = \\mathbf{u}t + \\tfrac{1}{2}\\mathbf{a}t^2", explanation: "With \\(\\mathbf{r}_0 = \\mathbf{0}\\) the formula simplifies, so here position and displacement from the origin coincide. Had the object started elsewhere we would simply add that constant vector at the end; keeping the structure in mind prevents over-simplifying in future problems where \\(\\mathbf{r}_0\\neq\\mathbf{0}\\)." }, { stepNumber: 4, description: "Substitute u, a and t = 5", workingLatex: "\\mathbf{r}(5) = (2, 3, 0)(5) + \\tfrac{1}{2}(1, 0, 2)(5)^2", explanation: "Insert the initial velocity \\((2,3,0)\\), the acceleration \\((1,0,2)\\), and \\(t=5\\). Note the \\(t^2\\) sits only in the acceleration term: a common slip is to square the time in the velocity term too. Squaring time before multiplying through keeps the order of operations correct." }, { stepNumber: 5, description: "Evaluate the velocity displacement term", workingLatex: "(2, 3, 0)(5) = (10, 15, 0)", explanation: "Multiply each component of \\(\\mathbf{u}\\) by \\(5\\) to get the displacement the object would have if it never accelerated. The \\(z\\)-component stays \\(0\\) here because the launch had no vertical velocity, even though the object will later gain height from acceleration." }, { stepNumber: 6, description: "Compute the acceleration scalar factor", workingLatex: "\\tfrac{1}{2}(5)^2 = \\tfrac{1}{2}(25) = 12.5", explanation: "Collapsing \\(\\tfrac12 t^2\\) into the single number \\(12.5\\) lets us scale the acceleration vector in one clean multiplication. Doing this scalar arithmetic separately, before touching the vector, reduces the chance of mismatching components and is a good habit on multi-component problems." }, { stepNumber: 7, description: "Evaluate the acceleration displacement term", workingLatex: "12.5(1, 0, 2) = (12.5, 0, 25)", explanation: "Scale \\(\\mathbf{a}\\) by \\(12.5\\). The \\(y\\)-component stays \\(0\\) because there is no acceleration in that direction, while the \\(z\\)-component jumps to \\(25\\) — all of the object's eventual height comes from this term, since it started with zero vertical speed." }, { stepNumber: 8, description: "Add the two contributions componentwise", workingLatex: "\\mathbf{r}(5) = (10 + 12.5,\\; 15 + 0,\\; 0 + 25)", explanation: "Add the velocity and acceleration displacements slot by slot, aligning \\(x\\) with \\(x\\), \\(y\\) with \\(y\\), \\(z\\) with \\(z\\). Mixing components across columns is the most common arithmetic mistake here; writing the additions out in line guards against it." }, { stepNumber: 9, description: "Add the x-components", workingLatex: "x = 10 + 12.5 = 22.5", explanation: "The \\(x\\)-position blends a uniform part (\\(10\\) m from the initial velocity) with an accelerated part (\\(12.5\\) m). Both directions contribute here because the object has both forward speed and forward acceleration along \\(x\\), so this coordinate grows faster than linearly with time." }, { stepNumber: 10, description: "Add the y-components", workingLatex: "y = 15 + 0 = 15", explanation: "Along \\(y\\) there is no acceleration, so the motion is purely uniform and \\(y = 3\\,\\text{m/s}\\times 5\\,\\text{s} = 15\\,\\text{m}\\). This clean linear result is a useful internal check that the velocity term was scaled correctly." }, { stepNumber: 11, description: "Add the z-components", workingLatex: "z = 0 + 25 = 25", explanation: "Along \\(z\\) the initial velocity is zero, so all \\(25\\) m of height come from acceleration alone. This is the mirror image of the \\(y\\)-axis: there velocity acted without acceleration, here acceleration acts without initial velocity." }, { stepNumber: 12, description: "State the final position vector", workingLatex: "\\mathbf{r}(5) = (22.5, 15, 25)\\text{ m}", explanation: "Assembling the three coordinates gives the position after \\(5\\) s, in metres from the origin. The pattern across axes — accelerated, uniform, and from-rest respectively — makes the answer easy to sense-check and confirms the components were never mixed." } ], finalAnswer: "\\((22.5, 15, 25)\\) m." } },
  { id: "y2v2-059", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 59", difficulty: "Challenge", questionText: "A runner in a stadium runs the diagonal of a cuboidal running track with corner dimensions 100 m × 50 m × 10 m (height of stand). Find the straight-line distance.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["applied", "distance"], workedSolution: { steps: [ { stepNumber: 1, description: "Identify the three perpendicular edges", workingLatex: "\\ell = 100,\\quad w = 50,\\quad h = 10", explanation: "A cuboidal track has three mutually perpendicular edges: length \\(100\\) m, width \\(50\\) m and height \\(10\\) m. Listing them first fixes which number plays which role and reminds us that the height, though small, is a genuine third dimension. The straight-line run is the space diagonal joining two opposite corners across all three edges." }, { stepNumber: 2, description: "Model the diagonal as a vector", workingLatex: "\\mathbf{d} = \\begin{pmatrix} 100 \\\\ 50 \\\\ 10 \\end{pmatrix}", explanation: "Because the edges are mutually perpendicular, they become the components of the diagonal vector directly: \\((100,50,10)\\). Picturing the runner's path as this single arrow turns the geometry into a magnitude calculation. There is no cross-coupling between axes precisely because they meet at right angles." }, { stepNumber: 3, description: "Write the 3D distance formula", workingLatex: "d = \\sqrt{x^2 + y^2 + z^2}", explanation: "The straight-line length is the magnitude of the diagonal vector — the 3D extension of Pythagoras. Conceptually it stacks two right-angle triangles: first the floor diagonal \\(\\sqrt{100^2+50^2}\\), then that hypotenuse with the vertical \\(10\\). Squaring all three at once is just the compact form of doing those two triangles in sequence." }, { stepNumber: 4, description: "Substitute the three dimensions", workingLatex: "d = \\sqrt{100^2 + 50^2 + 10^2}", explanation: "Insert the edge lengths \\(100\\), \\(50\\) and \\(10\\). Including the \\(10\\) m height is essential: omitting it would give only the floor diagonal and understate the distance. The most common error here is treating the track as flat because the height is small, but the question explicitly asks for the full 3D straight line." }, { stepNumber: 5, description: "Square the length term", workingLatex: "100^2 = 10000", explanation: "The length dominates the radicand at \\(10000\\). Evaluating it on its own highlights that this single term is four times larger than everything else combined, so the diagonal will be only slightly longer than the \\(100\\) m edge itself." }, { stepNumber: 6, description: "Square the width and height terms", workingLatex: "50^2 = 2500,\\quad 10^2 = 100", explanation: "The width contributes \\(2500\\) and the height only \\(100\\). Squaring each separately keeps the arithmetic transparent and exposes how little the \\(10\\) m height adds — yet it must still be carried, since dropping it changes the rounded answer at the second decimal place." }, { stepNumber: 7, description: "Sum the squared terms", workingLatex: "d = \\sqrt{10000 + 2500 + 100} = \\sqrt{12600}", explanation: "Add the three squares to get the radicand \\(12600\\). Keeping it as an exact surd here, rather than rounding mid-way, preserves full precision for the final rounding step. A quick estimate, \\(\\sqrt{12600}\\) is a little over \\(\\sqrt{12100}=110\\), already tells us the answer should be just above \\(110\\) m." }, { stepNumber: 8, description: "Take the root for the distance", workingLatex: "d = \\sqrt{12600} = 112.249\\ldots", explanation: "Evaluating the root gives \\(112.249\\ldots\\) m. This sits comfortably above our \\(110\\) m estimate, confirming the result is sensible. It is barely longer than the floor diagonal \\(\\sqrt{12500}\\approx 111.8\\) m, which makes sense because the \\(10\\) m rise adds very little to a path over \\(100\\) m long." }, { stepNumber: 9, description: "Round to two decimal places", workingLatex: "d \\approx 112.25\\text{ m}", explanation: "Rounding \\(112.249\\ldots\\) to two decimal places gives \\(112.25\\) m, the straight-line distance the runner covers. Rounding only at this last stage, after carrying the exact surd throughout, guarantees the final digit is reliable." }, { stepNumber: 10, description: "Confirm the result is reasonable", workingLatex: "112.25 > 100 = \\max(\\ell, w, h)", explanation: "As a final sanity check, a space diagonal must be longer than any single edge, and indeed \\(112.25\\) m exceeds the longest edge \\(100\\) m. It also exceeds the floor diagonal \\(\\approx 111.8\\) m by just the right tiny amount for a \\(10\\) m rise, so the answer is geometrically consistent." } ], finalAnswer: "\\(\\approx 112.25\\) m." } },
  { id: "y2v2-060", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 60", difficulty: "Challenge", questionText: "The points \\(A(1, 1, 1)\\), \\(B(2, 3, 5)\\), \\(C(a, 5, b)\\) are collinear. Find the values of \\(a\\) and \\(b\\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["collinear"], workedSolution: { steps: [ { stepNumber: 1, description: "Recall the collinearity strategy", workingLatex: "A,B,C \\text{ collinear} \\iff \\mathbf{AC} = \\lambda\\,\\mathbf{AB}", explanation: "Three points lie on one straight line exactly when the vector from \\(A\\) to \\(C\\) is a scalar multiple of the vector from \\(A\\) to \\(B\\): they must point along the same direction. The single scalar \\(\\lambda\\) must work for all three components simultaneously, and that shared-\\(\\lambda\\) requirement is precisely what lets us pin down the unknowns \\(a\\) and \\(b\\)." }, { stepNumber: 2, description: "Find the vector AB", workingLatex: "\\mathbf{AB} = B - A = (2 - 1,\\; 3 - 1,\\; 5 - 1)", explanation: "Subtract the position of \\(A\\) from \\(B\\) componentwise to get the direction of the known segment. The order \\(B-A\\) matters for sign but not for collinearity; what counts is that this same reference direction is reused for \\(\\mathbf{AC}\\)." }, { stepNumber: 3, description: "Simplify AB", workingLatex: "\\mathbf{AB} = (1, 2, 4)", explanation: "Evaluating the differences gives the baseline direction \\((1,2,4)\\) that the third point must share. Reading off the middle entry, \\(2\\), is what makes this vector so useful: it pairs with the fully numeric \\(y\\)-component of \\(\\mathbf{AC}\\) to fix \\(\\lambda\\) cleanly." }, { stepNumber: 4, description: "Find the vector AC symbolically", workingLatex: "\\mathbf{AC} = C - A = (a - 1,\\; 5 - 1,\\; b - 1)", explanation: "Subtract \\(A\\) from \\(C\\), keeping \\(a\\) and \\(b\\) as symbols since they are unknown. Crucially the \\(y\\)-coordinate of \\(C\\) is given as \\(5\\), so that component is fully numeric — this is the lever we exploit next to find \\(\\lambda\\) without any unknowns in the way." }, { stepNumber: 5, description: "Simplify the y-component of AC", workingLatex: "\\mathbf{AC} = (a - 1,\\; 4,\\; b - 1)", explanation: "The middle component evaluates to \\(5 - 1 = 4\\). Having one fully numeric slot in \\(\\mathbf{AC}\\) is the structural key: it lets us extract the scalar \\(\\lambda\\) first and only afterwards solve for the genuinely unknown components." }, { stepNumber: 6, description: "Write the scalar-multiple equation", workingLatex: "(a - 1,\\; 4,\\; b - 1) = \\lambda\\,(1, 2, 4)", explanation: "Equating \\(\\mathbf{AC}\\) with \\(\\lambda\\,\\mathbf{AB}\\) gives three scalar equations sharing one \\(\\lambda\\). Listing them this way makes plain that the \\(y\\)-equation, \\(4 = 2\\lambda\\), is the only one with numbers on both sides, so it is the natural starting point." }, { stepNumber: 7, description: "Find lambda from the y-component", workingLatex: "4 = 2\\lambda \\;\\Rightarrow\\; \\lambda = 2", explanation: "Because both \\(y\\)-entries are known, equating them isolates \\(\\lambda = 2\\) with no unknowns involved. Always seek a fully numeric component to fix the scalar first; trying to start from an equation containing \\(a\\) or \\(b\\) would leave two unknowns in one equation and stall the solution." }, { stepNumber: 8, description: "Apply lambda to the x-component", workingLatex: "a - 1 = 2(1) = 2", explanation: "Substitute \\(\\lambda = 2\\) into the \\(x\\)-equation, so the unknown displacement \\(a-1\\) must equal \\(2\\) times \\(\\mathbf{AB}\\)'s \\(x\\)-component. This forces \\(C\\) to advance along the line by the same factor in every direction, which is the geometric meaning of \\(\\lambda\\)." }, { stepNumber: 9, description: "Solve for a", workingLatex: "a = 3", explanation: "Adding \\(1\\) to both sides gives \\(a = 3\\). A quick check: from \\(A(1,1,1)\\) moving by \\(\\lambda\\mathbf{AB}=2(1,2,4)=(2,4,8)\\) lands the \\(x\\)-coordinate at \\(1+2 = 3\\), matching." }, { stepNumber: 10, description: "Apply lambda to the z-component", workingLatex: "b - 1 = 2(4) = 8", explanation: "Substitute \\(\\lambda = 2\\) into the \\(z\\)-equation, where \\(\\mathbf{AB}\\) contributes \\(4\\). That the same \\(\\lambda\\) consistently satisfies every component is the confirmation that the three points really are collinear, not merely that two equations happened to agree." }, { stepNumber: 11, description: "Solve for b and verify", workingLatex: "b = 9 \\;\\Rightarrow\\; C = (3, 5, 9)", explanation: "Adding \\(1\\) gives \\(b = 9\\), so \\(C=(3,5,9)\\). Checking against \\(A + 2\\mathbf{AB} = (1,1,1)+(2,4,8) = (3,5,9)\\) reproduces \\(C\\) exactly, confirming all three components are consistent with the single scalar \\(\\lambda = 2\\) and the points are genuinely collinear." } ], finalAnswer: "\\(a = 3,\\ b = 9\\)." } },
  { id: "y2v2-061", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 61", difficulty: "Challenge", questionText: "An aeroplane lands on a runway making angle \\(5^{\\circ}\\) with the horizontal. Approaching at 200 km/h, find the horizontal and vertical components of velocity.", marks: 5, examStyle: true, yearCreated: 2026, tags: ["applied", "mechanics"], workedSolution: { steps: [ { stepNumber: 1, description: "Identify the velocity triangle", workingLatex: "v = 200,\\quad \\alpha = 5^{\\circ}", explanation: "The aeroplane's speed \\(200\\) km/h is the hypotenuse of a right-angled velocity triangle, and the \\(5^{\\circ}\\) glide angle is measured down from the horizontal. Resolving a velocity means projecting this hypotenuse onto the horizontal and vertical directions, so getting clear on which side is which now prevents swapping sine and cosine later." }, { stepNumber: 2, description: "Decide which ratio is horizontal", workingLatex: "\\text{horizontal} \\parallel \\text{adjacent to } \\alpha", explanation: "Since the \\(5^{\\circ}\\) is measured from the horizontal, the horizontal direction lies adjacent to the angle and the vertical lies opposite it. This is the crux of the whole question: with the angle taken from the ground, cosine gives the large horizontal part and sine the small vertical part. Were the angle measured from the vertical instead, these would swap." }, { stepNumber: 3, description: "Resolve the horizontal component", workingLatex: "v_{\\text{horiz}} = v\\cos\\alpha = 200\\cos 5^{\\circ}", explanation: "The component adjacent to the angle uses cosine, so the forward ground speed is \\(200\\cos 5^{\\circ}\\). Because \\(5^{\\circ}\\) is shallow, we expect this to be very close to the full \\(200\\) km/h — a useful intuition check before reaching for the calculator." }, { stepNumber: 4, description: "Evaluate cosine of the angle", workingLatex: "\\cos 5^{\\circ} \\approx 0.99619", explanation: "Compute \\(\\cos 5^{\\circ} \\approx 0.99619\\), very nearly \\(1\\). Make sure the calculator is in degree mode; in radian mode \\(\\cos 5\\) would be about \\(0.28\\), and the answer would come out wildly wrong — this mode error is the single most common slip in resolving velocities." }, { stepNumber: 5, description: "Compute the horizontal speed", workingLatex: "v_{\\text{horiz}} = 200(0.99619) \\approx 199.24\\text{ km/h}", explanation: "Multiplying by the speed gives \\(199.24\\) km/h, satisfyingly close to the full \\(200\\) as predicted for such a shallow descent. Almost all of the plane's speed is directed forwards along the ground, which matches the physical picture of a gentle glide." }, { stepNumber: 6, description: "Resolve the vertical component", workingLatex: "v_{\\text{vert}} = v\\sin\\alpha = 200\\sin 5^{\\circ}", explanation: "The component opposite the angle uses sine, giving the rate of descent \\(200\\sin 5^{\\circ}\\). This is the speed at which the plane loses height; for a shallow glide angle it should come out small, which provides an immediate plausibility check on the value." }, { stepNumber: 7, description: "Evaluate sine of the angle", workingLatex: "\\sin 5^{\\circ} \\approx 0.08716", explanation: "Compute \\(\\sin 5^{\\circ} \\approx 0.08716\\), a small fraction reflecting the shallow angle. Again the calculator must be in degree mode; the smallness of this value is exactly what we expect, since a \\(5^{\\circ}\\) approach barely tilts the velocity away from horizontal." }, { stepNumber: 8, description: "Compute the vertical speed", workingLatex: "v_{\\text{vert}} = 200(0.08716) \\approx 17.43\\text{ km/h}", explanation: "Multiplying by the speed gives a descent rate of \\(17.43\\) km/h — small, as expected. A neat consistency check: \\(199.24^2 + 17.43^2 \\approx 40000 = 200^2\\), so the two components correctly recombine to the original speed via Pythagoras." }, { stepNumber: 9, description: "State the direction of descent", workingLatex: "v_{\\text{vert}} \\text{ acts downward}", explanation: "Because the plane is landing, the vertical component points downward; taking up as positive it would be \\(-17.43\\) km/h. Stating the direction, not just the magnitude, is essential — a velocity component carries a sign, and omitting it loses information about whether the plane climbs or descends." }, { stepNumber: 10, description: "Round and quote both answers", workingLatex: "v_{\\text{horiz}} \\approx 199.2,\\quad v_{\\text{vert}} \\approx 17.4\\;(\\text{downward})", explanation: "Quoting both to one decimal place gives \\(199.2\\) km/h forward and \\(17.4\\) km/h down, the complete resolved velocity. Rounding only at the end keeps the figures accurate, and presenting both magnitude and direction fully answers the question." } ], finalAnswer: "\\(\\approx 199.2\\) km/h horizontal, \\(\\approx 17.4\\) km/h downward." } },
  { id: "y2v2-062", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 62", difficulty: "Challenge", questionText: "A vector \\(\\mathbf{a}\\) has \\(|\\mathbf{a}| = 5\\) and makes angles \\(60^{\\circ}\\) with the \\(x\\)-axis, \\(45^{\\circ}\\) with the \\(y\\)-axis, \\(\\theta\\) with the \\(z\\)-axis. Find \\(\\theta\\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["angle"], workedSolution: { steps: [ { stepNumber: 1, description: "Recall the direction cosine identity", workingLatex: "\\cos^2\\alpha + \\cos^2\\beta + \\cos^2\\gamma = 1", explanation: "The cosines of the angles a vector makes with the three coordinate axes are its direction cosines, and the sum of their squares is always \\(1\\). This is really Pythagoras in disguise: those cosines are the components of the unit vector along \\(\\mathbf{a}\\), whose length is \\(1\\). Recognising the three-axis-angle setup is the signal to reach for this identity." }, { stepNumber: 2, description: "Note the magnitude is irrelevant", workingLatex: "|\\mathbf{a}| = 5 \\text{ does not enter the identity}", explanation: "The magnitude \\(5\\) is a deliberate distractor: direction cosines depend only on orientation, not length, since they describe the unit vector. A common slip is to try to weave the \\(5\\) into the calculation; resisting that keeps the work clean and is itself a small conceptual check that you understand what direction cosines measure." }, { stepNumber: 3, description: "Substitute the known angles", workingLatex: "\\cos^2 60^{\\circ} + \\cos^2 45^{\\circ} + \\cos^2\\theta = 1", explanation: "Insert \\(\\alpha = 60^{\\circ}\\) (with the \\(x\\)-axis) and \\(\\beta = 45^{\\circ}\\) (with the \\(y\\)-axis), leaving \\(\\gamma = \\theta\\), the angle with the \\(z\\)-axis, as the only unknown. The identity now reduces to a single equation in \\(\\cos^2\\theta\\)." }, { stepNumber: 4, description: "Insert exact cosine values", workingLatex: "\\left(\\tfrac{1}{2}\\right)^2 + \\left(\\tfrac{1}{\\sqrt{2}}\\right)^2 + \\cos^2\\theta = 1", explanation: "Use the exact surd values \\(\\cos 60^{\\circ} = \\tfrac12\\) and \\(\\cos 45^{\\circ} = \\tfrac{1}{\\sqrt2}\\). Working exactly rather than with decimals avoids rounding error and reveals the clean fractions that make the final angle recognisable without a calculator." }, { stepNumber: 5, description: "Square the known cosines", workingLatex: "\\tfrac{1}{4} + \\tfrac{1}{2} + \\cos^2\\theta = 1", explanation: "Squaring gives \\(\\left(\\tfrac12\\right)^2 = \\tfrac14\\) and \\(\\left(\\tfrac{1}{\\sqrt2}\\right)^2 = \\tfrac12\\). Note \\(\\left(\\tfrac{1}{\\sqrt2}\\right)^2 = \\tfrac12\\), not \\(\\tfrac{1}{\\sqrt2}\\) — squaring the surd properly is where careless work tends to go astray." }, { stepNumber: 6, description: "Combine the known fractions", workingLatex: "\\tfrac{3}{4} + \\cos^2\\theta = 1", explanation: "Add the two contributions \\(\\tfrac14 + \\tfrac12 = \\tfrac34\\). This is the total squared direction cosine already used up by the \\(x\\)- and \\(y\\)-axes, leaving only \\(\\tfrac14\\) of the unit \"budget\" for the \\(z\\)-direction." }, { stepNumber: 7, description: "Isolate cos squared theta", workingLatex: "\\cos^2\\theta = 1 - \\tfrac{3}{4} = \\tfrac{1}{4}", explanation: "Subtracting from \\(1\\) leaves \\(\\cos^2\\theta = \\tfrac14\\), a clean perfect square. That the right-hand side is positive confirms a real angle exists; had the given angles been too small, this could have gone negative and signalled an impossible configuration." }, { stepNumber: 8, description: "Take square roots, keeping both signs", workingLatex: "\\cos\\theta = \\pm\\tfrac{1}{2}", explanation: "Both signs survive because squaring erased the sign information. Geometrically the vector could lean toward the positive \\(z\\)-axis (\\(\\cos\\theta>0\\)) or away from it (\\(\\cos\\theta<0\\)); both orientations make the same magnitude of angle-squared, so both must be reported." }, { stepNumber: 9, description: "Solve the positive cosine case", workingLatex: "\\theta = \\cos^{-1}\\!\\left(\\tfrac{1}{2}\\right) = 60^{\\circ}", explanation: "Taking \\(\\cos\\theta = +\\tfrac12\\) gives \\(\\theta = 60^{\\circ}\\), a vector leaning toward the positive \\(z\\)-axis. This value lies in \\([0^{\\circ},180^{\\circ}]\\), the only legitimate range for an angle between a vector and an axis, so it is admissible." }, { stepNumber: 10, description: "Solve the negative cosine case", workingLatex: "\\theta = \\cos^{-1}\\!\\left(-\\tfrac{1}{2}\\right) = 120^{\\circ}", explanation: "Taking \\(\\cos\\theta = -\\tfrac12\\) gives \\(\\theta = 120^{\\circ}\\), a vector leaning away from the positive \\(z\\)-axis. This too lies in the valid range, so both answers stand." }, { stepNumber: 11, description: "Report both valid direction angles", workingLatex: "\\theta = 60^{\\circ} \\quad\\text{or}\\quad \\theta = 120^{\\circ}", explanation: "Both \\(60^{\\circ}\\) and \\(120^{\\circ}\\) satisfy the direction-cosine identity, so the question genuinely admits two distinct vectors — one tilted up and one tilted down relative to the \\(z\\)-axis. Discarding either, a tempting mistake once a single inverse-cosine is found, would lose half the answer." } ], finalAnswer: "\\(\\theta = 60^{\\circ}\\) or \\(\\theta = 120^{\\circ}\\)." } },
  { id: "y2v2-063", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 63", difficulty: "Challenge", questionText: "A drone follows a path \\(\\mathbf{r}(t) = (\\sin t, \\cos t, t)\\) m. Find the speed at \\(t = \\pi/2\\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["applied", "kinematics"], workedSolution: { steps: [ { stepNumber: 1, description: "Define speed as velocity magnitude", workingLatex: "\\text{speed} = |\\mathbf{v}(t)|,\\quad \\mathbf{v}(t) = \\frac{d\\mathbf{r}}{dt}", explanation: "Velocity is the time derivative of the position vector, and speed is its magnitude — a single non-negative number stripped of direction. The drone's path \\((\\sin t,\\cos t,t)\\) is a helix (circular motion in \\(x\\)-\\(y\\) plus steady rise in \\(z\\)), so we expect a constant speed; recognising \"find the speed\" means \"differentiate then take magnitude\" is the whole strategy." }, { stepNumber: 2, description: "Set up componentwise differentiation", workingLatex: "\\mathbf{v}(t) = \\left(\\tfrac{d}{dt}\\sin t,\\; \\tfrac{d}{dt}\\cos t,\\; \\tfrac{d}{dt}t\\right)", explanation: "A vector function is differentiated one component at a time, because the basis directions \\(\\mathbf{i},\\mathbf{j},\\mathbf{k}\\) are fixed. Laying out the three derivatives before evaluating them keeps the structure clear and ensures none is forgotten." }, { stepNumber: 3, description: "Differentiate the x and z parts", workingLatex: "\\tfrac{d}{dt}\\sin t = \\cos t,\\qquad \\tfrac{d}{dt}t = 1", explanation: "The \\(x\\)-component \\(\\sin t\\) differentiates to \\(\\cos t\\), giving the horizontal velocity, while the \\(z\\)-component \\(t\\) differentiates to the constant \\(1\\), a steady climb. That constant vertical rate is what stretches the circular motion into a rising helix rather than a flat circle." }, { stepNumber: 4, description: "Differentiate the y part carefully", workingLatex: "\\tfrac{d}{dt}\\cos t = -\\sin t", explanation: "The \\(y\\)-component \\(\\cos t\\) differentiates to \\(-\\sin t\\); the minus sign is the easiest thing to drop here. Losing it would not change this particular speed (the sign vanishes under squaring) but it would corrupt the velocity direction, so it is a habit worth keeping correct for problems where direction matters." }, { stepNumber: 5, description: "Assemble the velocity vector", workingLatex: "\\mathbf{v}(t) = (\\cos t,\\; -\\sin t,\\; 1)", explanation: "Combining the three derivatives gives the general velocity \\((\\cos t, -\\sin t, 1)\\). Notice the \\(x\\)- and \\(y\\)-parts trace a unit circle as \\(t\\) varies, so the horizontal speed is always \\(1\\); only the constant vertical \\(1\\) adds to it, foreshadowing a time-independent speed." }, { stepNumber: 6, description: "Substitute t = pi/2", workingLatex: "\\mathbf{v}\\!\\left(\\tfrac{\\pi}{2}\\right) = \\left(\\cos\\tfrac{\\pi}{2},\\; -\\sin\\tfrac{\\pi}{2},\\; 1\\right)", explanation: "Evaluate the velocity at the required instant \\(t = \\tfrac{\\pi}{2}\\). The argument is in radians, so the trig functions must be read in radians; treating \\(\\tfrac{\\pi}{2}\\) as degrees would give nonsense. The constant \\(z\\)-velocity of \\(1\\) stays \\(1\\) regardless of time." }, { stepNumber: 7, description: "Evaluate the trig values", workingLatex: "\\mathbf{v}\\!\\left(\\tfrac{\\pi}{2}\\right) = (0, -1, 1)", explanation: "At \\(t=\\tfrac{\\pi}{2}\\), \\(\\cos\\tfrac{\\pi}{2} = 0\\) and \\(\\sin\\tfrac{\\pi}{2} = 1\\), giving velocity \\((0,-1,1)\\). The zero \\(x\\)-velocity makes sense: at this point the helix is momentarily moving purely in the \\(-y\\) and \\(+z\\) directions as it sweeps around the circle." }, { stepNumber: 8, description: "Square each velocity component", workingLatex: "0^2 + (-1)^2 + 1^2 = 0 + 1 + 1", explanation: "Square the components ready for the magnitude. The negative sign on \\(-1\\) disappears under squaring, so both the \\(y\\)- and \\(z\\)-terms contribute \\(+1\\); only the zero \\(x\\)-term drops out." }, { stepNumber: 9, description: "Sum the squares and root", workingLatex: "|\\mathbf{v}| = \\sqrt{0 + 1 + 1} = \\sqrt{2}\\text{ m/s}", explanation: "Adding the squared components gives \\(2\\) under the root, so the speed is \\(\\sqrt{2}\\approx 1.41\\) m/s. The zero \\(x\\)-term contributes nothing, leaving the descent-direction and climb terms to combine into the answer." }, { stepNumber: 10, description: "Confirm the speed is constant", workingLatex: "|\\mathbf{v}(t)| = \\sqrt{\\cos^2 t + \\sin^2 t + 1} = \\sqrt{1 + 1} = \\sqrt{2}", explanation: "As a sanity check, computing the magnitude for general \\(t\\) uses \\(\\cos^2 t + \\sin^2 t = 1\\), giving \\(\\sqrt{2}\\) at every instant. So the drone's speed is constant along the whole helix — unit circular speed combined with unit climb — which both confirms our \\(t=\\tfrac{\\pi}{2}\\) value and explains why the specific instant did not matter." } ], finalAnswer: "\\(\\sqrt{2}\\) m/s." } },
  { id: "y2v2-064", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 64", difficulty: "Challenge", questionText: "A rectangular box has vertices at \\((0, 0, 0)\\) and \\((5, 3, 2)\\). (a) Find the main diagonal. (b) Find the angle between the main diagonal and the face \\(z = 0\\).", marks: 6, examStyle: true, yearCreated: 2026, tags: ["geometry"], workedSolution: { steps: [ { stepNumber: 1, description: "Write the main diagonal as a vector", workingLatex: "\\mathbf{d} = \\begin{pmatrix} 5 \\\\ 3 \\\\ 2 \\end{pmatrix} - \\begin{pmatrix} 0 \\\\ 0 \\\\ 0 \\end{pmatrix} = \\begin{pmatrix} 5 \\\\ 3 \\\\ 2 \\end{pmatrix}", explanation: "The main diagonal runs from \\((0,0,0)\\) to the opposite vertex \\((5,3,2)\\), so we subtract position vectors to get its direction and length. Subtracting in the other order would merely flip every sign, leaving the magnitude unchanged, so for a length calculation the order is harmless. The components \\(5,3,2\\) are just the box's edge lengths." }, { stepNumber: 2, description: "Square each component of the diagonal", workingLatex: "5^2 = 25,\\quad 3^2 = 9,\\quad 2^2 = 4", explanation: "The magnitude formula needs each component squared first. Squaring termwise like this avoids the classic blunder of squaring the sum, \\((5+3+2)^2\\), which would be completely wrong. Each squared term is the contribution of one axis to the diagonal's total squared length." }, { stepNumber: 3, description: "Sum the squared components", workingLatex: "25 + 9 + 4 = 38", explanation: "Adding the squares gives \\(38\\), the quantity under the root. Keeping it exact rather than rounding now preserves precision for part (b), where this same \\(\\sqrt{38}\\) reappears in the angle calculation." }, { stepNumber: 4, description: "State the diagonal length", workingLatex: "|\\mathbf{d}| = \\sqrt{38}", explanation: "The main diagonal has length \\(\\sqrt{38}\\approx 6.16\\). Since \\(38 = 2\\times 19\\) has no square factor, the surd is already fully simplified and should be left exact. This answers part (a) and feeds directly into the angle in part (b)." }, { stepNumber: 5, description: "Identify the face and its normal", workingLatex: "\\text{face } z = 0 \\;\\Rightarrow\\; \\text{normal along } z\\text{-axis}", explanation: "The face \\(z = 0\\) is the horizontal base of the box, so the direction perpendicular to it is the \\(z\\)-axis. Pinning down the normal direction is the conceptual hinge of part (b): the angle between a line and a plane is built from how much of the line lies along this normal versus along its full length." }, { stepNumber: 6, description: "Read off the perpendicular component", workingLatex: "z\\text{-component of }\\mathbf{d} = 2", explanation: "The part of the diagonal sticking up out of the plane is exactly its \\(z\\)-component, \\(2\\) — the height climbed from base to top. This is the side opposite the angle we want, the vertical leg of the right triangle whose hypotenuse is the full diagonal." }, { stepNumber: 7, description: "Choose sine for the line-plane angle", workingLatex: "\\sin\\theta = \\frac{\\text{perpendicular component}}{\\text{full length}} = \\frac{2}{\\sqrt{38}}", explanation: "The angle a line makes with a plane is found from the perpendicular (out-of-plane) component over the full length, which is a sine ratio, not cosine. Using cosine here is the textbook mistake: cosine would instead give the angle with the normal to the plane. Picture the right triangle whose hypotenuse is the diagonal and whose vertical leg is the rise of \\(2\\)." }, { stepNumber: 8, description: "Evaluate the ratio numerically", workingLatex: "\\frac{2}{\\sqrt{38}} \\approx \\frac{2}{6.1644} \\approx 0.3244", explanation: "Convert the surd ratio to a decimal, \\(\\sqrt{38}\\approx 6.1644\\), before taking the inverse sine. Carry several digits through this step: rounding \\(\\sqrt{38}\\) too early would shift the final angle by a few tenths of a degree." }, { stepNumber: 9, description: "Take the inverse sine for the angle", workingLatex: "\\theta = \\sin^{-1}(0.3244) \\approx 18.9^{\\circ}", explanation: "Inverting gives \\(\\theta \\approx 18.9^{\\circ}\\). Make sure the calculator is in degree mode, or the result would come out in radians (about \\(0.33\\)) and look wrong — the same mode trap that catches students throughout this topic." }, { stepNumber: 10, description: "Check the angle is plausible", workingLatex: "\\text{floor diagonal} = \\sqrt{5^2 + 3^2} = \\sqrt{34} \\approx 5.83 \\gg 2", explanation: "As a sanity check, the rise of \\(2\\) is small compared with the floor diagonal \\(\\sqrt{34}\\approx 5.83\\), so the diagonal lies nearly flat and a shallow angle under \\(20^{\\circ}\\) is exactly what we should expect. This confirms both answers: a main diagonal of \\(\\sqrt{38}\\) for part (a) and an inclination of \\(\\approx 18.9^{\\circ}\\) to the base for part (b)." } ], finalAnswer: "\\(\\sqrt{38}\\); \\(\\approx 18.9^{\\circ}\\)." } },
  { id: "y2v2-065", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 65", difficulty: "Challenge", questionText: "A line passes through \\(A(2, 1, -3)\\) with direction \\(\\mathbf{d} = (1, -2, 2)\\). Find the distance from the origin to this line.", marks: 6, examStyle: true, yearCreated: 2026, tags: ["applied", "geometry"], workedSolution: { steps: [ { stepNumber: 1, description: "Set up the shortest-distance strategy", workingLatex: "d = |\\mathbf{F} - \\mathbf{O}|,\\quad \\mathbf{F} = \\mathbf{A} + t\\,\\mathbf{d}", explanation: "The shortest distance from a point to a line is measured along the perpendicular dropped onto the line, and it ends at a unique point \\(\\mathbf{F}\\) called the foot of the perpendicular. The plan is to find the value of the line-parameter \\(t\\) that places \\(\\mathbf{F}\\) directly opposite the origin, then measure \\(|\\mathbf{F}|\\). Recognise this method whenever you are asked for a distance from a point to a line given in point-plus-direction form." }, { stepNumber: 2, description: "Form the vector from A to the origin", workingLatex: "\\mathbf{AO} = \\mathbf{O} - \\mathbf{A} = \\begin{pmatrix} 0 \\\\ 0 \\\\ 0 \\end{pmatrix} - \\begin{pmatrix} 2 \\\\ 1 \\\\ -3 \\end{pmatrix} = \\begin{pmatrix} -2 \\\\ -1 \\\\ 3 \\end{pmatrix}", explanation: "This vector runs from the known point \\(A\\) on the line to the origin we are measuring from, and its projection onto \\(\\mathbf{d}\\) tells us how far along the line to travel from \\(A\\) to reach \\(\\mathbf{F}\\). Always subtract in the order destination minus start: writing \\(\\mathbf{A} - \\mathbf{O}\\) instead flips every sign and, although it ultimately gives the same distance, it derails the sign of \\(t\\). Geometrically \\(\\mathbf{AO}\\) is the hypotenuse of the right triangle whose legs are the along-line and perpendicular displacements." }, { stepNumber: 3, description: "Write the projection formula for t", workingLatex: "t = \\frac{\\mathbf{AO} \\cdot \\mathbf{d}}{|\\mathbf{d}|^2}", explanation: "Projecting \\(\\mathbf{AO}\\) onto the direction \\(\\mathbf{d}\\) decomposes it into a component along the line plus a component perpendicular to it; the parameter \\(t\\) measures the along-line part in units of \\(\\mathbf{d}\\). Dividing by \\(|\\mathbf{d}|^2\\) (not \\(|\\mathbf{d}|\\)) rescales the dot product so that \\(t\\) counts whole copies of the direction vector, which is exactly what the line equation \\(\\mathbf{A} + t\\mathbf{d}\\) expects." }, { stepNumber: 4, description: "Compute the dot product AO·d", workingLatex: "\\mathbf{AO} \\cdot \\mathbf{d} = (-2)(1) + (-1)(-2) + (3)(2)", explanation: "The dot product multiplies matching components and adds them, measuring how much of \\(\\mathbf{AO}\\) points along the line. The middle term \\((-1)(-2)\\) is the classic trap: two negatives multiply to \\(+2\\), so a hurried student who carries one sign across loses two units here. Keep each bracketed product explicit before summing." }, { stepNumber: 5, description: "Simplify the dot product", workingLatex: "\\mathbf{AO} \\cdot \\mathbf{d} = -2 + 2 + 6 = 6", explanation: "The three signed products combine to \\(6\\); the first two cancel, leaving the \\(z\\)-contribution to dominate. A positive result tells us \\(\\mathbf{F}\\) lies on the same side of \\(A\\) as the direction \\(\\mathbf{d}\\) points, i.e. we move forward along the line, not backward." }, { stepNumber: 6, description: "Compute the squared length of d", workingLatex: "|\\mathbf{d}|^2 = 1^2 + (-2)^2 + 2^2 = 1 + 4 + 4 = 9", explanation: "We need \\(|\\mathbf{d}|^2\\), not \\(|\\mathbf{d}|\\), because the projection formula divides by the squared length; conveniently \\(|\\mathbf{d}| = 3\\) here, a tidy whole number. Squaring removes every sign, so all three terms are positive regardless of the \\(-2\\) in the direction. Forgetting to square (using \\(1 + (-2) + 2\\)) is a frequent slip that produces a nonsensical \\(t\\)." }, { stepNumber: 7, description: "Find the parameter t at the foot", workingLatex: "t = \\frac{6}{9} = \\frac{2}{3}", explanation: "Substituting the dot product over the squared length gives \\(t = \\tfrac{2}{3}\\), meaning the foot lies two-thirds of one direction-vector step beyond \\(A\\). Keep this as an exact fraction rather than \\(0.667\\); rounding now would corrupt the clean surd that emerges at the end. Since \\(0 < t < 1\\) is not required (the line is infinite), any value is geometrically valid." }, { stepNumber: 8, description: "Locate the foot of the perpendicular", workingLatex: "\\mathbf{F} = \\mathbf{A} + t\\,\\mathbf{d} = \\begin{pmatrix} 2 \\\\ 1 \\\\ -3 \\end{pmatrix} + \\tfrac{2}{3}\\begin{pmatrix} 1 \\\\ -2 \\\\ 2 \\end{pmatrix} = \\begin{pmatrix} \\tfrac{8}{3} \\\\ -\\tfrac{1}{3} \\\\ -\\tfrac{5}{3} \\end{pmatrix}", explanation: "Feeding \\(t = \\tfrac{2}{3}\\) back into the line equation pins down the exact closest point \\(\\mathbf{F}\\) on the line to the origin. Distribute the scalar over all three components carefully: \\(\\tfrac{2}{3}\\times(-2) = -\\tfrac{4}{3}\\) added to \\(1\\) gives \\(-\\tfrac{1}{3}\\). As a built-in check, \\(\\mathbf{F}\\cdot\\mathbf{d}\\) should equal \\(\\mathbf{A}\\cdot\\mathbf{d} + t|\\mathbf{d}|^2\\), confirming \\(\\mathbf{F}-\\mathbf{O}\\) is perpendicular to \\(\\mathbf{d}\\)." }, { stepNumber: 9, description: "Verify perpendicularity as a check", workingLatex: "(\\mathbf{F} - \\mathbf{O}) \\cdot \\mathbf{d} = \\tfrac{8}{3}(1) + (-\\tfrac{1}{3})(-2) + (-\\tfrac{5}{3})(2) = \\tfrac{8}{3} + \\tfrac{2}{3} - \\tfrac{10}{3} = 0", explanation: "The defining property of the foot is that \\(\\mathbf{OF}\\) is perpendicular to the line, so the dot product with \\(\\mathbf{d}\\) must vanish. Getting exactly zero confirms the value of \\(t\\) is correct before we invest effort in the magnitude calculation. Skipping this check is fine in an exam, but here it cheaply guarantees the rest of the working rests on solid ground." }, { stepNumber: 10, description: "Square each coordinate of the foot", workingLatex: "\\left(\\tfrac{8}{3}\\right)^2 = \\tfrac{64}{9},\\quad \\left(-\\tfrac{1}{3}\\right)^2 = \\tfrac{1}{9},\\quad \\left(-\\tfrac{5}{3}\\right)^2 = \\tfrac{25}{9}", explanation: "The distance we want is \\(|\\mathbf{F} - \\mathbf{O}| = |\\mathbf{F}|\\), so square each coordinate. Because \\(\\mathbf{F}\\) is the foot, this length is automatically the perpendicular distance, not some slanted distance. Working over the common denominator \\(9\\) keeps the arithmetic exact and the signs irrelevant once squared." }, { stepNumber: 11, description: "Sum the squared coordinates", workingLatex: "\\tfrac{64}{9} + \\tfrac{1}{9} + \\tfrac{25}{9} = \\tfrac{90}{9} = 10", explanation: "Adding the three fractions over the shared denominator \\(9\\) gives \\(\\tfrac{90}{9}\\), which collapses to a clean integer \\(10\\). A whole number here is a reassuring sign the fraction \\(t = \\tfrac{2}{3}\\) was carried through correctly, since errors usually leave an ugly denominator behind." }, { stepNumber: 12, description: "Take the root for the distance", workingLatex: "d = \\sqrt{10}", explanation: "The shortest distance from the origin to the line is \\(\\sqrt{10} \\approx 3.16\\). Since \\(10 = 2\\times 5\\) has no square factor, the surd is already fully simplified. As a sanity check this is comfortably less than \\(|\\mathbf{AO}| = \\sqrt{4+1+9} = \\sqrt{14}\\), as it must be, because the perpendicular is always the shortest of all distances from the origin to points on the line." } ], finalAnswer: "\\(\\sqrt{10}\\)." } },
  { id: "y2v2-066", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 66", difficulty: "Challenge", questionText: "Three children pull on a rope attached to a central point with forces \\(\\mathbf{F_{1}} = 30\\mathbf{i}\\), \\(\\mathbf{F_{2}} = 20\\mathbf{j} + 15\\mathbf{k}\\), and \\(\\mathbf{F_{3}} = -10\\mathbf{i} + 5\\mathbf{k}\\) N. Find the resultant force and its magnitude.", marks: 5, examStyle: true, yearCreated: 2026, tags: ["applied", "mechanics"], workedSolution: { steps: [ { stepNumber: 1, description: "State the resultant as a vector sum", workingLatex: "\\mathbf{R} = \\mathbf{F_1} + \\mathbf{F_2} + \\mathbf{F_3}", explanation: "Forces are vectors, so their combined effect on the central point is the single resultant obtained by vector addition, not by adding magnitudes. Physically the three children's pulls superpose head-to-tail, and the rope responds as if one force \\(\\mathbf{R}\\) acted alone. Whenever several forces meet at a point, this superposition is the method to reach for." }, { stepNumber: 2, description: "List the three force vectors", workingLatex: "\\mathbf{F_1} = 30\\mathbf{i},\\quad \\mathbf{F_2} = 20\\mathbf{j} + 15\\mathbf{k},\\quad \\mathbf{F_3} = -10\\mathbf{i} + 5\\mathbf{k}", explanation: "Writing each force with explicit \\(\\mathbf{i},\\mathbf{j},\\mathbf{k}\\) labels lines up the components so none is overlooked during addition. Notice that each force is missing one or two directions: \\(\\mathbf{F_1}\\) is purely along \\(x\\), \\(\\mathbf{F_2}\\) lies in the \\(yz\\)-plane, and \\(\\mathbf{F_3}\\) has no \\(y\\)-part. Treating the absent components as zero is the safeguard against the most common error here." }, { stepNumber: 3, description: "Add the i-components", workingLatex: "R_x = 30 + 0 + (-10) = 20", explanation: "Collect every \\(\\mathbf{i}\\)-term: \\(30\\) from \\(\\mathbf{F_1}\\), nothing from \\(\\mathbf{F_2}\\), and \\(-10\\) from \\(\\mathbf{F_3}\\). The negative sign on \\(\\mathbf{F_3}\\) means that child pulls in the opposite \\(x\\)-direction, partially cancelling the first child; dropping that sign would wrongly give \\(40\\)." }, { stepNumber: 4, description: "Add the j-components", workingLatex: "R_y = 0 + 20 + 0 = 20", explanation: "Only \\(\\mathbf{F_2}\\) carries a \\(\\mathbf{j}\\)-term, so the \\(y\\)-component of the resultant is simply \\(20\\). The discipline of writing \\(0 + 20 + 0\\) rather than just \\(20\\) reminds you that the other two forces genuinely contribute nothing here, which is exactly where careless students invent phantom terms." }, { stepNumber: 5, description: "Add the k-components", workingLatex: "R_z = 0 + 15 + 5 = 20", explanation: "Both \\(\\mathbf{F_2}\\) and \\(\\mathbf{F_3}\\) push in the \\(+z\\) direction, so their \\(\\mathbf{k}\\)-parts reinforce to give \\(20\\). It is a pleasant coincidence of this problem that all three resultant components turn out equal to \\(20\\), which makes the magnitude especially clean." }, { stepNumber: 6, description: "Write the resultant force", workingLatex: "\\mathbf{R} = 20\\mathbf{i} + 20\\mathbf{j} + 20\\mathbf{k}\\ \\text{N}", explanation: "Assembling the summed components gives the resultant force vector, with units of newtons. Geometrically \\(\\mathbf{R}\\) points equally along all three axes, so it lies along the cube diagonal direction \\((1,1,1)\\) — a clue that its magnitude will involve \\(\\sqrt{3}\\)." }, { stepNumber: 7, description: "Write the magnitude formula", workingLatex: "|\\mathbf{R}| = \\sqrt{R_x^2 + R_y^2 + R_z^2}", explanation: "The magnitude is the three-dimensional Pythagoras: the length of the space-diagonal of the box with sides \\(R_x, R_y, R_z\\). This single number is the actual strength of the combined pull that the rope and anchor must withstand, independent of direction." }, { stepNumber: 8, description: "Square each component", workingLatex: "20^2 + 20^2 + 20^2 = 400 + 400 + 400 = 1200", explanation: "Squaring each component separately and then adding avoids slips with the repeated \\(20\\)s. Because all three equal \\(20\\), this is just \\(3\\times 400 = 1200\\); spotting that shortcut is a good habit but writing the terms out guards against miscounting how many forces contribute." }, { stepNumber: 9, description: "Take the root of the sum", workingLatex: "|\\mathbf{R}| = \\sqrt{1200}", explanation: "The magnitude is \\(\\sqrt{1200}\\) newtons; leaving it under the root for now lets us simplify the surd cleanly rather than committing to a rounded decimal too early. A rough mental check: \\(\\sqrt{1200}\\) sits between \\(\\sqrt{900}=30\\) and \\(\\sqrt{1600}=40\\), so the answer should land in the mid-thirties." }, { stepNumber: 10, description: "Simplify the surd", workingLatex: "\\sqrt{1200} = \\sqrt{400 \\times 3} = 20\\sqrt{3}\\ \\text{N}", explanation: "Pulling out the largest perfect-square factor \\(400\\) leaves the fully simplified surd \\(20\\sqrt{3}\\,\\text{N} \\approx 34.6\\,\\text{N}\\), which indeed lies in the mid-thirties as predicted. The factor \\(\\sqrt{3}\\) confirms the cube-diagonal geometry: a vector with three equal components of size \\(a\\) always has magnitude \\(a\\sqrt{3}\\). Extracting only \\(\\sqrt{100}\\) instead of \\(\\sqrt{400}\\) would leave \\(10\\sqrt{12}\\), which is correct but not fully simplified." } ], finalAnswer: "\\(20\\sqrt{3}\\) N." } },
  { id: "y2v2-067", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 67", difficulty: "Challenge", questionText: "The angles \\(\\alpha,\\ \\beta,\\ \\gamma\\) are the angles a vector makes with the \\(x\\)-, \\(y\\)-, \\(z\\)-axes. Given \\(\\cos\\alpha = \\tfrac{1}{3}\\), \\(\\cos\\beta = \\tfrac{2}{3}\\), find the possible values of \\(\\cos\\gamma\\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["angle", "theory"], workedSolution: { steps: [ { stepNumber: 1, description: "Recall what direction cosines mean", workingLatex: "\\cos\\alpha = \\frac{v_x}{|\\mathbf{v}|},\\quad \\cos\\beta = \\frac{v_y}{|\\mathbf{v}|},\\quad \\cos\\gamma = \\frac{v_z}{|\\mathbf{v}|}", explanation: "Each direction cosine is the component of the unit vector along one axis, so the triple \\((\\cos\\alpha,\\cos\\beta,\\cos\\gamma)\\) is precisely the normalised direction of the vector. Because that triple is a unit vector, its components are constrained, which is what makes the third cosine recoverable from the first two. Reach for this idea whenever a problem gives angles to the coordinate axes." }, { stepNumber: 2, description: "State the direction-cosine identity", workingLatex: "\\cos^2\\alpha + \\cos^2\\beta + \\cos^2\\gamma = 1", explanation: "Squaring and summing the three direction cosines reconstructs \\(\\tfrac{v_x^2+v_y^2+v_z^2}{|\\mathbf{v}|^2} = 1\\), the statement that a unit vector has length one. This identity is the single constraint linking the three axis angles, and it holds for every nonzero vector in space regardless of its magnitude. It is the key that unlocks an unknown cosine when the other two are known." }, { stepNumber: 3, description: "Note the given direction cosines", workingLatex: "\\cos\\alpha = \\tfrac{1}{3},\\quad \\cos\\beta = \\tfrac{2}{3}", explanation: "Two of the three direction cosines are supplied and the third is to be found, so the single identity in one unknown is exactly enough information. Both given values lie strictly between \\(-1\\) and \\(1\\), as every cosine must, so the data is internally consistent before we even substitute. This sanity glance rules out a mistyped question at the outset." }, { stepNumber: 4, description: "Substitute the two known cosines", workingLatex: "\\left(\\tfrac{1}{3}\\right)^2 + \\left(\\tfrac{2}{3}\\right)^2 + \\cos^2\\gamma = 1", explanation: "Insert the given values \\(\\cos\\alpha = \\tfrac{1}{3}\\) and \\(\\cos\\beta = \\tfrac{2}{3}\\), leaving \\(\\cos^2\\gamma\\) as the only unknown. We deliberately keep \\(\\cos^2\\gamma\\) (the square) rather than \\(\\cos\\gamma\\) at this stage, because the identity naturally delivers the square first." }, { stepNumber: 5, description: "Square the known cosines", workingLatex: "\\tfrac{1}{9} + \\tfrac{4}{9} + \\cos^2\\gamma = 1", explanation: "Square each fraction term by term: \\(\\left(\\tfrac{1}{3}\\right)^2 = \\tfrac{1}{9}\\) and \\(\\left(\\tfrac{2}{3}\\right)^2 = \\tfrac{4}{9}\\). A frequent slip is to halve the numerator and write \\(\\tfrac{2}{9}\\) for the second term; remember squaring multiplies the fraction by itself, so \\(2^2 = 4\\) on top." }, { stepNumber: 6, description: "Combine the known squared terms", workingLatex: "\\tfrac{1}{9} + \\tfrac{4}{9} = \\tfrac{5}{9}", explanation: "Adding over the common denominator \\(9\\) gives \\(\\tfrac{5}{9}\\), the total share of the unit length already accounted for by the \\(x\\)- and \\(y\\)-directions. Since this is less than \\(1\\), there is room left for a genuine \\(z\\)-component, so a real solution must exist." }, { stepNumber: 7, description: "Isolate cos squared gamma", workingLatex: "\\cos^2\\gamma = 1 - \\tfrac{5}{9} = \\tfrac{4}{9}", explanation: "Rearranging by subtracting \\(\\tfrac{5}{9}\\) from \\(1 = \\tfrac{9}{9}\\) leaves \\(\\cos^2\\gamma = \\tfrac{4}{9}\\). The fact that this comes out positive is a consistency check: had it been negative, the given angles would have been geometrically impossible." }, { stepNumber: 8, description: "Take the square root for cos gamma", workingLatex: "\\cos\\gamma = \\pm\\sqrt{\\tfrac{4}{9}} = \\pm\\tfrac{2}{3}", explanation: "Taking the square root must introduce both signs, because the identity only fixes \\(\\cos^2\\gamma\\), and two vectors — one tilted toward the \\(+z\\) axis, one toward the \\(-z\\) axis — share the same \\(\\alpha\\) and \\(\\beta\\). Omitting the \\(\\pm\\) silently discards a perfectly valid direction, the single most common error in this type of question." }, { stepNumber: 9, description: "Interpret the two solutions geometrically", workingLatex: "\\cos\\gamma = +\\tfrac{2}{3}\\ (\\gamma \\approx 48.2^{\\circ}),\\quad \\cos\\gamma = -\\tfrac{2}{3}\\ (\\gamma \\approx 131.8^{\\circ})", explanation: "The positive root corresponds to a vector making an acute angle with the \\(+z\\) axis, while the negative root makes an obtuse angle, pointing into the lower half-space. Both are legitimate vectors consistent with the data, which is why the question asks for the possible values rather than a single answer. Quoting the two angles makes the geometric meaning of the \\(\\pm\\) concrete." }, { stepNumber: 10, description: "State both admissible values", workingLatex: "\\cos\\gamma = \\pm\\tfrac{2}{3}", explanation: "The final answer is the pair \\(\\cos\\gamma = \\pm\\tfrac{2}{3}\\), and both must be quoted to be complete. As a closing check, substituting either value back into the identity gives \\(\\tfrac{1}{9} + \\tfrac{4}{9} + \\tfrac{4}{9} = 1\\), confirming the squared cosines sum to unity exactly as required." } ], finalAnswer: "\\(\\cos\\gamma = \\pm\\tfrac{2}{3}\\)." } },
  { id: "y2v2-068", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 68", difficulty: "Challenge", questionText: "A projectile has velocity \\(\\mathbf{v}(t) = (3, 4 - 10t, 0)\\) m/s. Find the direction (angle above horizontal) at \\(t = 0\\) and the time at which velocity is horizontal.", marks: 6, examStyle: true, yearCreated: 2026, tags: ["applied", "kinematics"], workedSolution: { steps: [ { stepNumber: 1, description: "Evaluate the velocity at t = 0", workingLatex: "\\mathbf{v}(0) = (3,\\ 4 - 10(0),\\ 0) = (3,\\ 4,\\ 0)", explanation: "Substituting \\(t = 0\\) into each component gives the launch velocity at the instant of release. The \\(z\\)-component stays zero for all time, so the whole motion is confined to the vertical \\(xy\\)-plane, and we can treat the problem as effectively two-dimensional. This simplification is what lets us speak of a single 'angle above horizontal'." }, { stepNumber: 2, description: "Identify horizontal and vertical components", workingLatex: "v_x = 3\\ (\\text{horizontal}),\\quad v_y = 4\\ (\\text{vertical})", explanation: "By convention the \\(x\\)-direction is horizontal ground-speed and the \\(y\\)-direction is vertical climb-speed. The \\(-10t\\) inside \\(v_y\\) is gravity steadily eroding the upward speed, which is why only \\(v_y\\) changes with time while \\(v_x\\) stays a constant \\(3\\). Identifying which axis is which is essential before forming any angle." }, { stepNumber: 3, description: "Set up the tangent of the launch angle", workingLatex: "\\tan\\alpha = \\frac{v_y}{v_x} = \\frac{4}{3}", explanation: "The angle above the horizontal sits in the right triangle whose opposite side is the vertical speed and adjacent side is the horizontal speed, so \\(\\tan\\alpha = v_y/v_x\\). Writing the ratio the wrong way up, \\(v_x/v_y\\), returns the complementary angle measured from the vertical instead — a very common slip. Here the ratio \\(\\tfrac{4}{3}\\) signals the classic 3-4-5 triangle, hinting at a familiar angle." }, { stepNumber: 4, description: "Take the inverse tangent", workingLatex: "\\alpha = \\tan^{-1}\\left(\\tfrac{4}{3}\\right) \\approx 53.1^{\\circ}", explanation: "Applying \\(\\tan^{-1}\\) recovers the angle from its tangent, giving about \\(53.1^{\\circ}\\), the well-known angle of the 3-4-5 right triangle. Make sure the calculator is in degree mode, since radian mode would return \\(0.927\\) and look plausibly small. The launch is steeper than \\(45^{\\circ}\\), consistent with the vertical speed \\(4\\) exceeding the horizontal speed \\(3\\)." }, { stepNumber: 5, description: "State the launch direction answer", workingLatex: "\\alpha \\approx 53.1^{\\circ}\\ \\text{above horizontal}", explanation: "This is the answer to the first part: at release the projectile travels about \\(53.1^{\\circ}\\) above the horizontal. The angle is well below \\(90^{\\circ}\\), confirming the motion is a genuine forward arc rather than a vertical shot, which matches a nonzero horizontal speed of \\(3\\,\\text{m/s}\\)." }, { stepNumber: 6, description: "State the condition for horizontal velocity", workingLatex: "\\text{velocity horizontal} \\iff v_y = 0", explanation: "A velocity is horizontal precisely when it has no vertical part, so the condition is \\(v_y = 0\\); the horizontal component \\(v_x = 3\\) is constant and never vanishes, so it plays no role. Physically this is the apex of the flight, the single moment when the projectile stops rising and has not yet begun to fall." }, { stepNumber: 7, description: "Write the equation for that instant", workingLatex: "4 - 10t = 0", explanation: "Setting the vertical-velocity expression equal to zero turns the physical condition into a simple linear equation in \\(t\\). The term \\(-10t\\) encodes gravitational acceleration of about \\(10\\,\\text{m/s}^2\\) acting downward, steadily cancelling the initial upward \\(4\\,\\text{m/s}\\)." }, { stepNumber: 8, description: "Rearrange for t", workingLatex: "10t = 4", explanation: "Adding \\(10t\\) to both sides isolates the term containing the unknown, a routine but worth-doing-cleanly rearrangement. Keeping the equation balanced here prevents sign errors that would push the apex to a negative, unphysical time." }, { stepNumber: 9, description: "Solve for the time", workingLatex: "t = \\frac{4}{10} = 0.4\\ \\text{s}", explanation: "Dividing gives \\(t = 0.4\\,\\text{s}\\), the instant of peak height where the projectile moves purely horizontally. The answer is positive and small, exactly as expected for the top of a short, fast trajectory; a negative result would have signalled an arithmetic sign error in the rearrangement." }, { stepNumber: 10, description: "Confirm the velocity is horizontal there", workingLatex: "\\mathbf{v}(0.4) = (3,\\ 4 - 10(0.4),\\ 0) = (3,\\ 0,\\ 0)", explanation: "Substituting \\(t = 0.4\\) back into the velocity confirms the vertical component is exactly zero while the horizontal component remains \\(3\\,\\text{m/s}\\), so the motion is purely horizontal as claimed. This back-substitution is the cleanest possible check on the time, since it reproduces the very condition we imposed. The surviving \\(v_x = 3\\) also reassures us the projectile is still moving, not momentarily at rest." } ], finalAnswer: "\\(\\approx 53.1^{\\circ}\\); \\(t = 0.4\\) s." } },
  { id: "y2v2-069", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 69", difficulty: "Challenge", questionText: "Point \\(P\\) has position vector \\(\\mathbf{p} = 2\\mathbf{i} + 3\\mathbf{j} - \\mathbf{k}\\). Find the reflection of \\(P\\) in the \\(xy\\)-plane.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["reflection"], workedSolution: { steps: [ { stepNumber: 1, description: "Understand reflection as a perpendicular flip", workingLatex: "P \\;\\xrightarrow{\\text{reflect in } xy}\\; P',\\quad PP' \\perp (xy\\text{-plane})", explanation: "A reflection sends a point to the mirror-image position on the opposite side of the plane, with the plane bisecting the segment \\(PP'\\) at right angles. The strategy is therefore to find which coordinate measures distance perpendicular to the mirror and reverse only that one. Recognising reflection problems by this perpendicular-flip picture keeps you from accidentally moving the wrong coordinate." }, { stepNumber: 2, description: "Write P in coordinate form", workingLatex: "P = (2,\\ 3,\\ -1)", explanation: "Translating \\(\\mathbf{p} = 2\\mathbf{i} + 3\\mathbf{j} - \\mathbf{k}\\) into a coordinate triple lets us apply the reflection rule one component at a time. Note that \\(-\\mathbf{k}\\) means the \\(z\\)-coordinate is \\(-1\\), so \\(P\\) sits one unit below the \\(xy\\)-plane. Picturing its location relative to the mirror plane makes the result easy to anticipate." }, { stepNumber: 3, description: "Identify the perpendicular distance to the plane", workingLatex: "z\\text{-coordinate} = -1 \\;\\Rightarrow\\; P\\ \\text{lies } 1\\ \\text{unit below the } xy\\text{-plane}", explanation: "The signed perpendicular distance of \\(P\\) from the \\(xy\\)-plane is just its \\(z\\)-coordinate, here \\(-1\\), the minus sign meaning below the plane. The image will sit the same distance on the other side, so we can predict the answer's \\(z\\)-coordinate will be \\(+1\\) before doing any algebra. This forecast is a useful guard against sign slips in the steps that follow." }, { stepNumber: 4, description: "State the reflection rule for the xy-plane", workingLatex: "(x,\\ y,\\ z) \\mapsto (x,\\ y,\\ -z)", explanation: "The \\(xy\\)-plane is the set of points with \\(z = 0\\), so reflecting across it leaves the in-plane coordinates \\(x\\) and \\(y\\) untouched and simply flips the sign of the out-of-plane coordinate \\(z\\). The general principle is that reflection negates exactly the coordinate perpendicular to the mirror; choosing the wrong coordinate to negate is the dominant error in these questions. Recognise the plane by which variable is set to zero in its name." }, { stepNumber: 5, description: "Keep the x-coordinate unchanged", workingLatex: "x' = 2", explanation: "The \\(x\\)-axis lies inside the mirror plane, so distances measured along it are unaffected by the reflection. Points already in the plane map to themselves, and \\(x\\) is one of those in-plane directions." }, { stepNumber: 6, description: "Keep the y-coordinate unchanged", workingLatex: "y' = 3", explanation: "Likewise the \\(y\\)-direction lies within the \\(xy\\)-plane, so the \\(y\\)-coordinate is preserved at \\(3\\). Only the direction perpendicular to the plane can change under this reflection." }, { stepNumber: 7, description: "Negate the z-coordinate", workingLatex: "z' = -(-1) = 1", explanation: "The \\(z\\)-direction is perpendicular to the mirror, so its sign flips: a point one unit below the plane maps to its mirror image one unit above. Watch the double negative here — negating \\(-1\\) gives \\(+1\\), not \\(-1\\) — which is the precise spot where careless sign handling goes wrong." }, { stepNumber: 8, description: "Write the reflected point", workingLatex: "P' = (2,\\ 3,\\ 1)", explanation: "Reassembling the transformed coordinates gives the image \\(P' = (2,3,1)\\), matching the \\(z = +1\\) we forecast earlier. This is the coordinate-form answer the question asks for." }, { stepNumber: 9, description: "Express the image as a position vector", workingLatex: "\\mathbf{p'} = 2\\mathbf{i} + 3\\mathbf{j} + \\mathbf{k}", explanation: "Since the original point was given in \\(\\mathbf{i},\\mathbf{j},\\mathbf{k}\\) form, it is tidy to present the image the same way. Only the \\(\\mathbf{k}\\) term changed sign, from \\(-\\mathbf{k}\\) to \\(+\\mathbf{k}\\), exactly as the reflection rule dictates." }, { stepNumber: 10, description: "Check the midpoint lies in the plane", workingLatex: "\\text{midpoint of } PP' = \\left(2,\\ 3,\\ \\tfrac{-1+1}{2}\\right) = (2,\\ 3,\\ 0)", explanation: "The defining property of a reflection is that the mirror plane bisects \\(PP'\\), so the midpoint must have \\(z = 0\\) and lie in the \\(xy\\)-plane. Computing it gives \\((2,3,0)\\), whose zero \\(z\\)-coordinate confirms the image is correctly placed. This midpoint test is the most reliable way to catch a sign error in any reflection answer." } ], finalAnswer: "\\((2, 3, 1)\\)." } },
  { id: "y2v2-070", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 70", difficulty: "Challenge", questionText: "Two ships sail from the same harbour. Ship 1 with velocity \\(12\\mathbf{i} + 5\\mathbf{j}\\) km/h; ship 2 with \\(3\\mathbf{i} + 4\\mathbf{j}\\) km/h. Find the distance between them after 1 hour.", marks: 5, examStyle: true, yearCreated: 2026, tags: ["applied", "kinematics"], workedSolution: { steps: [ { stepNumber: 1, description: "State position equals velocity times time", workingLatex: "\\mathbf{r} = \\mathbf{r_0} + \\mathbf{v}\\,t,\\quad \\mathbf{r_0} = \\mathbf{0}", explanation: "With constant velocity and a common starting point at the harbour, each ship's position is simply velocity multiplied by elapsed time. Taking the harbour as the origin means \\(\\mathbf{r_0} = \\mathbf{0}\\), so the formula reduces to \\(\\mathbf{r} = \\mathbf{v}t\\). This linear-motion model is the natural starting point whenever objects move steadily from a shared point." }, { stepNumber: 2, description: "Find ship 1 position after 1 hour", workingLatex: "\\mathbf{r_1} = (12\\mathbf{i} + 5\\mathbf{j})(1) = 12\\mathbf{i} + 5\\mathbf{j}", explanation: "Multiplying ship 1's velocity by \\(t = 1\\) hour places it at \\((12, 5)\\). The numbers happen to equal the velocity components because exactly one hour has passed, but it is worth writing the \\(\\times 1\\) explicitly so the method generalises to other times. Units of km follow from km/h times hours." }, { stepNumber: 3, description: "Find ship 2 position after 1 hour", workingLatex: "\\mathbf{r_2} = (3\\mathbf{i} + 4\\mathbf{j})(1) = 3\\mathbf{i} + 4\\mathbf{j}", explanation: "Identically, ship 2 reaches \\((3, 4)\\) after one hour. Because both positions are referred to the same origin, we can compare them directly to find their separation without any further translation of coordinates." }, { stepNumber: 4, description: "Form the displacement between ships", workingLatex: "\\mathbf{r_1} - \\mathbf{r_2} = (12 - 3)\\mathbf{i} + (5 - 4)\\mathbf{j} = 9\\mathbf{i} + \\mathbf{j}", explanation: "The vector from one ship to the other is the difference of their position vectors, found by subtracting component by component. The order of subtraction does not matter for the eventual distance, since reversing it only flips the vector's direction, not its length. This separation vector \\(9\\mathbf{i} + \\mathbf{j}\\) is what we now measure." }, { stepNumber: 5, description: "Write the magnitude formula", workingLatex: "d = |\\mathbf{r_1} - \\mathbf{r_2}| = \\sqrt{9^2 + 1^2}", explanation: "The distance between the ships is the length of their separation vector, given by the Pythagorean magnitude of its components. In two dimensions this is just the hypotenuse of a right triangle with legs \\(9\\) and \\(1\\). Setting the formula out first makes clear why we square, add, and root in the next three steps." }, { stepNumber: 6, description: "Square each component of the displacement", workingLatex: "9^2 = 81,\\quad 1^2 = 1", explanation: "Square each component of the separation. The lopsided values \\(81\\) and \\(1\\) already hint that the ships are spread far apart along \\(x\\) but nearly level in \\(y\\), so the distance will be only slightly more than \\(9\\)." }, { stepNumber: 7, description: "Sum the squared components", workingLatex: "81 + 1 = 82", explanation: "Adding the squares gives \\(82\\), the quantity under the root. Keeping it as an exact integer avoids premature rounding and sets up a clean surd answer." }, { stepNumber: 8, description: "Take the root for the distance", workingLatex: "d = \\sqrt{82}\\ \\text{km}", explanation: "The exact distance is \\(\\sqrt{82}\\,\\text{km}\\). Since \\(82 = 2\\times 41\\) contains no square factor, the surd is already in simplest form and cannot be reduced further. Leaving the exact value is preferable when a question does not insist on a decimal." }, { stepNumber: 9, description: "Convert to a decimal", workingLatex: "\\sqrt{82} \\approx 9.06\\ \\text{km}", explanation: "Evaluating gives roughly \\(9.06\\,\\text{km}\\), comfortably just above \\(9\\) exactly as the dominant \\(81\\) under the root predicted. Quoting two or three significant figures is sensible for a physical distance; rounding to a whole \\(9\\) km would discard meaningful precision." }, { stepNumber: 10, description: "Sanity-check against the components", workingLatex: "9 < \\sqrt{82} < 10 = \\sqrt{81} + 1", explanation: "The final separation \\(\\sqrt{82} \\approx 9.06\\,\\text{km}\\) sits just above the larger leg \\(9\\) and below the straight sum \\(10\\) of the two legs, exactly as the triangle inequality demands. Because the \\(y\\)-gap of \\(1\\,\\text{km}\\) is tiny next to the \\(x\\)-gap of \\(9\\,\\text{km}\\), the diagonal distance barely exceeds \\(9\\), confirming the answer is physically reasonable and free of arithmetic slips." } ], finalAnswer: "\\(\\sqrt{82}\\) km \\(\\approx 9.06\\) km." } },
  { id: "y2v2-071", topicRef: "y2v2", topicTitle: "Calculating Vectors in 3D 71", difficulty: "Challenge", questionText: "A plane flies from \\(A(0, 0, 0)\\) to \\(B(60, 80, 100)\\) km in 30 minutes at constant velocity. (a) Find the velocity. (b) Find the speed in km/h. (c) Find the total distance travelled.", marks: 7, examStyle: true, yearCreated: 2026, tags: ["applied", "kinematics"], workedSolution: { steps: [ { stepNumber: 1, description: "Form the displacement from A to B", workingLatex: "\\mathbf{AB} = \\begin{pmatrix} 60 \\\\ 80 \\\\ 100 \\end{pmatrix} - \\begin{pmatrix} 0 \\\\ 0 \\\\ 0 \\end{pmatrix} = \\begin{pmatrix} 60 \\\\ 80 \\\\ 100 \\end{pmatrix}", explanation: "Velocity is displacement divided by time, so the first task is the displacement \\(\\mathbf{AB} = \\mathbf{B} - \\mathbf{A}\\). Because \\(A\\) is the origin this conveniently equals the coordinates of \\(B\\). This single vector captures both the direction of flight and the straight-line distance covered." }, { stepNumber: 2, description: "Convert the time to hours", workingLatex: "t = 30\\ \\text{min} = 0.5\\ \\text{h}", explanation: "Since the speed is required in km/h, the time must be in hours before any division; \\(30\\) minutes is half an hour. Forgetting this conversion and dividing by \\(30\\) instead of \\(0.5\\) is the single biggest trap in this question and would shrink every answer sixtyfold. Always match your time units to the units demanded in the answer." }, { stepNumber: 3, description: "Divide displacement by time", workingLatex: "\\mathbf{v} = \\frac{1}{0.5}\\begin{pmatrix} 60 \\\\ 80 \\\\ 100 \\end{pmatrix} = 2\\begin{pmatrix} 60 \\\\ 80 \\\\ 100 \\end{pmatrix}", explanation: "Dividing the displacement by \\(t = 0.5\\,\\text{h}\\) is the same as multiplying each component by \\(2\\), because dividing by a half doubles. The scalar must be applied to every component, not just one. Velocity inherits the direction of \\(\\mathbf{AB}\\) and only its size is rescaled by the timing." }, { stepNumber: 4, description: "State the velocity vector", workingLatex: "\\mathbf{v} = (120,\\ 160,\\ 200)\\ \\text{km/h}", explanation: "This is the constant velocity vector that answers part (a). Notice the components are in the same ratio \\(60:80:100 = 3:4:5\\) as the displacement, confirming the direction of travel is unchanged and only the magnitude has been set by the half-hour duration." }, { stepNumber: 5, description: "Square each velocity component", workingLatex: "120^2 = 14400,\\quad 160^2 = 25600,\\quad 200^2 = 40000", explanation: "Speed is the magnitude \\(|\\mathbf{v}|\\), reached by the three-dimensional Pythagoras, so square each component separately to keep the large numbers manageable. Doing each square in isolation guards against arithmetic slips that are easy with four- and five-digit values." }, { stepNumber: 6, description: "Sum the squared components", workingLatex: "14400 + 25600 + 40000 = 80000", explanation: "Adding the three squares gives \\(80000\\), the value under the root for the speed. The round total is a hint that a neat surd will emerge, since \\(80000 = 40000 \\times 2\\)." }, { stepNumber: 7, description: "Take the root and simplify the surd", workingLatex: "|\\mathbf{v}| = \\sqrt{80000} = \\sqrt{40000 \\times 2} = 200\\sqrt{2}", explanation: "Extracting the perfect square \\(40000 = 200^2\\) leaves the exact speed \\(200\\sqrt{2}\\,\\text{km/h}\\). Keeping the answer as a surd at this stage preserves full precision for the distance calculation that follows. The clean factor of \\(\\sqrt{2}\\) is no accident; it reflects the simple integer ratios of the velocity components." }, { stepNumber: 8, description: "Convert the speed to a decimal", workingLatex: "200\\sqrt{2} \\approx 282.84\\ \\text{km/h}", explanation: "Evaluating \\(200\\sqrt{2}\\) gives about \\(282.84\\,\\text{km/h}\\), answering part (b). A quick check: the largest single component is \\(200\\), and the full speed should exceed it but stay below the sum \\(480\\), which \\(282.84\\) comfortably does." }, { stepNumber: 9, description: "Relate distance to speed and time", workingLatex: "\\text{distance} = |\\mathbf{v}| \\times t = 200\\sqrt{2} \\times 0.5", explanation: "For straight-line motion the total path length equals speed times time, and because the velocity is constant there is no curving to lengthen the route. Equivalently the distance is just \\(|\\mathbf{AB}|\\), the straight gap between \\(A\\) and \\(B\\); using either route should agree, which doubles as a check." }, { stepNumber: 10, description: "Compute the total distance", workingLatex: "\\text{distance} = 100\\sqrt{2} \\approx 141.42\\ \\text{km}", explanation: "Multiplying \\(200\\sqrt{2}\\) by \\(0.5\\) gives \\(100\\sqrt{2} \\approx 141.42\\,\\text{km}\\), answering part (c). As a final consistency check this matches \\(|\\mathbf{AB}| = \\sqrt{60^2+80^2+100^2} = \\sqrt{20000} = 100\\sqrt{2}\\), confirming the whole chain of working hangs together." } ], finalAnswer: "\\(\\mathbf{v} = (120, 160, 200)\\) km/h; \\(\\approx 282.84\\) km/h; distance \\(\\approx 141.42\\) km." } },
];
